# --- Smart dependency bootstrap (Windows-friendly) ---
def _ensure_runtime_dependencies():
    required = {
        "firebase_admin": "firebase-admin>=6.5,<8",
        "pyotp": "pyotp>=2.9,<3",
        "bs4": "beautifulsoup4>=4.12,<5",
    }
    missing = []
    import importlib.util
    for module, package in required.items():
        if importlib.util.find_spec(module) is None:
            missing.append(package)
    if not missing:
        return
    import subprocess
    cmd = [sys.executable, "-m", "pip", "install", "--disable-pip-version-check", "--no-input", *missing]
    result = subprocess.run(
        cmd,
        check=False,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    if result.returncode != 0:
        raise RuntimeError(
            "Automatic dependency installation failed; install required packages before startup."
        )

