# One Telegram bot token must have exactly one getUpdates poller.  A duplicate
# process makes Telegram return 409 conflicts; the former tight retry loop then
# consumed CPU and neither process could reliably answer users.
_BOT_INSTANCE_SOCKET = None
_BOT_INSTANCE_PORT = 39000 + (int(hashlib.sha256(TOKEN.encode("utf-8")).hexdigest()[:8], 16) % 1000)

def _acquire_bot_instance_lock():
    """Keep one local polling process for this bot token."""
    global _BOT_INSTANCE_SOCKET
    if _BOT_INSTANCE_SOCKET is not None:
        return True
    try:
        lock_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        lock_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 0)
        lock_socket.bind(("127.0.0.1", _BOT_INSTANCE_PORT))
        lock_socket.listen(1)
        _BOT_INSTANCE_SOCKET = lock_socket
        return True
    except OSError:
        return False

