def _firebase_credential_candidates():
    candidates = []
    if firebase_credentials_json:
        candidates.append(("FIREBASE_CREDENTIALS_JSON", firebase_credentials_json))
    for label, path in (("FIREBASE_CREDENTIALS_FILE", firebase_credentials_file),
                        ("GOOGLE_APPLICATION_CREDENTIALS", GOOGLE_APPLICATION_CREDENTIALS),
                        ("DEFAULT_SERVICE_ACCOUNT", str(BASE_DIR / "firebase_frd_prime_new.json"))):
        if path and os.path.isfile(path):
            try:
                candidates.append((label, Path(path).read_text(encoding="utf-8")))
            except Exception as exc:
                # Keep credential details out of the production terminal; the
                # bounded health check below reports only connection status.
                pass
    candidates.append(("EMBEDDED_FIREBASE_CREDENTIALS", json.dumps(EMBEDDED_FIREBASE_CREDENTIALS)))
    return candidates

def _initialize_firebase():
    global db, FIREBASE_INIT_ERROR
    errors = []
    try:
        app = firebase_admin.get_app()
        db = firestore.client(app=app)
        return True
    except Exception:
        pass
    for label, raw in _firebase_credential_candidates():
        try:
            cred = credentials.Certificate(json.loads(raw))
            app = firebase_admin.initialize_app(cred, {"projectId": FIRESTORE_PROJECT_ID})
            db = firestore.client(app=app)
            FIREBASE_INIT_ERROR = ""
            return True
        except Exception as exc:
            errors.append(f"{label}: {type(exc).__name__}: {exc}")
            try:
                app = firebase_admin.get_app()
                db = firestore.client(app=app)
                FIREBASE_INIT_ERROR = ""
                return True
            except Exception:
                pass
    FIREBASE_INIT_ERROR = " | ".join(errors)[-1800:]
    # Startup health output is emitted once by the background bootstrap.
    db = None
    return False

_initialize_firebase()

FIREBASE_INITIALIZED = db is not None

FIREBASE_HEALTH_LOCK = threading.RLock()
FIREBASE_HEALTH = {"ok": None, "message": "not checked", "project": "", "checked_at": 0.0}

def _verify_firebase_connection(timeout=5):
    """Non-blocking-ish Firebase health check with a hard caller wait cap.

    Google auth metadata refresh can outlive the Firestore stream timeout (for
    example when an invalid service account returns ``invalid_grant``). Run the
    network operation on a daemon thread and never hold bot startup longer than
    the configured cap. The worker may finish later, but it cannot block the
    Telegram poller.
    """
    if not db:
        return {"ok": False, "message": FIREBASE_INIT_ERROR or "Firebase client is not initialized."}

    try:
        hard_timeout = max(1.0, min(float(timeout or 5), 8.0))
    except Exception:
        hard_timeout = 5.0

    result = {}
    done = threading.Event()

    def _probe():
        try:
            iterator = db.collection("users").limit(1).stream(timeout=3)
            next(iterator, None)
            project_id = ""
            try:
                project_id = firebase_admin.get_app().project_id or ""
            except Exception:
                pass
            result.update({"ok": True, "project": project_id})
        except Exception as exc:
            result.update({"ok": False, "message": str(exc)[:500]})
        finally:
            done.set()

    threading.Thread(target=_probe, daemon=True, name="firebase-health-probe").start()
    done.wait(hard_timeout)
    if not done.is_set():
        msg = f"Firebase health check timed out after {hard_timeout:.1f}s; bot startup is continuing."
        with FIREBASE_HEALTH_LOCK:
            FIREBASE_HEALTH.update({"ok": False, "message": msg, "checked_at": time.time()})
        return {"ok": False, "message": msg}

    with FIREBASE_HEALTH_LOCK:
        FIREBASE_HEALTH.update({
            "ok": bool(result.get("ok")),
            "message": str(result.get("message", "")),
            "project": str(result.get("project", "")),
            "checked_at": time.time(),
        })
    return result


