    store = bot_settings.setdefault(RANGE_AUTO_SERVICE_MODES, {})
    if not isinstance(store, dict):
        store = {}
        bot_settings[RANGE_AUTO_SERVICE_MODES] = store
    if provider is None:
        return store
    p = str(provider or "").strip().upper()
