def _range_force_delete_store(provider=None):
    """Return the persisted per-service/country Force Delete store."""
    store = bot_settings.setdefault(RANGE_FORCE_DELETE_MODES, {})
    if not isinstance(store, dict):
        store = {}
        bot_settings[RANGE_FORCE_DELETE_MODES] = store
    if provider is None:
        return store
    p = str(provider or "").strip().upper()
    node = store.setdefault(p, {})
    if not isinstance(node, dict):
        node = {}
        store[p] = node
    return node

def _range_pair_key(service, country):
    return f"{_normalize_label(service)}::{_normalize_label(country)}"

def _canonical_fb_forgot_service_name(value):
    """Canonicalize every user-facing Facebook Forgot alias to one identity.

    Internal provider tag ``Fb Clone`` is deliberately not changed here.
    This helper is intentionally strict about the Facebook namespace so names
    such as ``FB Forgot_ZNX`` or ``FB Forgot Premium`` cannot create a second
    user-facing service button.
    """
    raw = str(value or "").strip()
    norm = _normalize_label(raw)
    if not norm:
        return raw
    aliases = {
        "fb pc clone",
        "facebook pc clone",
        "facebook clone",
        "fb clone",
        "pc clone",
        "fb forgot",
    }
    if norm in aliases:
        return FB_FORGOT_CANONICAL_NAME

    # Remove only known provider/display suffixes before the identity check.
    base = re.sub(r"(?:[_\- ]+)(?:ZNX|VTX|STEX|VIP|PREMIUM|OFFICIAL)$", "", norm, flags=re.IGNORECASE).strip(" _-")
    if base in aliases:
        return FB_FORGOT_CANONICAL_NAME
    # Common decorated labels from older configs (emoji/html/font-normalized by
    # _normalize_label) are canonicalized when the dedicated token is present.
    if re.search(r"(?<![a-z0-9])fb\s*(?:forgot|pc\s*clone|clone)(?![a-z0-9])", norm):
        return FB_FORGOT_CANONICAL_NAME
    if re.search(r"(?<![a-z0-9])facebook\s*(?:forgot|pc\s*clone|clone)(?![a-z0-9])", norm):
        return FB_FORGOT_CANONICAL_NAME
    return raw


def _merge_service_country_maps(target, source):
    """Merge service->country->ranges dictionaries without dropping state."""
    changed = False
    if not isinstance(target, dict) or not isinstance(source, dict):
        return changed
    for country, ranges in source.items():
        if country not in target:
            target[country] = ranges
            changed = True
            continue
        existing = target.get(country)
        if isinstance(existing, list) and isinstance(ranges, (list, tuple, set)):
            before = list(existing)
            for value in ranges:
                if value not in existing:
                    existing.append(value)
            changed = changed or before != existing
        elif existing in (None, "", []) and ranges not in (None, "", []):
            target[country] = ranges
            changed = True
    return changed


def _migrate_legacy_fb_forgot_state():
    """Migrate legacy Facebook clone service keys to one canonical FB Forgot entry.

    This removes duplicate user-facing service buttons after upgrades while
    retaining all existing countries/ranges and automation overrides.
    """
    changed = False
    service_maps = ("stex_services", "voltx_services", "zenex_services")

    for source_key in service_maps:
        source = bot_settings.get(source_key, {}) or {}
        if not isinstance(source, dict):
            continue
        rebuilt = {}
        for raw_service, countries in source.items():
            canonical = _canonical_fb_forgot_service_name(raw_service)
            if not canonical:
                continue
            if canonical not in rebuilt:
                rebuilt[canonical] = countries if isinstance(countries, dict) else {}
                if canonical != raw_service:
                    changed = True
            else:
                changed = _merge_service_country_maps(rebuilt[canonical], countries) or changed
                if canonical != raw_service:
                    changed = True
        if rebuilt != source:
            bot_settings[source_key] = rebuilt
            changed = True

    # Migrate persisted service-level and pair-level automation overrides.
    for store_key in (RANGE_AUTO_SERVICE_MODES,):
        store = bot_settings.get(store_key, {}) or {}
        if not isinstance(store, dict):
            continue
        for provider, node in list(store.items()):
            if not isinstance(node, dict):
                continue
            for raw_service, value in list(node.items()):
                canonical = _canonical_fb_forgot_service_name(raw_service)
                if canonical != raw_service:
                    node[_normalize_label(canonical)] = value
                    node.pop(raw_service, None)
                    changed = True

    for store_key in (RANGE_AUTO_MODES, RANGE_FORCE_DELETE_MODES):
        store = bot_settings.get(store_key, {}) or {}
        if not isinstance(store, dict):
            continue
        for provider, node in list(store.items()):
            if not isinstance(node, dict):
                continue
            for raw_key, value in list(node.items()):
                if "::" not in str(raw_key):
                    continue
                raw_service, raw_country = str(raw_key).split("::", 1)
                canonical = _canonical_fb_forgot_service_name(raw_service)
                if canonical != raw_service:
                    new_key = _range_pair_key(canonical, raw_country)
                    node[new_key] = value
                    node.pop(raw_key, None)
                    changed = True

    # Canonicalize committed range metadata so terminal/UI never resurrect the legacy label.
    meta = bot_settings.get("zenex_range_meta", {}) or {}
    if isinstance(meta, dict):
        for key, row in list(meta.items()):
            if not isinstance(row, dict):
                continue
            canonical = _canonical_fb_forgot_service_name(row.get("service", ""))
            if canonical and canonical != str(row.get("service", "") or "").strip():
                new_row = dict(row)
                new_row["service"] = canonical
                new_key = _range_pair_key(canonical, new_row.get("country", ""))
                if new_key != key:
                    meta.pop(key, None)
                    meta[new_key] = new_row
                else:
                    meta[key] = new_row
                changed = True

    # Canonicalize active-menu contexts too, so persisted live menus do not
    # republish the old label after restart.
    live_ui = bot_settings.get("live_ui_messages", {}) or {}
    if isinstance(live_ui, dict):
        for uid, entry in live_ui.items():
            if not isinstance(entry, dict):
                continue
            if "service" in entry:
                canonical = _canonical_fb_forgot_service_name(entry.get("service"))
                if canonical and canonical != entry.get("service"):
                    entry["service"] = canonical
                    changed = True

    return changed


def _range_service_key(service):
    return _normalize_label(service)

def _get_service_auto_range_override(provider, service):
    node = _range_service_mode_store(provider)
    value = node.get(_range_service_key(service))
    return value if isinstance(value, bool) else None

def _set_service_auto_range(provider, service, enabled):
    node = _range_service_mode_store(provider)
    key = _range_service_key(service)
    if enabled is None:
        node.pop(key, None)
        result = None
    else:
        result = bool(enabled)
        node[key] = result
    save_db_sync()
    return result

def _toggle_service_auto_range(provider, service):
    current = _get_service_auto_range_override(provider, service)
    next_value = True if current is None else False if current else None
    return _set_service_auto_range(provider, service, next_value)

def _is_pair_auto_range_enabled(provider, service, country):
    """Resolve auto-range using country > service > provider precedence.

    Configured pairs default to ON, so newly-created manual service/country
    entries immediately participate in the Top-1 range optimizer.
    """
    p = str(provider or "").strip().upper()
    pair_key = _range_pair_key(service, country)
    pair_store = _range_mode_store(p)
    if pair_key in pair_store:
        return bool(pair_store[pair_key])
    service_override = _get_service_auto_range_override(p, service)
    if service_override is not None:
        return service_override
    source_key = {"STEX":"stex_services","VOLTX":"voltx_services","ZENEX":"zenex_services"}.get(p)
    service_exists = isinstance(bot_settings.get(source_key), dict) and service in bot_settings.get(source_key, {}) if source_key else False
    if service_exists:
        return True
    return bool(bot_settings.get(f"{p.lower()}_auto", False))

def _get_pair_auto_range_state(provider, service, country):
    p = str(provider or "").strip().upper()
    pair_key = _range_pair_key(service, country)
    pair_store = _range_mode_store(p)
    if pair_key in pair_store:
        return bool(pair_store[pair_key]), "country"
    service_override = _get_service_auto_range_override(p, service)
    if service_override is not None:
        return service_override, "service"
    source_key = {"STEX":"stex_services","VOLTX":"voltx_services","ZENEX":"zenex_services"}.get(p)
    service_exists = isinstance(bot_settings.get(source_key), dict) and service in bot_settings.get(source_key, {}) if source_key else False
    if service_exists:
        return True, "default"
    return bool(bot_settings.get(f"{p.lower()}_auto", False)), "provider"

def _set_pair_auto_range(provider, service, country, enabled):
    p = str(provider or "").strip().upper()
    _range_mode_store(p)[_range_pair_key(service, country)] = bool(enabled)
    save_db_sync()
    return bool(enabled)

def _clear_pair_auto_range_override(provider, service, country):
    p = str(provider or "").strip().upper()
    _range_mode_store(p).pop(_range_pair_key(service, country), None)
    save_db_sync()

def _is_pair_force_delete_enabled(provider, service, country):
    p = str(provider or "").strip().upper()
    # AUTO OFF is an unconditional manual-country lock. Even if an old/stale
    # Force Delete value remains in storage, it must never delete a manual pair.
    if not _is_pair_auto_range_enabled(p, service, country):
        return False
    key = _range_pair_key(service, country)
    store = _range_force_delete_store(p)
    value = store.get(key)
    return bool(value) if isinstance(value, bool) else True

def _set_pair_force_delete(provider, service, country, enabled):
    p = str(provider or "").strip().upper()
    _range_force_delete_store(p)[_range_pair_key(service, country)] = bool(enabled)
    save_db_sync()
    return bool(enabled)

def _toggle_pair_force_delete(provider, service, country):
    enabled = not _is_pair_force_delete_enabled(provider, service, country)
    return _set_pair_force_delete(provider, service, country, enabled)

def _provider_has_pair_auto_modes(provider):
    pair_node = _range_mode_store(provider)
    service_node = _range_service_mode_store(provider)
    # A configured service/country itself is enough to make the optimizer eligible.
    p = str(provider or "").strip().upper()
    source_key = {"STEX":"stex_services","VOLTX":"voltx_services","ZENEX":"zenex_services"}.get(p)
    has_configured = bool(bot_settings.get(source_key)) if source_key else False
    return has_configured or any(bool(v) for v in pair_node.values()) or any(isinstance(v, bool) for v in service_node.values())

def _resolve_provider_service_callback(provider, payload):
    """Resolve a service from callback payload without breaking underscore names."""
    p = str(provider or "").strip().upper()
    source_key = {"STEX": "stex_services", "VOLTX": "voltx_services", "ZENEX": "zenex_services"}.get(p)
    source = bot_settings.get(source_key, {}) or {} if source_key else {}
    for candidate in sorted((str(k) for k in source.keys()), key=len, reverse=True):
        if payload == candidate or payload.startswith(candidate + "_"):
            return candidate, payload[len(candidate):].lstrip("_")
    return "", str(payload or "").strip("_")

panel_sessions = {}
# Persistent HTTP sessions for API-based manual panels; avoids TCP/TLS setup per poll.
manual_panel_http_sessions = {}

def _manual_panel_is_enabled_for_fetch(p):
    return str(p.get("source_type") or "").strip().upper() == "MANUAL" or bool(str(p.get("login_url") or "").strip())


def _manual_panel_column_indexes(p, headers=None):
    """Resolve Number/SMS columns for Manual panels without affecting legacy Auto panels."""
    headers = list(headers or [])
    n_idx = None
    m_idx = None

    try:
        if p.get("num_col_idx") not in (None, ""):
            n_idx = max(0, int(p.get("num_col_idx")) - 1)
    except Exception:
        n_idx = None
    try:
        if p.get("msg_col_idx") not in (None, ""):
            m_idx = max(0, int(p.get("msg_col_idx")) - 1)
    except Exception:
        m_idx = None

    if headers:
        lowered = [str(h or "").strip().casefold() for h in headers]
        wanted_n = str(p.get("num_col_name") or "number").strip().casefold()
        wanted_m = str(p.get("msg_col_name") or "sms").strip().casefold()
        # Table headers are authoritative for Manual panels. This also repairs stale
        # column indexes left by an older/manual configuration automatically.
        detected_n = next((i for i, h in enumerate(lowered) if h == wanted_n or h == "number" or "number" in h), None)
        detected_m = next((i for i, h in enumerate(lowered) if h == wanted_m or h == "sms" or "sms" in h or "message" in h), None)
        if detected_n is not None:
            n_idx = detected_n
        if detected_m is not None:
            m_idx = detected_m

    # Common Inteliotech SMS CDR layout: Date, Range, Number, CLI, Client, SMS, ...
    if n_idx is None:
        n_idx = 2
    if m_idx is None:
        m_idx = 5
    return n_idx, m_idx


def _manual_parse_timestamp(value):
    text = str(value or "").strip()
    if not text:
        return None
    text = re.sub(r"\s+", " ", text)
    for fmt in (
        "%Y-%m-%d %H:%M:%S",
        "%Y-%m-%d %H:%M",
        "%Y/%m/%d %H:%M:%S",
        "%Y/%m/%d %H:%M",
        "%d-%m-%Y %H:%M:%S",
        "%d/%m/%Y %H:%M:%S",
    ):
        try:
            return datetime.strptime(text[:19], fmt).timestamp()
        except Exception:
            pass
    m = re.search(r"(\d{4}[-/]\d{2}[-/]\d{2}\s+\d{2}:\d{2}:\d{2})", text)
    if m:
        try:
            return datetime.strptime(m.group(1).replace("/", "-"), "%Y-%m-%d %H:%M:%S").timestamp()
        except Exception:
            pass
    return None


def _manual_build_record(row, p, headers=None):
    if not isinstance(row, (list, tuple)):
        return None
    values = list(row)
    n_idx, m_idx = _manual_panel_column_indexes(p, headers)
    if len(values) <= max(n_idx, m_idx):
        return None
    date_value = values[0] if values else ""
    num_value = values[n_idx]
    msg_value = values[m_idx]
    num_text = BeautifulSoup(str(num_value or ""), "html.parser").get_text(separator=" ", strip=True)
    msg_text = BeautifulSoup(str(msg_value or ""), "html.parser").get_text(separator=" ", strip=True)
    clean_num = re.sub(r"\D", "", num_text)
    otp = extract_otp_code(msg_text) if len(msg_text) > 4 else ""
    return {
        "number": clean_num,
        "message": msg_text,
        "otp": otp or "",
        "date": str(date_value or "").strip(),
        "_sort_ts": _manual_parse_timestamp(date_value),
    }


def _manual_sort_latest(records):
    def key(item):
        ts = item.get("_sort_ts")
        return ts if isinstance(ts, (int, float)) else float("-inf")
    records.sort(key=key, reverse=True)
    return records


def _manual_records_from_html(html_text, p):
    soup = BeautifulSoup(html_text or "", "html.parser")
    records = []
    for table in soup.find_all("table"):
        rows = table.find_all("tr")
        if not rows:
            continue
        header_cells = rows[0].find_all(["th", "td"])
        headers = [c.get_text(" ", strip=True) for c in header_cells]
        n_idx, m_idx = _manual_panel_column_indexes(p, headers)
        for row in rows[1:]:
            cols = row.find_all(["td", "th"])
            if not cols or all(c.name == "th" for c in cols):
                continue
            rec = _manual_build_record([c.get_text(" ", strip=True) for c in cols], p, headers)
            if rec and rec.get("message"):
                records.append(rec)
    return _manual_sort_latest(records)


def _manual_records_from_ajax_payload(payload, p):
    cfg = _manual_hadi_force_config(p or {})
    if isinstance(payload, str):
        decoded = _manual_decode_ajax_payload(payload)
        payload = decoded if decoded is not None else payload
    if isinstance(payload, dict):
        rows = payload.get("aaData")
        if not isinstance(rows, list):
            rows = payload.get("data")
        if isinstance(rows, str):
            decoded = _manual_decode_ajax_payload(rows)
            if isinstance(decoded, (dict, list)):
                return _manual_records_from_ajax_payload(decoded, cfg)
        if not isinstance(rows, list):
            rows = []
    elif isinstance(payload, list):
        rows = payload
    else:
        rows = []
    records = []
    for row in rows:
        if isinstance(row, dict):
            lower = {str(k).strip().casefold(): v for k, v in row.items()}
            num_value = next((lower[k] for k in ("number", "num", "phone", "msisdn") if k in lower), None)
            msg_value = next((lower[k] for k in ("sms", "message", "msg", "content", "text") if k in lower), None)
            date_value = next((lower[k] for k in ("date", "datetime", "time", "created_at", "created") if k in lower), "")
            if num_value is None or msg_value is None:
                rec = _manual_build_record(list(row.values()), cfg)
            else:
                num_text = BeautifulSoup(str(num_value or ""), "html.parser").get_text(" ", strip=True)
                msg_text = BeautifulSoup(str(msg_value or ""), "html.parser").get_text(" ", strip=True)
                clean_num = re.sub(r"\D", "", num_text)
                rec = {"number": clean_num, "message": msg_text,
                       "otp": extract_otp_code(msg_text) if len(msg_text) > 4 else "",
                       "date": str(date_value or "").strip(),
                       "_sort_ts": _manual_parse_timestamp(date_value)}
        else:
            rec = _manual_build_record(row, cfg, cfg.get("_detected_headers"))
        if rec and rec.get("number") and rec.get("message"):
            records.append(rec)
    return _manual_sort_latest(records)

def _manual_prepare_ajax_url(url, check_url):
    full_ajax_url = urljoin(check_url, str(url or "").strip())
    if "iDisplayLength" not in full_ajax_url:
        query = "sEcho=1&iColumns=9&iDisplayStart=0&iDisplayLength=10000&sSearch=&iSortingCols=1&iSortCol_0=0&sSortDir_0=desc"
        full_ajax_url += ("&" if "?" in full_ajax_url else "?") + query
    else:
        full_ajax_url = re.sub(r"([?&]iColumns=)\d+", r"\g<1>9", full_ajax_url, flags=re.I)
    return full_ajax_url


def _fetch_manual_panel_cdrs(p, session, check_url, target_numbers=None):
    """Dedicated Manual Inteliotech/HADI fetch path with exact DataTables AJAX handling."""
    cfg = _manual_hadi_force_config(p or {})
    check_url = check_url or _manual_default_cdr_url(cfg)
    headers = {
        "Referer": check_url,
        "X-Requested-With": "XMLHttpRequest",
        "Accept": "application/json, text/javascript, */*; q=0.01",
        "Cache-Control": "no-cache",
        "Pragma": "no-cache",
    }
    target_norms = tuple(dict.fromkeys(
        _normalize_number_key(x) for x in (target_numbers or ()) if _normalize_number_key(x)
    ))
    ajax_url = str(cfg.get("cdr_ajax_url") or "").strip()
    html_text = ""

    def consume(payload):
        records = _manual_records_from_ajax_payload(payload, cfg)
        if records:
            p["_manual_latest_preview"] = dict(records[0])
            return records
        return []

    # Always refresh the page source once when needed; HADI's sesskey can change.
    try:
        page = session.get(check_url, headers={"Accept": "text/html,application/xhtml+xml"}, timeout=MANUAL_PANEL_HTTP_TIMEOUT, allow_redirects=True)
        html_text = page.text or ""
        try:
            page_soup = BeautifulSoup(html_text, "html.parser")
            for table in page_soup.find_all("table"):
                first = table.find("tr")
                if not first:
                    continue
                detected = [c.get_text(" ", strip=True) for c in first.find_all(["th", "td"])]
                lowered = {str(x).casefold() for x in detected}
                if any("number" in x for x in lowered) and any("sms" in x for x in lowered):
                    cfg["_detected_headers"] = detected
                    break
        except Exception:
            pass
        low = html_text.casefold()
        # Do not treat the word "login" in scripts/navigation as an expired
        # session. Only a real sign-in form indicates that authentication failed.
        page_soup = BeautifulSoup(html_text, "html.parser")
        has_login_form = bool(
            page_soup.find("input", {"name": re.compile(r"user|email", re.I)})
            and page_soup.find("input", {"type": "password"})
        )
        if has_login_form and not page_soup.find("table"):
            raise Exception("Session expired or login page returned")
    except Exception:
        # A cached AJAX endpoint may still be valid; try it before failing.
        if not ajax_url:
            raise

    discovered = _manual_extract_datatables_source(html_text, check_url) if html_text else ""
    if discovered:
        ajax_url = discovered
    if not ajax_url:
        # Known Inteliotech fallback; preserve any session/query parameters from the panel page when available.
        ajax_url = urljoin(check_url, "res/data_smscdr.php")
    ajax_url = _manual_prepare_ajax_url(ajax_url, check_url)
    p["cdr_ajax_url"] = ajax_url

    # DataTables needs the session's current cookies plus its normal server-side parameters.
    # For active leases, request exact target numbers first. A generic fallback remains
    # available for panels that ignore DataTables' global search term.
    search_terms = list(target_norms) if target_norms else [""]
    params_templates = (
        {"sEcho": "1", "iColumns": "9", "iDisplayStart": "0", "iDisplayLength": "100", "iSortingCols": "1", "iSortCol_0": "0", "sSortDir_0": "desc"},
        {"sEcho": "2", "iColumns": "9", "iDisplayStart": "0", "iDisplayLength": "25", "iSortingCols": "1", "iSortCol_0": "0", "sSortDir_0": "desc"},
    )
    for search_term in search_terms:
        for template in params_templates:
            extra = dict(template)
            extra["sSearch"] = search_term
            try:
                ajax_res = session.get(ajax_url, params=extra, headers=headers, timeout=MANUAL_PANEL_HTTP_TIMEOUT, allow_redirects=True)
                payload = _manual_decode_ajax_payload(ajax_res.text)
                records = consume(payload)
                # A few panel deployments accept DataTables parameters only via
                # POST; retry the same authenticated request before abandoning it.
                if not records and ajax_res.status_code < 400:
                    ajax_res = session.post(ajax_url, data=extra, headers=headers, timeout=MANUAL_PANEL_HTTP_TIMEOUT, allow_redirects=True)
                    if not (BeautifulSoup(ajax_res.text or "", "html.parser").find("input", {"type": "password"})):
                        records = consume(_manual_decode_ajax_payload(ajax_res.text))
                if target_norms:
                    records = [r for r in records if any(_manual_numbers_match(r.get("number"), target) for target in target_norms)]
                if records:
                    try:
                        if str(p.get("source_type") or "").strip().upper() == "MANUAL":
                            save_db()
                    except Exception:
                        pass
                    return records, html_text
            except Exception:
                continue

    # Static HTML fallback is useful for panels/proxies that render rows server-side.
    records = _manual_records_from_html(html_text, cfg) if html_text else []
    if records:
        p["_manual_latest_preview"] = dict(records[0])
    return records, html_text

def fetch_cpt_panel_cdrs(p, session, check_url):
    # Manual panels use an isolated enhanced path. All existing non-Manual behavior is unchanged.
    if _manual_panel_is_enabled_for_fetch(p):
        return _fetch_manual_panel_cdrs(p, session, check_url)

    # Once a panel exposes its DataTables AJAX endpoint, keep using that endpoint
    # directly. The HTML/login page is still fetched as the fallback so legacy panels
    # keep their original behavior and session-expiry detection.
    cached_ajax_url = str(p.get("cdr_ajax_url", "") or "").strip()
    if cached_ajax_url:
        ajax_headers = {"Referer": check_url, "X-Requested-With": "XMLHttpRequest"}
        try:
            ajax_res = session.get(cached_ajax_url, headers=ajax_headers, timeout=MANUAL_PANEL_HTTP_TIMEOUT)
            data_dict = ajax_res.json()
            rows = data_dict.get("aaData", []) if isinstance(data_dict, dict) else []
            if isinstance(rows, list):
                n_col_name = p.get("num_col_name", "number").lower()
                m_col_name = p.get("msg_col_name", "message").lower()
                n_idx = int(p.get("num_col_idx", 1)) - 1 if p.get("num_col_idx") else 1
                m_idx = int(p.get("msg_col_idx", 2)) - 1 if p.get("msg_col_idx") else 2
                results = []
                for row_val in rows:
                    if not isinstance(row_val, list) or len(row_val) < max(n_idx, m_idx) + 1:
                        continue
                    num_val = row_val[n_idx] if 0 <= n_idx < len(row_val) else row_val[2]
                    msg_val = row_val[m_idx] if 0 <= m_idx < len(row_val) else row_val[4]
                    clean_num = re.sub(r"\D", "", str(num_val))
                    if clean_num and 5 <= len(clean_num) <= 18:
                        otp = extract_otp_code(msg_val)
                        if otp and len(msg_val) > 4:
                            results.append({"number": clean_num, "message": msg_val, "otp": otp})
                return results, ""
        except Exception:
            p.pop("cdr_ajax_url", None)

    res = session.get(check_url, timeout=MANUAL_PANEL_HTTP_TIMEOUT)
    html_text = res.text
    if "login" in html_text.lower() or "signin" in html_text.lower() or any(x in html_text for x in ["Sign in to your account", "Please sign in", "Welcome back!"]):
        raise Exception("Session expired")

    soup = BeautifulSoup(html_text, 'html.parser')
    s_ajax_source = ""
    for script in soup.find_all("script"):
        script_text = script.string or ""
        match = re.search(r'sAjaxSource":\s*"([^"]+)"', script_text)
        if match:
            s_ajax_source = match.group(1)
            break

    results = []
    n_col_name = p.get("num_col_name", "number").lower()
    m_col_name = p.get("msg_col_name", "message").lower()
    n_idx = int(p.get("num_col_idx", 1)) - 1 if p.get("num_col_idx") else 1
    m_idx = int(p.get("msg_col_idx", 2)) - 1 if p.get("msg_col_idx") else 2

    if s_ajax_source:
        baseUrl = p.get("login_url", "").split("/client")[0].split("/login")[0].strip()
        if not baseUrl.startswith("http"):
            baseUrl = "http://" + baseUrl
        full_ajax_url = ""
        if s_ajax_source.startswith("http"):
            full_ajax_url = s_ajax_source
        elif s_ajax_source.startswith("/"):
            full_ajax_url = f"{baseUrl}{s_ajax_source}"
        else:
            last_slash_idx = check_url.rfind("/")
            current_dir = check_url[:last_slash_idx]
            full_ajax_url = f"{current_dir}/{s_ajax_source}"
        if "iDisplayLength" not in full_ajax_url:
            query_params = "sEcho=1&iColumns=7&iDisplayStart=0&iDisplayLength=10000&sSearch=&iSortingCols=1&iSortCol_0=0&sSortDir_0=desc"
            divider = "&" if "?" in full_ajax_url else "?"
            full_ajax_url += f"{divider}{query_params}"
        ajax_headers = {"Referer": check_url, "X-Requested-With": "XMLHttpRequest"}
        if str(p.get("cdr_ajax_url", "") or "").strip() != full_ajax_url:
            p["cdr_ajax_url"] = full_ajax_url
            save_db()
        ajax_res = session.get(full_ajax_url, headers=ajax_headers, timeout=MANUAL_PANEL_HTTP_TIMEOUT)
        data_dict = ajax_res.json()
        rows = data_dict.get("aaData", [])
        for row_val in rows:
            if not isinstance(row_val, list) or len(row_val) < max(n_idx, m_idx) + 1:
                continue
            num_val = row_val[n_idx] if 0 <= n_idx < len(row_val) else row_val[2]
            msg_val = row_val[m_idx] if 0 <= m_idx < len(row_val) else row_val[4]
            clean_num = re.sub(r"\D", "", str(num_val))
            if clean_num and 5 <= len(clean_num) <= 18:
                otp = extract_otp_code(msg_val)
                if otp and len(msg_val) > 4:
                    results.append({"number": clean_num, "message": msg_val, "otp": otp})
    else:
        tables = soup.find_all('table')
        for table in tables:
            rows = table.find_all('tr')
            if not rows:
                continue
            final_n_idx = n_idx
            final_m_idx = m_idx
            header_cells = rows[0].find_all(['th', 'td'])
            for i, cell in enumerate(header_cells):
                c_text = cell.get_text(strip=True).lower()
                if n_col_name in c_text:
                    final_n_idx = i
                if m_col_name in c_text:
                    final_m_idx = i
            for row in rows:
                cols = row.find_all(['td', 'th'])
                if all(c.name == 'th' for c in cols):
                    continue
                if len(cols) > max(final_n_idx, final_m_idx):
                    num_text = cols[final_n_idx].get_text(separator=" ", strip=True)
                    msg_text = cols[final_m_idx].get_text(separator=" ", strip=True)
                    clean_num = re.sub(r'\D', '', num_text)
                    if clean_num and 5 <= len(clean_num) <= 18:
                        otp = extract_otp_code(msg_text)
                        if otp and len(msg_text) > 4:
                            results.append({"number": clean_num, "message": msg_text, "otp": otp})
    return results, html_text

