def _contains_bengali(value):
    return bool(re.search(r"[\u0980-\u09FF]", str(value or "")))

def _sanitize_custom_messages_for_english():
    changed = False
    for key, default in DEFAULT_CUSTOM_MESSAGES.items():
        current = bot_settings.get("custom_messages", {}).get(key, {})
        text = current.get("text", "") if isinstance(current, dict) else ""
        buttons = current.get("buttons", []) if isinstance(current, dict) else []
        has_bengali = _contains_bengali(text)
        if not has_bengali and isinstance(buttons, list):
            for button in buttons:
                if isinstance(button, dict) and _contains_bengali(button.get("text", "")):
                    has_bengali = True
                    break
        if has_bengali:
            bot_settings["custom_messages"][key] = json.loads(json.dumps(default, ensure_ascii=False))
            changed = True
    return changed



def _ensure_builtin_premium_languages():
    """Fill missing built-in language display metadata without overwriting custom values."""
    configured = bot_settings.setdefault("premium_languages", {})
    if not isinstance(configured, dict):
        bot_settings["premium_languages"] = {}
        configured = bot_settings["premium_languages"]
    changed = False
    for code, default in BUILTIN_PREMIUM_LANGUAGES.items():
        current = configured.get(code)
        if not isinstance(current, dict):
            configured[code] = dict(default)
            changed = True
            continue
        for field, value in default.items():
            if not str(current.get(field, "")).strip():
                current[field] = value
                changed = True
    return changed

