def _load_prepared_analysis_state():
    try:
        path = Path(DB_FILE)
        if not path.is_file():
            return None
        with path.open("r", encoding="utf-8") as fh:
            data = json.load(fh)
        value = data.get("analysis_state") if isinstance(data, dict) else None
        return value if isinstance(value, dict) and value.get("services") else None
    except Exception:
        return None

