def _extract_remote_range_state(remote):
    if not isinstance(remote, dict):
        return None
    result = {}
    for key in FS_RANGE_KEYS:
        if key in remote:
            result[key] = remote[key]
    result.pop("zenex_auto", None)  # keep local automation preference local
    return result or None

def _merge_remote_ranges(remote_range):
    """Merge only remote ZenEX range state into local settings, preserving local UI/config."""
    if not remote_range:
        return False
    changed = False
    for key in ("zenex_services", "zenex_range_meta", "zenex_range_status"):
        if key in remote_range:
            if bot_settings.get(key) != remote_range.get(key):
                bot_settings[key] = remote_range.get(key)
                changed = True
    return changed

