# Shared provider sessions keep TCP/TLS connections warm across polling cycles.
# The bot is I/O-bound; connection reuse is one of the safest high-impact latency wins.
def _build_http_session(pool_connections=32, pool_maxsize=64, user_agent="FRD-Bot/2.0"):
    session = requests.Session()
    adapter = HTTPAdapter(
        pool_connections=pool_connections,
        pool_maxsize=pool_maxsize,
        max_retries=Retry(
            total=2,
            connect=2,
            read=1,
            backoff_factor=0.2,
            status_forcelist=(429, 502, 503, 504),
            allowed_methods=("GET", "POST"),
            respect_retry_after_header=True,
        ),
    )
    session.mount("http://", adapter)
    session.mount("https://", adapter)
    session.headers.update({"Connection": "keep-alive", "User-Agent": user_agent})
    return session

STEX_HTTP = _build_http_session(user_agent="FRD-Stex/2.0")
VOLTX_HTTP = _build_http_session(user_agent="FRD-Voltx/2.0")
ZENEX_HTTP = _build_http_session(user_agent="FRD-Zenex/2.0")
# Dedicated no-retry lanes for interactive Get Number allocation.
# Background polling keeps its resilient retry policy; user clicks should never
# wait through an automatic retry/backoff cycle.
def _build_fast_provider_session(user_agent):
    session = requests.Session()
    adapter = HTTPAdapter(pool_connections=32, pool_maxsize=96, max_retries=0)
    session.mount("http://", adapter)
    session.mount("https://", adapter)
    session.headers.update({"Connection": "keep-alive", "User-Agent": user_agent})
    return session

STEX_GETNUM_HTTP = _build_fast_provider_session("FRD-Stex-GetNum/2.1")
