ZENEX_GETNUM_HTTP = _build_fast_provider_session("FRD-Zenex-GetNum/2.1")
FILE_HTTP = _build_http_session(pool_connections=8, pool_maxsize=16, user_agent="FRD-Telegram-File/2.0")

def _retry_after_seconds(response=None, data=None, default=1.0):
    """Read Telegram/provider retry guidance without hiding the server's backoff window."""
    candidates = []
    if isinstance(data, dict):
        try:
            candidates.append((data.get("parameters") or {}).get("retry_after"))
        except Exception:
            pass
    try:
        if response is not None:
            candidates.append(response.headers.get("Retry-After"))
    except Exception:
        pass
    for value in candidates:
        try:
            delay = float(value)
            if delay >= 0:
                return min(delay, 3600.0)
        except (TypeError, ValueError):
            continue
    return max(0.0, float(default))


def api_call(method, payload=None):
    call_started = time.perf_counter()
    url = f"{BASE_URL}/{method}"
    request_payload = _stylize_api_payload(payload) if payload else payload

    for attempt in range(1, 6):
        try:
            response = tg_session.post(url, json=request_payload, timeout=15)
            data = response.json()
            if data.get("ok"):
                elapsed = _debug_duration_ms(call_started) if "_debug_duration_ms" in globals() else 0
                if DEBUG_TERMINAL and elapsed >= DEBUG_LOG_MIN_MS:
                    _debug_log(f"Telegram API {method} OK {elapsed:.0f}ms")
                return data

            if data.get("error_code") == 429:
                # Telegram's ResponseParameters.retry_after is the authoritative
                # flood-control delay. Honor it rather than guessing or spinning.
                delay = _retry_after_seconds(response, data, default=min(2 ** (attempt - 1), 8))
                time.sleep(delay)
                continue

            return data
        except (requests.exceptions.Timeout, requests.exceptions.ConnectionError):
            if attempt >= 5:
                break
            # Exponential backoff with bounded jitter prevents synchronized retry
            # bursts while keeping recovery responsive.
            base = min(2 ** (attempt - 1), 8)
            time.sleep(base + random.uniform(0.0, min(0.35, base * 0.15)))
        except ValueError:
            return {}
        except Exception:
            return {}
    return {}


DEBUG_TERMINAL = str(os.getenv("DEBUG_TERMINAL", "0")).strip().lower() not in {"0", "false", "off", "no"}
DEBUG_LOG_MIN_MS = max(1.0, float(os.getenv("DEBUG_LOG_MIN_MS", "50")))
# Focused Auto Intelligence terminal telemetry. This is intentionally separate
# from DEBUG_TERMINAL so operators can see each research/apply cycle without
# enabling every low-level request trace.
INTELLIGENCE_TERMINAL = (
    str(os.getenv("INTELLIGENCE_TERMINAL", "0")).strip().lower() not in {"0", "false", "off", "no"}
    and not TERMINAL_STATUS_ONLY
)

def _debug_log(message):
    if not DEBUG_TERMINAL:
        return
    _startup_console_log(f"[DEBUG {time.strftime('%H:%M:%S')}] {message}")


def _debug_duration_ms(start):
    return (time.perf_counter() - start) * 1000.0


def _telegram_get_updates(offset=None):
    """Long-poll Telegram and expose request timing/errors in debug mode."""
    params = {"timeout": 20}
    if offset is not None:
        params["offset"] = int(offset)
    url = f"{BASE_URL}/getUpdates"
    started = time.perf_counter()
    for attempt in range(2):
        try:
            _debug_log(f"Telegram getUpdates START offset={offset} attempt={attempt+1}")
            response = tg_fast_session.get(url, params=params, timeout=(5, 25))
            data = response.json()
            elapsed = _debug_duration_ms(started)
            if data.get("error_code") == 409:
                _debug_log(f"Telegram getUpdates 409 CONFLICT after {elapsed:.0f}ms")
                LOCAL_STOP.wait(5.0)
                return {}
            if data.get("ok") or data.get("error_code") != 429 or attempt == 1:
                count = len(data.get("result") or []) if isinstance(data, dict) else 0
                _debug_log(f"Telegram getUpdates END ok={data.get('ok')} updates={count} elapsed={elapsed:.0f}ms")
                return data
            delay = _retry_after_seconds(response, data, default=1.0)
            _debug_log(f"Telegram getUpdates 429 retry_after={delay:.1f}s")
            time.sleep(min(max(delay, 0.0), 30.0))
        except (requests.exceptions.Timeout, requests.exceptions.ConnectionError) as exc:
            elapsed = _debug_duration_ms(started)
            _debug_log(f"Telegram getUpdates NETWORK ERROR after {elapsed:.0f}ms: {type(exc).__name__}: {str(exc)[:120]}")
            if attempt == 0:
                LOCAL_STOP.wait(0.75)
                started = time.perf_counter()
                continue
            return {}
        except ValueError as exc:
            _debug_log(f"Telegram getUpdates JSON ERROR: {exc}")
            return {}
        except Exception as exc:
            _debug_log(f"Telegram getUpdates ERROR: {type(exc).__name__}: {str(exc)[:160]}")
            return {}
    return {}

def _prepare_outbound_user_text(chat_id, text):
    """Apply premium-emoji rendering and provider secrecy at the final outbound boundary.

    Admin chats keep provider names visible for diagnostics/control. All other chats
    receive the user-safe renderer so legacy call-sites cannot accidentally leak a
    provider identifier or bypass uploaded Premium Emoji mappings.
    """
    raw = str(text or "")
    try:
        uid = int(chat_id)
    except Exception:
        uid = None
    try:
        admin_view = uid is not None and is_admin(uid)
    except Exception:
        admin_view = False
    return render_body_text(raw) if admin_view else render_user_body_text(raw)


def _strip_normal_button_emojis(text):
    """Remove redundant standard emojis from button labels.

    The corresponding Premium custom emoji is shown by Telegram in
    ``icon_custom_emoji_id`` instead, so the label itself stays clean.
    """
    raw = str(text or "")
    if not raw:
        return raw
    # Longest-first avoids partial replacement of multi-codepoint emoji such as 1️⃣.
    chars = set(GLOBAL_BODY_EMOJIS.keys()) | set(PREMIUM_EMOJI_FALLBACKS.keys())
    for store_key in ("premium_body_emojis", "premium_flags", "premium_apps", "premium_languages"):
        store = bot_settings.get(store_key, {}) if isinstance(bot_settings, dict) else {}
        if isinstance(store, dict):
            for data in store.values():
                if isinstance(data, dict):
                    ch = str(data.get("char") or data.get("emoji") or "").strip()
                    if ch:
                        chars.add(ch)
    for normal_emj in sorted(chars, key=len, reverse=True):
        raw = raw.replace(normal_emj, "")
    raw = re.sub(r"[ \t]{2,}", " ", raw)
    raw = re.sub(r"^[ \t]+|[ \t]+$", "", raw)
    return raw


def _ensure_premium_button_emojis(reply_markup):
    """Ensure every inline button has a Premium custom emoji and no redundant normal emoji."""
    if not isinstance(reply_markup, dict):
        return reply_markup
    rows = reply_markup.get("inline_keyboard")
    if not isinstance(rows, list):
        return reply_markup

    default_by_style = {
        "success": "5352694861990501856",  # ✅
        "danger": "5420130255174145507",   # ❌
        "primary": "5420155432272438703",  # ⚙️
    }
    fallback = str(bot_settings.get("frd_button_emoji_id", "") or "").strip()
    if not fallback.isdigit():
        fallback = "5352877703043258544"  # 📊

    # Prefer the Premium ID matching a normal emoji already present in the label.
    # Admin-uploaded mappings are checked first, then the built-in premium fallback map.
    premium_by_char = {}
    for store_key in ("premium_body_emojis", "premium_flags", "premium_apps", "premium_languages"):
        store = bot_settings.get(store_key, {}) if isinstance(bot_settings, dict) else {}
        if not isinstance(store, dict):
            continue
        for data in store.values():
            if not isinstance(data, dict):
                continue
            ch = str(data.get("char") or data.get("emoji") or "").strip()
            eid = str(data.get("id") or data.get("custom_emoji_id") or "").strip()
            if ch and eid.isdigit():
                premium_by_char[ch] = eid
    for ch, eid in GLOBAL_BODY_EMOJIS.items():
        if str(eid).isdigit():
            premium_by_char.setdefault(str(ch), str(eid))

    out = []
    for row in rows:
        if not isinstance(row, list):
            out.append(row)
            continue
        new_row = []
        for button in row:
            if not isinstance(button, dict):
                new_row.append(button)
                continue
            b = dict(button)
            label = str(b.get("text", "") or "")

            eid = str(b.get("icon_custom_emoji_id", "") or "").strip()
            if not eid.isdigit():
                matched = next((premium_by_char[ch] for ch in sorted(premium_by_char, key=len, reverse=True) if ch in label), "")
                if matched:
                    eid = matched
                else:
                    style = str(b.get("style", "") or "").strip().lower()
                    eid = default_by_style.get(style, fallback)
                b["icon_custom_emoji_id"] = eid

            # Once the Premium icon is guaranteed, remove the duplicate standard
            # emoji from the visible button label.
            if label:
                b["text"] = _strip_normal_button_emojis(label)
            new_row.append(b)
        out.append(new_row)
    result = dict(reply_markup)
    result["inline_keyboard"] = out
    return result

def _telegram_plain_html_fallback(text):
    """Keep valid HTML while replacing unsupported custom emoji entities."""
    return re.sub(
        r"<tg-emoji[^>]*>(.*?)</tg-emoji>", r"\1", str(text or ""), flags=re.I | re.S
    )


def _telegram_keyboard_fallback(reply_markup):
    """Copy button markup without removing supported colors or Premium icons."""
    if not isinstance(reply_markup, dict):
        return reply_markup
    return json.loads(json.dumps(reply_markup, ensure_ascii=False))


def _telegram_entity_fallback_needed(data):
    detail = str((data or {}).get("description", "") if isinstance(data, dict) else "").lower()
    return "entity_text_invalid" in detail or "can't parse entities" in detail


def _send_message_without_custom_entities(payload):
    fallback = dict(payload)
    fallback["text"] = _telegram_plain_html_fallback(fallback.get("text", ""))
    if fallback.get("reply_markup"):
        fallback["reply_markup"] = _telegram_keyboard_fallback(fallback["reply_markup"])
    try:
        response = tg_fast_session.post(f"{BASE_URL}/sendMessage", json=fallback, timeout=(0.65, 3.0))
        return response.json()
    except Exception as exc:
        return {"ok": False, "error": f"plain_html_fallback: {str(exc)[:120]}"}


def send_message(chat_id, text, reply_markup=None, parse_mode="HTML", reply_to_message_id=None):
    send_started = time.perf_counter()
    _debug_log(f"send_message START chat={chat_id}")
    # Final outbound normalization: premium emojis + provider secrecy.
    reply_markup = _ensure_premium_button_emojis(reply_markup)
    text = _prepare_outbound_user_text(chat_id, text)
    # Balance every inline-keyboard screen automatically.
    if isinstance(reply_markup, dict) and reply_markup.get("inline_keyboard"):
        text = _balance_text_to_inline_keyboard(text, reply_markup)
    payload = {"chat_id": chat_id, "text": text, "parse_mode": parse_mode, "disable_web_page_preview": True}
    if reply_markup: payload["reply_markup"] = reply_markup
    if reply_to_message_id is not None:
        payload["reply_parameters"] = {"message_id": int(reply_to_message_id), "allow_sending_without_reply": True}
    result = api_call("sendMessage", payload)
    elapsed = _debug_duration_ms(send_started)
    _debug_log(f"send_message END chat={chat_id} ok={bool(isinstance(result, dict) and result.get("ok"))} elapsed={elapsed:.0f}ms")
    return _send_message_without_custom_entities(payload) if _telegram_entity_fallback_needed(result) else result


def send_message_fast(chat_id, text, reply_markup=None, parse_mode="HTML", reply_to_message_id=None):
    """High-priority Telegram send lane for latency-sensitive deliveries.

    This path deliberately avoids long retry/backoff cycles; transient failures remain
    retryable by the owning worker so OTP ingestion itself is never blocked.
    """
    reply_markup = _ensure_premium_button_emojis(reply_markup)
    text = _prepare_outbound_user_text(chat_id, text)
    if isinstance(reply_markup, dict) and reply_markup.get("inline_keyboard"):
        text = _balance_text_to_inline_keyboard(text, reply_markup)
    payload = {"chat_id": chat_id, "text": text, "parse_mode": parse_mode, "disable_web_page_preview": True}
    if reply_markup: payload["reply_markup"] = reply_markup
    if reply_to_message_id is not None:
        payload["reply_parameters"] = {"message_id": int(reply_to_message_id), "allow_sending_without_reply": True}
    url = f"{BASE_URL}/sendMessage"
    last_result = {"ok": False, "error": "fast_send_unknown"}
    for attempt in range(2):
        try:
            res = tg_fast_session.post(url, json=payload, timeout=(0.65, 2.0))
            try:
                data = res.json()
            except Exception:
                data = {"ok": False, "status_code": res.status_code}
            last_result = data
            if data.get("ok"):
                return data
            if _telegram_entity_fallback_needed(data):
                return _send_message_without_custom_entities(payload)
            if data.get("error_code") == 429 and attempt == 0:
                delay = _retry_after_seconds(res, data, default=1.0)
                time.sleep(min(max(delay, 0.0), 30.0))
                continue
            return data
        except (requests.exceptions.Timeout, requests.exceptions.ConnectionError):
            if attempt == 0:
                time.sleep(0.05)
                continue
            return {"ok": False, "error": "fast_send_network"}
        except Exception as exc:
            return {"ok": False, "error": str(exc)[:160]}
    return last_result

def send_photo(chat_id, photo_url_or_file_id, caption="", reply_markup=None, parse_mode="HTML"):
    reply_markup = _ensure_premium_button_emojis(reply_markup)
    caption = _prepare_outbound_user_text(chat_id, caption)
    payload = {"chat_id": chat_id, "photo": photo_url_or_file_id, "caption": caption, "parse_mode": parse_mode}
    if reply_markup: payload["reply_markup"] = reply_markup
    return api_call("sendPhoto", payload)

def edit_message(chat_id, message_id, text, reply_markup=None, parse_mode="HTML"):
    """Fast-first message edit with resilient fallback."""
    reply_markup = _ensure_premium_button_emojis(reply_markup)
    text = _prepare_outbound_user_text(chat_id, text)
    if isinstance(reply_markup, dict) and reply_markup.get("inline_keyboard"):
        text = _balance_text_to_inline_keyboard(text, reply_markup)
    payload = {"chat_id": chat_id, "message_id": message_id, "text": text, "parse_mode": parse_mode, "disable_web_page_preview": True}
    if reply_markup:
        payload["reply_markup"] = reply_markup
    try:
        res = tg_fast_session.post(
            f"{BASE_URL}/editMessageText",
            json=_stylize_api_payload(payload),
            timeout=(0.35, 1.5),
        )
        data = res.json()
        desc = str(data.get("description", "") or "").lower()
        if data.get("ok") or "message is not modified" in desc:
            return data
        if data.get("error_code") == 429:
            retry_after = int((data.get("parameters") or {}).get("retry_after", 1) or 1)
            time.sleep(min(max(retry_after, 1), 60))
        return api_call("editMessageText", payload)
    except Exception:
        return api_call("editMessageText", payload)

def delete_message(chat_id, message_id):
    return api_call("deleteMessage", {"chat_id": chat_id, "message_id": message_id})

def answer_callback(callback_id, text="", show_alert=False):
    """Low-latency callback ACK lane; never inherits api_call retry/backoff."""
    payload = {"callback_query_id": callback_id, "text": text, "show_alert": show_alert}
    url = f"{BASE_URL}/answerCallbackQuery"
    for attempt in range(2):
        try:
            res = tg_fast_session.post(url, json=payload, timeout=(0.35, 1.5))
            try:
                data = res.json()
            except Exception:
                data = {"ok": False, "status_code": res.status_code}
            if data.get("ok"):
                return data
            if data.get("error_code") == 429 and attempt == 0:
                delay = _retry_after_seconds(res, data, default=1.0)
                time.sleep(min(max(delay, 0.0), 30.0))
                continue
            return data
        except (requests.exceptions.Timeout, requests.exceptions.ConnectionError):
            if attempt == 0:
                time.sleep(0.05)
                continue
            return {"ok": False, "error": "callback_ack_network"}
        except Exception:
            return {"ok": False, "error": "callback_ack_exception"}
    return {"ok": False, "error": "callback_ack_failed"}

def _schedule_callback_ack(callback_id, text="", show_alert=False):
    """Queue callback acknowledgement on a dedicated high-priority pool."""
    try:
        _callback_ack_pool.submit(answer_callback, callback_id, text, show_alert)
        return True
    except Exception:
        return False


def _normalize_telegram_chat_id(value):
    """Normalize a Telegram chat id while preserving @username-style ids."""
    raw = str(value or "").strip()
    if not raw:
        return ""
    # Admins often paste a public t.me link instead of @username. Telegram's
    # sendMessage API accepts the latter, not the URL.
    public_link = re.fullmatch(r"(?:https?://)?(?:t\.me|telegram\.me)/([A-Za-z0-9_]{5,})/?", raw, flags=re.IGNORECASE)
    if public_link:
        return "@" + public_link.group(1)
    if raw.startswith("@"):
        return raw
    raw = raw.replace(" ", "")
    try:
        return str(int(raw))
    except Exception:
        return raw

def _withdrawal_group_candidates():
    """Return ONLY the administrator-configured withdrawal group.

    Withdrawal requests must never silently fall back to an OTP forward group.
    """
    primary = _normalize_telegram_chat_id(bot_settings.get("w_group", ""))
    return [primary] if primary else []

def _probe_telegram_chat(chat_id):
    """Probe Telegram access to a configured group and return (ok, detail)."""
    cid = _normalize_telegram_chat_id(chat_id)
    if not cid:
        return False, "empty chat id"
    try:
        res = api_call("getChat", {"chat_id": cid})
        if not isinstance(res, dict) or not res.get("ok"):
            desc = (res or {}).get("description", "Telegram getChat failed") if isinstance(res, dict) else "Telegram getChat failed"
            return False, str(desc)
        chat = res.get("result") or {}
        ctype = str(chat.get("type", "") or "")
        if ctype not in {"group", "supergroup", "channel"}:
            return False, f"chat type is {ctype or 'unknown'}, not a group/supergroup"
        # A bot must be able to access the chat. getChat success is enough to reject
        # the common 'chat not found' failure before a user's money is reserved.
        return True, f"{ctype}: {chat.get('title', cid)}"
    except Exception as exc:
        return False, str(exc)

def _get_withdrawal_group_id():
    """Resolve the exact administrator-configured withdrawal group only."""
    candidates = _withdrawal_group_candidates()
    diagnostics = []
    if not candidates:
        return "", "no withdrawal group configured", diagnostics
    cid = candidates[0]
    ok, detail = _probe_telegram_chat(cid)
    diagnostics.append((cid, detail))
    if ok:
        _terminal_log(f"[WITHDRAWAL][GROUP] configured withdrawal group is accessible chat_id={cid} detail={detail}")
        return cid, "ok", diagnostics
    _terminal_log(f"[WITHDRAWAL][GROUP] configured withdrawal group is NOT accessible chat_id={cid}: {detail}")
    return "", "configured withdrawal group is not accessible to this bot", diagnostics

def send_document(chat_id, filename, text_content):
    url = f"{BASE_URL}/sendDocument"
    files = {'document': (filename, text_content)}
    data = {'chat_id': chat_id}
    try: 
        # Use a separate session to avoid blocking
        with requests.Session() as s:
            s.post(url, data=data, files=files, timeout=30)
    except: pass

all_known_users = set()

def sync_users_list():
    """Load the local user index only; Firebase is not scanned for broadcasts."""
    global all_known_users
    try:
        if os.path.exists("users_list.json"):
            with open("users_list.json", "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, list):
                all_known_users = {str(x) for x in data if str(x).strip()}
    except Exception as exc:
        _terminal_log(f"[LOCAL] user index load failed: {exc}")

threading.Thread(target=sync_users_list, daemon=True).start()

_USERS_LIST_DIRTY = threading.Event()
_USERS_LIST_STOP = threading.Event()
_USERS_LIST_LOCK = threading.RLock()

def _save_users_list():
    try:
        with _USERS_LIST_LOCK:
            temp = "users_list.json.tmp"
            with open(temp, "w", encoding="utf-8") as f:
                json.dump(sorted(all_known_users), f, ensure_ascii=False)
                f.flush()
                os.fsync(f.fileno())
            os.replace(temp, "users_list.json")
    except Exception as exc:
        _terminal_log(f"[LOCAL] users_list save failed: {exc}")

def _users_list_flush_worker():
    while not _USERS_LIST_STOP.is_set():
        if not _USERS_LIST_DIRTY.wait(timeout=5):
            continue
        _USERS_LIST_DIRTY.clear()
        # Coalesce bursts of new users into a single atomic write.
        _USERS_LIST_STOP.wait(0.5)
        try:
            _save_users_list()
        except Exception:
            pass

def register_user_local(uid):
    uid_str = str(uid)
    with _USERS_LIST_LOCK:
        if uid_str in all_known_users:
            return False
        all_known_users.add(uid_str)
        _USERS_LIST_DIRTY.set()
        return True

threading.Thread(target=_users_list_flush_worker, daemon=True, name="users-list-flush").start()

# -----------------------------------------------------------------------------
# Production Broadcast Engine
# -----------------------------------------------------------------------------
# Uses controlled concurrency, connection reuse, bounded retries, and Telegram
# Retry-After handling. It does not attempt to bypass Telegram anti-spam limits.
_broadcast_pool = ThreadPoolExecutor(max_workers=max(8, BROADCAST_WORKERS), thread_name_prefix="broadcast")
# Small dedicated pool so OTP group delivery never waits for unrelated broadcasts.
_otp_delivery_pool = ThreadPoolExecutor(max_workers=MANUAL_PANEL_DELIVERY_WORKERS, thread_name_prefix="otp-delivery")

# Forward-delivery health is intentionally local and contains no OTP, phone
# number, or message body.  It makes a Telegram-side failure observable without
# retaining sensitive event content.
_OTP_FORWARD_STATUS_LOCK = threading.RLock()
OTP_FORWARD_STATUS = {"sent": 0, "failed": 0, "last_success_at": 0.0, "last_error": ""}


def _test_route_is_configured(service_name, country_name):
    """Allow manual test messages only for service/country pairs configured by admin."""
    canonical = _resolve_configured_service_name(str(service_name or "").strip())
    if not canonical:
        return ""
    country = str(country_name or "").strip()
    if not country:
        return ""
    for setting_key in ("stex_services", "voltx_services", "zenex_services"):
        configured = bot_settings.get(setting_key, {}) or {}
        if not isinstance(configured, dict):
            continue
        for configured_service, countries in configured.items():
            if not isinstance(countries, dict):
                continue
            if not _service_labels_match(canonical, configured_service):
                continue
            if any(_country_labels_match(country, configured_country) for configured_country in countries):
                return canonical
    return ""


def _test_service_emoji(service_name):
    """Return configured Premium service emoji HTML; empty means do not forward."""
    try:
        _, premium_html = get_service_info_html(service_name, "")
        return str(premium_html or "").strip()
    except Exception:
        return ""


def forward_otp_to_configured_groups(otp, message_text, fast=True):
    """Deliver one masked OTP event to every configured forward group.

    All producer paths use this gateway so group IDs are normalized consistently
    and Telegram failures are never silently discarded.  ``send_message_fast``
    includes one retry for transient network errors and flood waits.
    """
    # Every group OTP must carry the service logo.  The message builder returns
    # an empty value when a service has no configured/fallback emoji, but keep
    # this guard at the delivery boundary as well so a future producer cannot
    # accidentally bypass that rule.
    if not str(message_text or "").strip():
        return [{"ok": False, "error": "missing service emoji; group forward skipped"}]

    outcomes = []
    sender = send_message_fast if fast else send_message
    for fw in list(bot_settings.get("fw_groups", []) or []):
        if not isinstance(fw, dict):
            continue
        chat_id = _normalize_telegram_chat_id(fw.get("chat_id", ""))
        if not chat_id:
            outcomes.append({"ok": False, "error": "empty forward-group chat id"})
            continue
        try:
            keyboard = build_otp_group_keyboard(otp, fw).get("inline_keyboard", [])
            result = sender(chat_id, message_text, {"inline_keyboard": keyboard})
            # The fast lane uses a deliberately tiny timeout.  That is useful
            # for user inbox latency, but a group can legitimately take longer
            # to acknowledge a send.  Retry group delivery through the regular
            # Telegram lane before treating it as failed.
            if fast and not (isinstance(result, dict) and result.get("ok")):
                result = send_message(chat_id, message_text, {"inline_keyboard": keyboard})
            ok = bool(isinstance(result, dict) and result.get("ok"))
            error = "" if ok else str((result or {}).get("description") or (result or {}).get("error") or "Telegram sendMessage failed")[:240]
        except Exception as exc:
            ok, error = False, str(exc)[:240]
        with _OTP_FORWARD_STATUS_LOCK:
            if ok:
                OTP_FORWARD_STATUS["sent"] = int(OTP_FORWARD_STATUS.get("sent", 0) or 0) + 1
                OTP_FORWARD_STATUS["last_success_at"] = time.time()
            else:
                OTP_FORWARD_STATUS["failed"] = int(OTP_FORWARD_STATUS.get("failed", 0) or 0) + 1
                OTP_FORWARD_STATUS["last_error"] = error
        outcomes.append({"ok": ok, "chat_id": chat_id, "error": error})
    return outcomes


def forward_routed_otp_to_configured_groups(provider, otp, number, message_text, fast=True):
    """Forward an OTP for any currently assigned provider number.

    Group forwarding must not depend on whether that country was separately
    added to an admin service list.  The existing assigned-number route is the
    authority that the number belongs to this bot and provider.
    """
    route = _assigned_number_route(number, provider)
    if not isinstance(route, dict):
        return None
    service = str(route.get("service") or "").strip()
    country = str(route.get("country") or "").strip()
    if not service or not country:
        return None
    iso = _country_iso_from_full_name(country) or _country_short_name(country) or "XX"
    _service_name, premium_service = get_service_info_html(service, "")
    display_num = str(number)
    if not display_num.startswith("+"):
        display_num = "+" + display_num
    language = _lang_name(detect_language(message_text))
    group_text = build_otp_group_message(display_num, iso, premium_service, language)
    forward_otp_to_configured_groups(otp, group_text, fast=fast)
    return route

_callback_ack_pool = ThreadPoolExecutor(max_workers=32, thread_name_prefix="callback-ack")
# Manual-panel ingestion is isolated from the poller so panel polling never waits
# for Telegram sends, Firebase writes, or user notifications.
_manual_panel_processing_pool = ThreadPoolExecutor(max_workers=MANUAL_PANEL_PROCESSING_WORKERS, thread_name_prefix="manual-panel")
# Dedicated ingestion pool for Manual API panels. Each panel gets its own request
# worker so one slow provider never serializes the other Manual panels.
_manual_panel_fetch_pool = ThreadPoolExecutor(max_workers=MANUAL_PANEL_FETCH_WORKERS, thread_name_prefix="manual-fetch")
# Auto Captcha panels get their own parallel fetch/processing lanes so a slow
# captcha/session or CDR endpoint can never serialize other configured panels.
_auto_panel_fetch_pool = ThreadPoolExecutor(max_workers=AUTO_PANEL_FETCH_WORKERS, thread_name_prefix="auto-fetch")
_auto_panel_processing_pool = ThreadPoolExecutor(max_workers=AUTO_PANEL_PROCESSING_WORKERS, thread_name_prefix="auto-panel")
_auto_panel_http_sessions_by_id = {}
_auto_panel_fetch_inflight = set()
_auto_panel_fetch_lock = threading.RLock()
_auto_panel_next_due = {}
# Per-panel runtime state. Config data remains in bot_settings; this ephemeral
# state is intentionally separate so scheduler updates never rewrite panel config
# on every poll.
_auto_panel_runtime = {}
_auto_panel_runtime_lock = threading.RLock()
_auto_panel_binding_by_idx = {}
_manual_panel_http_sessions_by_id = {}
_manual_panel_fetch_inflight = set()
_manual_panel_fetch_lock = threading.RLock()
_manual_panel_next_due = {}
_broadcast_tls = threading.local()

def _get_broadcast_session():
    session = getattr(_broadcast_tls, "session", None)
    if session is None:
        session = requests.Session()
        adapter = HTTPAdapter(pool_connections=16, pool_maxsize=16, max_retries=0)
        session.mount("http://", adapter)
        session.mount("https://", adapter)
        session.headers.update({"User-Agent": "FRD-Bot-Broadcast/1.0"})
        _broadcast_tls.session = session
    return session

def _copy_message_one(user_id, from_chat_id, msg_id):
    session = _get_broadcast_session()
    url = f"{BASE_URL}/copyMessage"
    payload = {"chat_id": user_id, "from_chat_id": from_chat_id, "message_id": msg_id}
    for attempt in range(4):
        try:
            response = session.post(url, json=payload, timeout=(5, 15))
            try:
                data = response.json()
            except ValueError:
                data = {}

            if data.get("ok"):
                return True

            if data.get("error_code") == 429:
                retry_after = int(data.get("parameters", {}).get("retry_after", 1) or 1)
                time.sleep(min(max(retry_after, 1), 60))
                continue

            if response.status_code in (500, 502, 503, 504):
                time.sleep(min(2 ** attempt, 8))
                continue

            return False
        except (requests.exceptions.Timeout, requests.exceptions.ConnectionError):
            time.sleep(min(2 ** attempt, 8))
        except Exception:
            return False
    return False

def broadcast_copymessage(from_chat_id, msg_id):
    users = list(all_known_users)
    success = 0
    failed = 0
    if not users:
        send_message(from_chat_id, render_body_text("📢 <b>Broadcast Completed!</b>\n✅ Success: 0\n❌ Failed: 0\n👥 Total Sent: 0"))
        return

    futures = [
        _broadcast_pool.submit(_copy_message_one, uid, from_chat_id, msg_id)
        for uid in users
    ]
    for future in futures:
        try:
            if future.result():
                success += 1
            else:
                failed += 1
        except Exception:
            failed += 1

    send_message(
        from_chat_id,
        render_body_text(
            f"📢 <b>Broadcast Completed!</b>\n✅ Success: {success}\n❌ Failed: {failed}\n👥 Total Sent: {len(users)}"
        )
    )

def _refresh_user_index_for_broadcast(force=False):
    """Merge local user IDs with Firestore when needed.

    Automatic range alerts do not wait for this refresh; they use the current
    in-memory index immediately and refresh the index in the background.
    """
    global all_known_users
    now = time.time()
    last = getattr(_refresh_user_index_for_broadcast, "_last_refresh", 0.0)
    if not force and (now - last) < BROADCAST_USER_INDEX_TTL and all_known_users:
        return list(all_known_users)

    merged = set(all_known_users)
    try:
        if os.path.exists("users_list.json"):
            with open("users_list.json", "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, list):
                merged.update(str(x) for x in data if str(x).strip())
    except Exception as exc:
        _terminal_log(f"[Broadcast] local user index read failed: {exc}")

    all_known_users = merged
    _refresh_user_index_for_broadcast._last_refresh = now
    try:
        _save_users_list()
    except Exception:
        pass
    return list(all_known_users)


def _telegram_send_one(session, user_id, text):
    # Enforce the same premium-emoji outbound boundary used by normal sends.
    # This closes the direct-broadcast path that otherwise bypasses the renderer.
    text = render_user_body_text(text)
    url = f"{BASE_URL}/sendMessage"
    payload = {
        "chat_id": user_id,
        "text": text,
        "parse_mode": "HTML",
        "disable_web_page_preview": True,
    }
    if bot_settings.get("paid_broadcast", False):
        payload["allow_paid_broadcast"] = True

    for attempt in range(BROADCAST_MAX_RETRIES):
        try:
            response = session.post(
                url,
                json=payload,
                timeout=(BROADCAST_CONNECT_TIMEOUT, BROADCAST_READ_TIMEOUT),
            )
            try:
                data = response.json()
            except ValueError:
                data = {}

            if data.get("ok"):
                return True

            if data.get("error_code") == 429:
                retry_after = int(data.get("parameters", {}).get("retry_after", 1) or 1)
                time.sleep(min(max(retry_after, 1), 60))
                continue

            if response.status_code in (408, 425, 500, 502, 503, 504):
                time.sleep(min(0.5 * (2 ** attempt), 8))
                continue

            return False
        except (requests.exceptions.Timeout, requests.exceptions.ConnectionError):
            time.sleep(min(0.5 * (2 ** attempt), 8))
        except Exception:
            return False
    return False


def broadcast_text_to_all_users(text, force_user_refresh=False):
    """High-concurrency, retry-aware broadcast engine.

    The goal is simultaneous dispatch, not bypassing Telegram limits. With free
    broadcasts Telegram enforces its normal bulk-send limit; when paid broadcasts
    are enabled in BotFather and this setting is True, the Bot API supports the
    higher broadcast throughput.
    """
    users = _refresh_user_index_for_broadcast(force=force_user_refresh)
    if not users:
        _terminal_log("[Broadcast] skipped: no known users")
        return {"success": 0, "failed": 0, "total": 0}

    def _send(uid):
        session = _get_broadcast_session()
        return _telegram_send_one(session, uid, text)

    futures = [_broadcast_pool.submit(_send, uid) for uid in users]
    success = 0
    failed = 0
    for future in futures:
        try:
            if future.result():
                success += 1
            else:
                failed += 1
        except Exception:
            failed += 1

    result = {"success": success, "failed": failed, "total": len(users)}
    _terminal_log(f"[Broadcast] result={result} paid={bool(bot_settings.get('paid_broadcast', False))}")
    return result


def _send_range_alert_one(user_id, text):
    session = _get_broadcast_session()
    return _telegram_send_one(session, user_id, text)


def _broadcast_range_notification_async(text, label="range-change"):
    """Fast range-notification dispatcher.

    Uses the already-known user set immediately so a Firestore-wide index scan
    cannot delay the notification. A user-index refresh is triggered separately.
    """
    def _worker():
        try:
            users = list(all_known_users)
            if not users:
                users = _refresh_user_index_for_broadcast(force=True)
            else:
                # Refresh the user index without blocking the alert dispatch.
                threading.Thread(
                    target=_refresh_user_index_for_broadcast,
                    kwargs={"force": True},
                    daemon=True,
                    name=f"{label}-user-index",
                ).start()

            if not users:
                _terminal_log(f"[Broadcast:{label}] skipped: no known users")
                return

            start_ts = time.time()
            futures = []
            for uid in users:
                futures.append(_broadcast_pool.submit(_send_range_alert_one, str(uid), text))

            success = 0
            for future in futures:
                try:
                    success += int(bool(future.result()))
                except Exception:
                    pass
            elapsed_ms = (time.time() - start_ts) * 1000.0
            _terminal_log(
                f"[Broadcast:{label}] total={len(users)} success={success} "
                f"failed={len(users)-success} elapsed_ms={elapsed_ms:.1f}"
            )
        except Exception as exc:
            _terminal_log(f"[Broadcast:{label}] failed: {exc}")
    threading.Thread(target=_worker, daemon=True, name=label).start()

def _build_hourly_best_traffic_broadcast(window_seconds=None):
    """Build the hourly user recommendation from the canonical Active-Ranges analysis.

    This is a presentation-only view. Ranking uses only the latest canonical
    Active-Ranges snapshot; recent_traffic and zenex_range_meta are not ranking
    inputs. Each configured service contributes its single best country/range.
    """
    del window_seconds  # Kept for backward-compatible call signatures.
    analysis = _analysis_snapshot()
    services = analysis.get("services", {}) or {}
    configured = _configured_service_catalog()

    rows = []
    for _key, row in services.items():
        if not isinstance(row, dict):
            continue
        service = str(row.get("service", "") or "").strip()
        if not service:
            continue
        canonical = configured.get(_normalize_label(service), service)
        countries = [
            dict(x) for x in (row.get("countries", ()) or ())
            if isinstance(x, dict) and str(x.get("country", "") or "").strip()
        ]
        if not countries:
            continue
        countries.sort(key=lambda x: (
            -int(x.get("hits", 0) or 0),
            -int(x.get("top_range_hits", 0) or 0),
            _normalize_label(str(x.get("country", ""))),
        ))
        top = countries[0]
        rows.append((canonical, top))

    rows.sort(key=lambda item: (
        -int(item[1].get("hits", 0) or 0),
        _normalize_label(item[0]),
    ))

    if not rows:
        return render_user_body_text(
            "📊 <b>HOURLY PERFORMANCE ANALYSIS</b>\n\n"
            "<i>No current Active-Ranges analysis is available.</i>"
        ), 0

    lines = [
        "📊 <b>HOURLY PERFORMANCE ANALYSIS</b>",
        "━━━━━━━━━━━━━━━━━━━━",
    ]
    for service, top in rows:
        country = str(top.get("country", "") or "").strip()
        hits = int(top.get("hits", 0) or 0)
        rng = str(top.get("top_range", "") or "").strip()
        flag = _premium_flag_html_for_country(country)
        iso = _country_short_name(country).upper() or "XX"
        svc_html = _service_emoji_html(service) or "📱"
        lines.append("")
        lines.append(f"{svc_html} <b>{html.escape(_small_caps_text(service))}</b> {PEM['fire']}")
        lines.append(
            f"{flag} <b>{html.escape(_small_caps_text(country))} ({html.escape(iso)})</b> "
            f"— → {('<code>' + html.escape(rng) + '</code> ') if rng else ''}• <b>{hits} {_small_caps_text('hits')}</b> {PEM['fire']}"
        )

    return render_user_body_text("\n".join(lines)), len(rows)


def _send_admin_report_async(text, label="admin-report"):
    """Send a report only to owner/admin recipients, never to normal users."""
    if not text:
        return
    recipients = set()
    try:
        if str(OWNER_ID).lstrip("-").isdigit():
            recipients.add(int(OWNER_ID))
    except Exception:
        pass
    for value in (bot_settings.get("admins", []) or []):
        try:
            if str(value).lstrip("-").isdigit():
                recipients.add(int(value))
        except Exception:
            continue
    if not recipients:
        return
    def _worker():
        try:
            futures = []
            for uid in recipients:
                futures.append(_broadcast_pool.submit(_send_range_alert_one, str(uid), text))
            success = 0
            for f in futures:
                try:
                    success += int(bool(f.result()))
                except Exception:
                    pass
            _terminal_log(f"[Broadcast:{label}] admins={len(recipients)} success={success} failed={len(recipients)-success}")
        except Exception as exc:
            _terminal_log(f"[Broadcast:{label}] failed: {exc}")
    threading.Thread(target=_worker, daemon=True, name=label).start()


def hourly_best_traffic_broadcast_listener():
    """Send exactly one report after each completed one-hour analysis window."""
    global hourly_best_broadcast_last_ts

    try:
        last_ts = float(bot_settings.get("hourly_best_broadcast_last_ts", 0.0) or 0.0)
    except (TypeError, ValueError):
        last_ts = 0.0
    hourly_best_broadcast_last_ts = last_ts

    # First-ever run waits a full hour. After restart, continue from the last
    # persisted broadcast timestamp rather than emitting a duplicate immediately.
    if last_ts > 0:
        elapsed = max(0.0, time.time() - last_ts)
        initial_wait = max(1.0, HOURLY_BEST_BROADCAST_INTERVAL - elapsed)
    else:
        initial_wait = HOURLY_BEST_BROADCAST_INTERVAL
    next_run = time.monotonic() + initial_wait

    while True:
        try:
            if time.monotonic() >= next_run:
                with hourly_best_broadcast_lock:
                    now = time.time()
                    if hourly_best_broadcast_last_ts and (now - hourly_best_broadcast_last_ts) < (HOURLY_BEST_BROADCAST_INTERVAL - 1):
                        next_run = time.monotonic() + max(
                            1.0,
                            HOURLY_BEST_BROADCAST_INTERVAL - (now - hourly_best_broadcast_last_ts),
                        )
                        continue

                    text, service_count = _build_hourly_best_traffic_broadcast()
                    hourly_best_broadcast_last_ts = now
                    bot_settings["hourly_best_broadcast_last_ts"] = now
                    # Persist the cadence marker before async Telegram dispatch so a
                    # slow broadcast can never cause the next cycle to overlap.
                    save_local_db()

                    if text and service_count:
                        _broadcast_range_notification_async(
                            text,
                            label="hourly-best-traffic-broadcast",
                        )
                        # Always deliver the completed hourly analysis to owner/admins too,
                        # even if an admin is not present in the normal user index.
                        _send_admin_report_async(
                            text,
                            label="hourly-analysis-admin-copy",
                        )
                        _terminal_log(
                            f"[Broadcast:hourly-best] services={service_count} "
                            f"window={HOURLY_BEST_BROADCAST_WINDOW}s"
                        )
                    else:
                        _terminal_log("[Broadcast:hourly-best] completed window; no qualifying traffic")

                next_run = time.monotonic() + HOURLY_BEST_BROADCAST_INTERVAL
            # Sub-second scheduler sleep: low CPU, while keeping the trigger responsive.
            time.sleep(0.25)
        except Exception as exc:
            _terminal_log(f"[Broadcast:hourly-best] scheduler error: {exc}")
            next_run = time.monotonic() + min(60.0, HOURLY_BEST_BROADCAST_INTERVAL)
            time.sleep(1)

def _flatten_provider_ranges(state):
    result = {}
    for service, countries in (state or {}).items():
        if not isinstance(countries, dict):
            continue
        for country, ranges in countries.items():
            if isinstance(ranges, list):
                result[(str(service), str(country))] = list(ranges)
            elif ranges is None:
                result[(str(service), str(country))] = []
            else:
                result[(str(service), str(country))] = [str(ranges)]
    return result

def _provider_range_changes(before, after):
    """Return a change for every existing service/country range-list mutation.

    Add/remove/replace operations on an already-populated pair are real range
    changes and can trigger a notification. Pure list reordering is ignored.
    Initial population and complete removal are ignored by design.
    """
    old = _flatten_provider_ranges(before)
    new = _flatten_provider_ranges(after)
    changes = []
    for key in sorted(set(old) | set(new)):
        old_ranges = list(old.get(key, []))
        new_ranges = list(new.get(key, []))
        if not old_ranges or not new_ranges:
            continue
        if set(old_ranges) == set(new_ranges):
            continue

        old_top = old_ranges[0]
        new_top = new_ranges[0]
        if old_top != new_top:
            old_range = old_top
            new_range = new_top
        else:
            removed = [r for r in old_ranges if r not in new_ranges]
            added = [r for r in new_ranges if r not in old_ranges]
            old_range = removed[0] if removed else None
            new_range = added[0] if added else None

        changes.append({
            "service": key[0],
            "country": key[1],
            "old_range": old_range,
            "new_range": new_range,
            "old_ranges": old_ranges,
            "new_ranges": new_ranges,
            "hits": 0,
        })
    return changes


def _build_auto_range_change_broadcast(_provider, changes):
    """Build the public notification for any real service-range mutation."""
    lines = []
    for item in changes:
        service = str(item.get("service", "Unknown")).strip()
        raw_country = str(item.get("country", "Unknown")).strip()
        country = _country_full_name(raw_country)
        service_name, service_html = get_service_info_html(service)
        variant = _facebook_variant_label(service, item.get("tag", ""))
        display_service = f"{service_name} • {variant}" if variant else service_name
        country_html = _premium_flag_html_for_country(raw_country or country)
        old_range = item.get("old_range")
        new_range = item.get("new_range")
        old_ranges = [str(v) for v in item.get("old_ranges", []) if str(v).strip()]
        new_ranges = [str(v) for v in item.get("new_ranges", []) if str(v).strip()]

        if old_range and new_range:
            range_line = f"Range: <code>{html.escape(str(old_range))}</code> → <code>{html.escape(str(new_range))}</code>"
        else:
            added = [r for r in new_ranges if r not in old_ranges]
            removed = [r for r in old_ranges if r not in new_ranges]
            detail_lines = []
            if added:
                detail_lines.append("Added: " + ", ".join(f"<code>{html.escape(r)}</code>" for r in added))
            if removed:
                detail_lines.append("Removed: " + ", ".join(f"<code>{html.escape(r)}</code>" for r in removed))
            range_line = "<b>Range changed</b>"
            if detail_lines:
                range_line += "\n" + "\n".join(detail_lines)

        lines.append(
            f"{service_html} <b>{html.escape(display_service)}</b> {PEM['fire']} RANGE UPDATED\n"
            f"{country_html} <b>{html.escape(country)}</b>\n"
            f"{range_line}"
        )
    return render_body_text("\n\n".join(lines))

# User-facing English small-cap alphabet requested for all visible UI text.
_SMALLCAP = str.maketrans({
    "A":"ᴀ","B":"ʙ","C":"ᴄ","D":"ᴅ","E":"ᴇ","F":"ғ","G":"ɢ","H":"ʜ",
    "I":"ɪ","J":"ᴊ","K":"ᴋ","L":"ʟ","M":"ᴍ","N":"ɴ","O":"ᴏ","P":"ᴘ",
    "Q":"ǫ","R":"ʀ","S":"s","T":"ᴛ","U":"ᴜ","V":"ᴠ","W":"ᴡ","X":"x","Y":"ʏ","Z":"ᴢ",
    "a":"ᴀ","b":"ʙ","c":"ᴄ","d":"ᴅ","e":"ᴇ","f":"ғ","g":"ɢ","h":"ʜ",
    "i":"ɪ","j":"ᴊ","k":"ᴋ","l":"ʟ","m":"ᴍ","n":"ɴ","o":"ᴏ","p":"ᴘ",
    "q":"ǫ","r":"ʀ","s":"s","t":"ᴛ","u":"ᴜ","v":"ᴠ","w":"ᴡ","x":"x","y":"ʏ","z":"ᴢ",
})


def stylize_visible_text(value):
    text = str(value or "")
    # Protect markup tags and plain URLs; Telegram deep links must remain ASCII
    # or the small-cap UI font turns ``https://t.me/...`` into a dead link.
    chunks = re.split(r"(<[^>]+>|https?://[^\s<>\"']+)", text, flags=re.I)
    for i, chunk in enumerate(chunks):
        if not chunk.startswith("<") and not re.match(r"https?://", chunk, re.I):
            chunks[i] = chunk.translate(_SMALLCAP)
    return "".join(chunks)


def _stylize_keyboard(markup):
    if not isinstance(markup, dict):
        return markup
    out = json.loads(json.dumps(markup, ensure_ascii=False))
    rows = out.get("inline_keyboard")
    if isinstance(rows, list):
        for row in rows:
            if not isinstance(row, list):
                continue
            for button in row:
                if isinstance(button, dict) and "text" in button:
                    button["text"] = stylize_visible_text(button.get("text", ""))
    return out


def _stylize_api_payload(payload):
    if not isinstance(payload, dict):
        return payload
    out = json.loads(json.dumps(payload, ensure_ascii=False))
    def walk(obj):
        if isinstance(obj, dict):
            for key, value in list(obj.items()):
                if key in {"text", "caption"} and isinstance(value, str):
                    obj[key] = render_body_text(value)
                elif key == "reply_markup":
                    obj[key] = _stylize_keyboard(value)
                elif isinstance(value, (dict, list)):
                    walk(value)
        elif isinstance(obj, list):
            for item in obj:
                walk(item)
    walk(out)
    return out



_USER_HIDDEN_PROVIDER_NAMES = (
    "STEXSMS", "VOLTXSMS", "ZENEXNETWORK", "STEX", "VOLTX", "ZENEX",
)


def _hide_provider_names_from_user(text):
    """Remove provider identity/suffixes from user-visible text while preserving admin views.

    User-facing service labels are destination names only. Provider suffixes such as
    ``_ZNX``/``_VTX``/``_STEX`` and standalone provider names are never shown.
    """
    raw = str(text or "")
    if not raw:
        return raw

    # First remove common provider suffixes attached directly to service names,
    # e.g. ``FACEBOOK_ZNX`` -> ``FACEBOOK``.
    raw = re.sub(r"(?i)(?<![A-Za-z0-9])([A-Za-z][A-Za-z0-9 &()'./-]*?)(?:[_\- ]+)(?:ZNX|VTX|STEX)(?![A-Za-z0-9])", r"\1", raw)

    # Then remove standalone provider identities.
    for name in sorted(_USER_HIDDEN_PROVIDER_NAMES, key=len, reverse=True):
        raw = re.sub(rf"(?<![A-Za-z0-9]){re.escape(name)}(?![A-Za-z0-9])", "", raw, flags=re.I)

    # Cleanup whitespace left behind by provider removal.
    raw = re.sub(r"[ \t]{2,}", " ", raw)
    raw = re.sub(r"[ \t]+([|•·:/])", r" \1", raw)
    raw = re.sub(r"([|•·:/])[ \t]+", r"\1 ", raw)
    return raw.strip()


def render_user_body_text(text):
    """User-facing renderer: provider names are hidden and admin-uploaded emojis win."""
    return render_body_text(_hide_provider_names_from_user(text))

def render_body_text(text):
    if not text:
        return str(text)
    parts = re.split(r"(<tg-emoji.*?</tg-emoji>)", str(text), flags=re.S)
    configured = bot_settings.get("premium_body_emojis", {}) if isinstance(bot_settings, dict) else {}
    emoji_map = {}
    if isinstance(configured, dict):
        for normal_emj, raw_id in configured.items():
            eid = str(raw_id or "").strip()
            if normal_emj and eid.isdigit():
                emoji_map[str(normal_emj)] = eid
    # Uploaded flag/app/language emojis are also authoritative mappings.
    for store_key in ("premium_flags", "premium_apps", "premium_languages"):
        store = bot_settings.get(store_key, {}) if isinstance(bot_settings, dict) else {}
        if isinstance(store, dict):
            for data in store.values():
                if not isinstance(data, dict):
                    continue
                ch = str(data.get("char") or data.get("emoji") or "")
                eid = str(data.get("id") or "").strip()
                if ch and eid.isdigit():
                    emoji_map[ch] = eid
    # Safe bootstrap defaults remain only for any emoji not yet uploaded by admin.
    # Admin-uploaded mappings above always win.
    for normal_emj, prem_id in GLOBAL_BODY_EMOJIS.items():
        emoji_map.setdefault(normal_emj, str(prem_id))
    for normal_emj, prem_id in PREMIUM_EMOJI_FALLBACKS.items():
        if str(prem_id).isdigit():
            emoji_map.setdefault(normal_emj, str(prem_id))

    for i in range(len(parts)):
        if not parts[i].startswith("<tg-emoji"):
            # Longest-first avoids partial replacement of multi-codepoint emoji.
            for normal_emj, prem_id in sorted(emoji_map.items(), key=lambda kv: len(kv[0]), reverse=True):
                if normal_emj in parts[i]:
                    parts[i] = parts[i].replace(normal_emj, f'<tg-emoji emoji-id="{prem_id}">{normal_emj}</tg-emoji>')
            parts[i] = stylize_visible_text(parts[i])
    return "".join(parts)

def extract_premium_html(msg):
    text = msg.get("text", msg.get("caption", ""))
    entities = msg.get("entities", msg.get("caption_entities", []))
    if not entities: return text
    try:
        b_text = text.encode('utf-16-le')
        c_entities = [e for e in entities if e.get("type") == "custom_emoji"]
        c_entities.sort(key=lambda x: x["offset"], reverse=True)
        for ent in c_entities:
            offset = ent["offset"] * 2
            length = ent["length"] * 2
            eid = ent["custom_emoji_id"]
            emoji_char = b_text[offset:offset+length].decode('utf-16-le')
            html_tag = f'<tg-emoji emoji-id="{eid}">{emoji_char}</tg-emoji>'
            replacement = html_tag.encode('utf-16-le')
            b_text = b_text[:offset] + replacement + b_text[offset+length:]
        return b_text.decode('utf-16-le')
    except Exception as e:
        return text 

def get_flag_info_from_num(num):
    clean = num.replace("+", "").replace(" ", "")
    sorted_codes = sorted(bot_settings.get("premium_flags", {}).keys(), key=len, reverse=True)
    for code in sorted_codes:
        if clean.startswith(code):
            data = bot_settings["premium_flags"][code]
            return data["char"], data.get("iso", "XX"), data.get("id")
    return "🌍", "XX", None

def get_flag_and_code(num):
    char, iso, _ = get_flag_info_from_num(num)
    return char, iso

def _country_display_from_number(number):
    """Resolve a number to ISO, full country name and a standard Unicode flag.

    This helper is intentionally isolated from ``get_flag_and_code`` so the OTP
    receive/forward pipeline keeps its existing behavior.
    """
    raw = re.sub(r"\D", "", str(number or ""))
    if not raw:
        return "XX", "Unknown", "🌍"

    try:
        _char, iso, _eid = get_flag_info_from_num(raw)
    except Exception:
        iso = "XX"

    iso = str(iso or "XX").upper()
    if iso != "XX":
        full_name = _country_full_name(iso)
        if full_name and full_name != iso:
            return iso, full_name, _country_flag_emoji_from_iso(iso)

    # Fall back to the bundled calling-code directory for numbers whose country
    # is not configured in premium_flags (for example +261 = Madagascar).
    try:
        matches = []
        for key, values in (ZENEX_COUNTRY_CALLING_CODES or {}).items():
            if str(key).isalpha() and len(str(key)) <= 4:
                continue
            for code in values or []:
                code = str(code).strip()
                if code and raw.startswith(code):
                    matches.append((len(code), str(key).strip(), code))
        if matches:
            _, country_name, _code = max(matches, key=lambda item: item[0])
            iso_guess = _country_iso_from_full_name(country_name)
            return iso_guess, country_name, _country_flag_emoji_from_iso(iso_guess)
    except Exception:
        pass

    return iso, (full_name if iso != "XX" else "Unknown"), _country_flag_emoji_from_iso(iso)

def _country_iso_from_full_name(country_name):
    target = _normalize_label(country_name)
    if not target:
        return "XX"
    for code, data in (bot_settings.get("premium_flags", {}) or {}).items():
        if _normalize_label(data.get("name", "")) == target:
            return str(data.get("iso", "XX")).upper()
    # Static directory pairs the full country name with its ISO alias.
    for idx, (key, values) in enumerate((ZENEX_COUNTRY_CALLING_CODES or {}).items()):
        if _normalize_label(key) != target:
            continue
        codes = set(str(x) for x in (values or []))
        for other, other_values in (ZENEX_COUNTRY_CALLING_CODES or {}).items():
            if other == key or not str(other).isalpha() or len(str(other)) != 2:
                continue
            if codes & set(str(x) for x in (other_values or [])):
                return str(other).upper()
    return "XX"


def _country_flag_emoji_from_iso(iso_or_name):
    value = str(iso_or_name or "").strip().upper()
    if len(value) == 2 and value.isalpha():
        return "".join(chr(0x1F1E6 + ord(c) - 65) for c in value)
    return "🌍"


def get_flag_info_html(num_or_iso, return_full_name=False):
    if len(num_or_iso) == 2:
        for code, data in bot_settings.get("premium_flags", {}).items():
            if data.get("iso") == num_or_iso:
                eid = data.get("id")
                char = data.get("char")
                name = data.get("name", num_or_iso)
                if return_full_name: return name
                if eid: return f'<tg-emoji emoji-id="{eid}">{char}</tg-emoji>'
                return char
        if return_full_name: return num_or_iso
        return "🌍"
        
    char, _, eid = get_flag_info_from_num(num_or_iso)
    if return_full_name:
        for code, data in bot_settings.get("premium_flags", {}).items():
            clean = num_or_iso.replace("+", "").replace(" ", "")
            if clean.startswith(code): return data.get("name", num_or_iso)
        return num_or_iso
        
    if eid:
        return f'<tg-emoji emoji-id="{eid}">{char}</tg-emoji>'
    return char

def _number_country_display_html(number):
    """Return admin-configured premium flag + canonical country + ISO short code.

    The number screen must use the exact premium flag configured through the Admin
    panel, never a plain Unicode fallback when a matching configured entry exists.
    """
    iso, country, _fallback_flag = _country_display_from_number(number)
    iso = str(iso or "XX").strip().upper()
    country = str(country or "Unknown").strip() or "Unknown"
    premium_flag = _premium_flag_html_for_country(iso)
    short_name = _country_short_name(iso) or iso
    short_name = str(short_name or iso).strip().upper()
    return premium_flag, country, short_name


def mask_number(num):
    clean = num.replace("+", "").replace(" ", "")
    # Deliberately use stylish typographic symbols around FRD; no emoji entities.
    if len(clean) > 6: return f"{clean[:3]}❖XXX❖{clean[-3:]}"
    elif len(clean) > 2: return f"{clean[:1]}❖XXX❖{clean[-1:]}"
    return clean

