def detect_service(text):
    text_lower = str(text).lower()
    for service_key, keywords in SERVICE_SMS_KEYWORDS.items():
        for kw in keywords:
            if kw in text_lower:
                return service_key.upper()
    return None

def get_service_info_html(service_text, msg_text=""):
    """Return the configured display name plus the best matching Premium Emoji.

    The administrator's service label remains authoritative. OTP message text is
    used only to infer a logo when no explicit service label was supplied.
    """
    provided = str(service_text or "").strip()
    display_name = _pretty_service_display_name(provided) if provided else ""
    detected_key = _detected_fixed_service_key(display_name) if display_name else ""

    if not detected_key and not display_name and msg_text:
        try:
            detected = detect_service(msg_text)
            if detected:
                detected_key = _detected_fixed_service_key(detected) or _normalize_label(detected)
                display_name = _pretty_service_display_name(str(detected).strip())
        except Exception:
            pass

    apps = bot_settings.get("premium_apps", {}) or {}

    # Admin-uploaded Premium App Emoji is always authoritative. Fixed service
    # logos are only a fallback when no matching admin record exists.
    target_aliases = _service_emoji_aliases(display_name or service_text)
    if isinstance(apps, dict):
        for app_name, data in apps.items():
            if not isinstance(data, dict):
                continue
            aliases = {
                _normalize_label(str(app_name)),
                _normalize_label(str(data.get("name", ""))),
                _normalize_label(str(data.get("service", ""))),
            }
            if target_aliases & aliases:
                visible = _pretty_service_display_name(display_name or str(data.get("name") or app_name))
                char = str(data.get("char") or "📱")
                eid = str(data.get("id") or "").strip()
                return visible, (f'<tg-emoji emoji-id="{eid}">{html.escape(char)}</tg-emoji>' if eid.isdigit() else html.escape(char))

    if detected_key:
        fixed_id = FIXED_PREMIUM_SERVICE_EMOJI_IDS.get(detected_key)
        if fixed_id:
            return display_name or detected_key.replace("_", " ").title(), f'<tg-emoji emoji-id="{fixed_id}">📱</tg-emoji>'

    return (display_name or "Service"), ""

def _country_flag_emoji(country):
    """Return a compact Unicode flag from the resolved ISO-2 code."""
    iso = _country_short_name(country).strip().upper()
    if len(iso) != 2 or not iso.isalpha():
        return "🌐"
    return "".join(chr(0x1F1E6 + (ord(ch) - ord("A"))) for ch in iso)

def _country_short_name(country):
    """Resolve a configured country to its ISO short name for display only."""
    raw = str(country or "").strip()
    norm = _normalize_label(raw)
    for code, data in bot_settings.get("premium_flags", {}).items():
        iso = str(data.get("iso", "")).strip().upper()
        name = str(data.get("name", "")).strip()
        aliases = {_normalize_label(str(code)), _normalize_label(iso), _normalize_label(name)}
        if norm in aliases:
            return iso or str(code)
    # The country may not yet have a Premium Flag entry.  Resolve its ISO-2
    # short name from the built-in calling-code pairs (e.g. Ghana -> GH).
    for name, calling_codes in (ZENEX_COUNTRY_CALLING_CODES or {}).items():
        if _normalize_label(name) != norm or (name.isalpha() and 2 <= len(name) <= 4):
            continue
        target_codes = tuple(str(code) for code in (calling_codes or []))
        for iso, iso_codes in (ZENEX_COUNTRY_CALLING_CODES or {}).items():
            if iso.isalpha() and len(iso) == 2 and tuple(str(code) for code in (iso_codes or [])) == target_codes:
                return iso.upper()
    # Final universal resolver: accepts official country names with accents,
    # apostrophes and alternate display casing, even without a Premium Flag.
    if pycountry is not None:
        candidates = (raw, raw.replace("’", "'"), raw.replace("'", " "))
        for candidate in candidates:
            try:
                return str(pycountry.countries.lookup(candidate).alpha_2).upper()
            except (LookupError, AttributeError):
                pass
        try:
            matches = pycountry.countries.search_fuzzy(raw)
            if matches:
                return str(matches[0].alpha_2).upper()
        except (LookupError, AttributeError):
            pass
    return raw.upper()


COMMON_COUNTRY_BROADCAST_ALIASES = {
    "uk": "United Kingdom",
    "gb": "United Kingdom",
    "usa": "United States",
    "us": "United States",
    "uae": "United Arab Emirates",
    "u.a.e.": "United Arab Emirates",
    "ksa": "Saudi Arabia",
}

def _country_full_name(country):
    """Resolve ISO/short/full country labels to a full country name for broadcasts."""
    raw = str(country or "").strip()
    if not raw:
        return "Unknown"
    norm = _normalize_label(raw)
    if not norm:
        return "Unknown"

    alias = COMMON_COUNTRY_BROADCAST_ALIASES.get(norm)
    if alias:
        return alias

    for code, data in (bot_settings.get("premium_flags", {}) or {}).items():
        aliases = {_normalize_label(code), _normalize_label(data.get("iso", "")), _normalize_label(data.get("name", ""))}
        if norm in aliases:
            return str(data.get("name") or raw).strip() or "Unknown"

    items = list((ZENEX_COUNTRY_CALLING_CODES or {}).items())
    # Numeric calling-code labels are valid short country inputs when they
    # uniquely identify a country in the built-in dataset.
    if raw.isdigit():
        numeric = norm
        for key, values in items:
            if key.isalpha() and 2 <= len(key) <= 4:
                continue
            if any(str(v).strip() == numeric for v in (values or [])):
                return str(key).strip()

    for key, values in items:
        if _normalize_label(key) == norm and not (key.isalpha() and 2 <= len(key) <= 4):
            return str(key).strip()

    for idx, (key, values) in enumerate(items):
        if key.isalpha() and 2 <= len(key) <= 4 and norm == _normalize_label(key):
            wanted = tuple(str(x) for x in values)
            for maybe_name, maybe_values in reversed(items[:idx]):
                if maybe_name.isalpha() and 2 <= len(maybe_name) <= 4:
                    continue
                if tuple(str(x) for x in maybe_values) == wanted:
                    return str(maybe_name).strip()
            for maybe_name, maybe_values in items:
                if maybe_name == key or (maybe_name.isalpha() and 2 <= len(maybe_name) <= 4):
                    continue
                if tuple(str(x) for x in maybe_values) == wanted:
                    return str(maybe_name).strip()
    return raw

def _language_display(lang_code):
    """Return configured language name and premium emoji from an ISO-like language code."""
    code = str(lang_code or "EN").lstrip("#").upper()
    configured = bot_settings.get("premium_languages", {}) or {}
    item = configured.get(code, {}) if isinstance(configured, dict) else {}
    name = str(item.get("name") or LANG_MAP.get("#" + code) or code).strip()
    char = str(item.get("char") or "🗣")
    eid = str(item.get("id") or GLOBAL_BODY_EMOJIS.get(char) or PREMIUM_EMOJI_FALLBACKS.get(char) or "5355102594886833928")
    emoji_html = f'<tg-emoji emoji-id="{eid}">{html.escape(char)}</tg-emoji>' if eid.isdigit() else render_body_text(char)
    return name, emoji_html

def _display_width(value):
    """Approximate Telegram's rendered text width in character units."""
    text = str(value or "")
    width = 0
    for ch in text:
        if unicodedata.combining(ch):
            continue
        if unicodedata.east_asian_width(ch) in {"W", "F"}:
            width += 2
        else:
            width += 1
    return width


def _plain_display_text(value):
    """Remove Telegram HTML/custom-emoji tags before measuring text."""
    text = str(value or "")
    text = re.sub(r"<tg-emoji[^>]*>(.*?)</tg-emoji>", lambda m: m.group(1), text, flags=re.S | re.I)
    text = re.sub(r"<[^>]+>", "", text)
    return html.unescape(text)


def _keyboard_width_units(reply_markup):
    """Estimate the width of the widest inline-keyboard row."""
    if not isinstance(reply_markup, dict):
        return 0
    rows = reply_markup.get("inline_keyboard")
    if not isinstance(rows, list):
        return 0

    widest = 0
    for row in rows:
        if not isinstance(row, list) or not row:
            continue
        row_width = 0
        valid_buttons = 0
        for button in row:
            if not isinstance(button, dict):
                continue
            valid_buttons += 1
            label = _plain_display_text(button.get("text", ""))
            # Approximate button-cell padding plus icon space.
            button_width = max(4, _display_width(label)) + 4
            if button.get("icon_custom_emoji_id"):
                button_width += 2
            row_width += button_width
        if valid_buttons > 1:
            row_width += (valid_buttons - 1) * 2
        widest = max(widest, row_width)
    return widest


def _balance_text_to_inline_keyboard(text, reply_markup, extra_units=3):
    """Align message-bubble separators with the widest inline-keyboard row.

    Telegram does not expose a direct bubble-width control. For screens that
    contain a full-width button row (for example Refresh/Close/Back), divider
    lines are normalized to the same visual width instead of leaving shorter
    15–20 character separators that make the text bubble look narrower than
    the keyboard. Existing non-divider content is never rewritten.
    """
    raw = str(text or "").strip()
    if not raw or not isinstance(reply_markup, dict):
        return raw
    rows = reply_markup.get("inline_keyboard")
    if not isinstance(rows, list) or not rows:
        return raw

    # A single-button row is Telegram's visual full-width master for these
    # panels (Refresh Ranges, Close, Back, etc.).
    has_full_width_row = any(
        isinstance(row, list) and len(row) == 1 and isinstance(row[0], dict)
        for row in rows
    )

    if has_full_width_row:
        # Telegram's single-button row is rendered at a stable near-maximum width.
        # Keep every divider at the same width so text bubbles and controls line up.
        target = 51 + max(0, int(extra_units))
        target = min(target, 54)

        def _is_divider(line):
            stripped = str(line or "").strip()
            if len(stripped) < 5:
                return False
            divider_chars = set("━─═—_")
            return all(ch in divider_chars for ch in stripped)

        # Normalize existing divider-only lines in-place so screens such as
        # System Settings, 2FA, Speed Up Control and LIVE TRAFFIC stay aligned.
        lines = raw.splitlines()
        changed = False
        for idx, line in enumerate(lines):
            if _is_divider(line):
                lines[idx] = "━" * target
                changed = True
        if changed:
            return "\n".join(lines)

        visible_lines = _plain_display_text(raw).splitlines() or [""]
        current_width = max((_display_width(line) for line in visible_lines), default=0)
        if current_width >= target:
            return raw
        return raw + "\n" + ("━" * target)

    target = _keyboard_width_units(reply_markup) + max(0, int(extra_units))
    target = max(24, min(51, target))
    visible_lines = _plain_display_text(raw).splitlines() or [""]
    current_width = max((_display_width(line) for line in visible_lines), default=0)
    if current_width >= target:
        return raw
    return raw + "\n" + ("━" * target)


def _balance_ui_message(text, min_chars=28):
    """Visually balance short standalone OTP messages."""
    raw = str(text or "").strip()
    if not raw:
        return raw
    plain = _plain_display_text(raw)
    if max((_display_width(line) for line in plain.splitlines()), default=0) >= min_chars:
        return raw
    if "━━━━━━━━━━━━━━━━━━━━" in raw:
        return raw
    return raw + "\n━━━━━━━━━━━━━━━━━━━━"


def _two_column_rows(items):
    rows = []
    row = []
    for item in items:
        row.append(item)
        if len(row) == 2:
            rows.append(row)
            row = []
    if row:
        rows.append(row)
    return rows

