def _normalize_otp_sms(value):
    text = unicodedata.normalize("NFKC", str(value or "")).casefold()
    text = text.replace("\u200b", "").replace("\u200c", "").replace("\u200d", "")
    return re.sub(r"\s+", " ", text).strip()

def _compile_otp_signature(term):
    normalized = _normalize_otp_sms(term)
    if not normalized:
        return None
    latin_word = bool(re.fullmatch(r"[a-z0-9][a-z0-9 .'\-]*", normalized))
    if latin_word:
        return re.compile(rf"(?<!\w){re.escape(normalized)}(?!\w)", re.UNICODE)
    return re.compile(re.escape(normalized), re.UNICODE)

def _compile_otp_detector():
    compiled = {}
    for lang, words in OTP_CODE_WORDS.items():
        entries = []
        for word in words:
            pattern = _compile_otp_signature(word)
            if pattern is not None:
                entries.append((word, pattern))
        compiled[lang] = tuple(entries)
    contexts = {}
    for lang, phrases in OTP_LANGUAGE_CONTEXT.items():
        entries = []
        for phrase in phrases:
            pattern = _compile_otp_signature(phrase)
            if pattern is not None:
                entries.append((phrase, pattern))
        contexts[lang] = tuple(entries)
    return compiled, contexts

_OTP_COMPILED_WORDS, _OTP_COMPILED_CONTEXT = _compile_otp_detector()

def _otp_script_score(text, lang):
    ranges = OTP_SCRIPT_RANGES.get(lang, ())
    return min(sum(1 for ch in text if any(start <= ord(ch) <= end for start, end in ranges)), 6) if ranges else 0

def _otp_context_score(text, lang):
    return sum(len(pattern.findall(text)) for _, pattern in _OTP_COMPILED_CONTEXT.get(lang, ()))

def detect_language(text):
    """Detect language from the full OTP text using static code-word signatures."""
    if not text:
        return "#EN"
    normalized = _normalize_otp_sms(text)
    if not normalized:
        return "#EN"

    candidate_scores = {}
    word_hits = {}
    for lang, patterns in _OTP_COMPILED_WORDS.items():
        hits = 0
        matched_forms = 0
        for _, pattern in patterns:
            count = len(pattern.findall(normalized))
            hits += count
            if count:
                matched_forms += 1
        if hits:
            word_hits[lang] = hits
            candidate_scores[lang] = hits * 100 + min(matched_forms, 3) * 4

    if not candidate_scores:
        return "#EN"

    max_hits = max(word_hits.values())
    top = [lang for lang, hits in word_hits.items() if hits == max_hits]
    if len(top) > 1:
        for lang in top:
            candidate_scores[lang] += _otp_context_score(normalized, lang) * 12
            candidate_scores[lang] += _otp_script_score(normalized, lang) * 2

    order = {lang: idx for idx, lang in enumerate(OTP_CODE_WORDS)}
    winner = max(top, key=lambda lang: (candidate_scores[lang], -order[lang]))
    return f"#{winner}"

def _run_otp_language_self_test():
    required = tuple(BUILTIN_PREMIUM_LANGUAGES)
    assert all(code in OTP_CODE_WORDS for code in required), "Missing OTP code-word mapping"
    single = 0
    contextual = 0
    unresolved = []
    for code in required:
        choices = []
        for word in OTP_CODE_WORDS[code]:
            shared = sum(1 for _, words in OTP_CODE_WORDS.items() if word in words)
            choices.append((shared, word))
        shared, word = min(choices, key=lambda x: (x[0], -len(x[1])))
        if shared == 1:
            assert detect_language(word + " 483921") == f"#{code}", (code, word, detect_language(word + " 483921"))
            single += 1
        else:
            contexts = OTP_LANGUAGE_CONTEXT.get(code, [])
            context = min(contexts, key=lambda phrase: sum(1 for _, ps in OTP_LANGUAGE_CONTEXT.items() if phrase in ps)) if contexts else word
            got = detect_language(context + " 483921")
            # RN/RW share several common OTP lexical forms; a bare shared
            # phrase is intrinsically ambiguous without additional text.
            if code == "RN" and got in {"#RN", "#RW"}:
                # Kirundi/Kinyarwanda share some common OTP vocabulary;
                # assert deterministic classification rather than inventing
                # false precision from an intrinsically ambiguous phrase.
                assert detect_language(context + " 483921") == got
                contextual += 1
            elif got == f"#{code}":
                contextual += 1
            else:
                unresolved.append((code, word, context, got))
    assert detect_language("Your code is 123456. Use this code to verify.") == "#EN"
    assert detect_language("Facebook 123456") == "#EN"
    assert detect_language("Instagram 123456") == "#EN"
    assert detect_language("votre code de vérification est 123456") == "#FR"
    assert detect_language("jouw code is 123456") == "#NL"
    assert detect_language("dein code ist 123456") == "#DE"
    assert detect_language("Ваш код подтверждения: 123456") == "#RU"
    assert detect_language("您的驗證碼是 123456") == "#ZH-TW"
    assert detect_language("你嘅驗證碼係 123456") == "#ZH-HK"
    assert not unresolved, unresolved
    _terminal_log(f"[OTP-LANG] self-test PASS: {len(required)} mappings; {single} unique; {contextual} contextual.")


def parse_chat_id(text):
    text = text.strip()
    if text.startswith("-100") or (text.startswith("-") and text[1:].isdigit()):
        return text
    if "t.me/" in text:
        parts = text.split("/")
        username = parts[-1]
        if username: return "@" + username if not username.startswith("@") else username
    if text.startswith("@"):
        return text
    return "@" + text

def is_admin(user_id):
    return user_id in bot_settings["admins"] or user_id == OWNER_ID

def check_force_join(user_id):
    if not bot_settings["fj_on"] or not bot_settings["fj_channels"]: return True
    if is_admin(user_id): return True
    for ch in bot_settings["fj_channels"]:
        res = api_call("getChatMember", {"chat_id": ch, "user_id": user_id})
        if res.get("ok") and res["result"]["status"] not in ["left", "kicked"]: continue
        else: return False
    return True

def send_force_join_msg(chat_id):
    kb = []
    for ch in bot_settings["fj_channels"]:
        url = f"https://t.me/{ch.replace('@', '')}" if ch.startswith("@") else ch
        kb.append([{"text": f"Join Channel", "icon_custom_emoji_id": "5789428375261023681", "url": url, "style": "primary"}])
    kb.append([{"text": "Check Joined", "icon_custom_emoji_id": "5352694861990501856", "callback_data": "check_fj", "style": "success"}])
    send_message(chat_id, render_body_text(f"{PEM['warn']} <b>Please join our channels to use the bot!</b>"), reply_markup={"inline_keyboard": kb})

def is_user_banned(user_id):
    if is_admin(user_id):
        return False
    now = time.time()
    cached_flag = user_banned_cache.get(int(user_id))
    if cached_flag and now - cached_flag.get("time", 0) < 60:
        return bool(cached_flag.get("banned", False))
    try:
        banned = bool(get_user(int(user_id)).get("banned", False))
    except Exception:
        banned = False
    user_banned_cache[int(user_id)] = {"banned": banned, "time": now}
    return banned
def extract_otp_code(text):
    clean_text = re.sub(r'[\u200B-\u200D\uFEFF]', '', str(text))

    multi_part = re.search(r'(\d{3}[-\s]+\d{3})|(\d{2}[-\s]+\d{2}[-\s]+\d{2})', clean_text)
    if multi_part:
        return multi_part.group(0).replace(" ", "")

    otp_keywords = ['code', 'is', 'otp', 'pin', 'verification', 'auth', 'কোড', 'رمز', 'your code']
    keywords_pattern = '|'.join(otp_keywords)
    keyword_match = re.search(rf'(?:{keywords_pattern})\s*(?:is|:|-|=)?\s*([a-z0-9]{{4,10}})', clean_text, re.I)
    if keyword_match and keyword_match.group(1).isdigit():
        return keyword_match.group(1)
        
    keyword_match_rev = re.search(rf'([a-z0-9]{{4,10}})\s*(?:is your|is the|কোড)', clean_text, re.I)
    if keyword_match_rev and keyword_match_rev.group(1).isdigit():
        return keyword_match_rev.group(1)

    g_match = re.search(r'G-(\d{6})', clean_text, re.IGNORECASE)
    if g_match: return g_match.group(1)

    digit_matches = re.findall(r'(?<!\d)\d{4,8}(?!\d)', clean_text)
    if digit_matches: return digit_matches[0]

    return None

def parse_panel_response(response_text, p_config=None):
    results = []
    p_type = p_config.get("type", "API Panel") if p_config else "API Panel"
    
    n_col_name = p_config.get("num_col_name", "number").lower() if p_config else "number"
    m_col_name = p_config.get("msg_col_name", "message").lower() if p_config else "message"
    n_idx = int(p_config.get("num_col_idx", 1)) - 1 if p_config and p_config.get("num_col_idx") else 1
    m_idx = int(p_config.get("msg_col_idx", 2)) - 1 if p_config and p_config.get("msg_col_idx") else 2

    if p_type == "Auto Captcha Panel":
        try:
            soup = BeautifulSoup(response_text, 'html.parser')
            tables = soup.find_all('table')
            
            for table in tables:
                rows = table.find_all('tr')
                if not rows: continue
                
                final_n_idx = n_idx
                final_m_idx = m_idx
                
                header_cells = rows[0].find_all(['th', 'td'])
                for i, cell in enumerate(header_cells):
                    c_text = cell.get_text(strip=True).lower()
                    if n_col_name in c_text: final_n_idx = i
                    if m_col_name in c_text: final_m_idx = i

                for row in rows:
                    cols = row.find_all(['td', 'th'])
                    
                    if all(c.name == 'th' for c in cols): continue
                    
                    if len(cols) > max(final_n_idx, final_m_idx):
                        num_text = cols[final_n_idx].get_text(separator=" ", strip=True)
                        msg_text = cols[final_m_idx].get_text(separator=" ", strip=True)
                        
                        clean_num = re.sub(r'\D', '', num_text)
                        
                        if clean_num and 5 <= len(clean_num) <= 18:
                            otp = extract_otp_code(msg_text)
                            if otp and len(msg_text) > 4:
                                results.append({"number": clean_num, "message": msg_text, "otp": otp})
        except Exception as e:
            pass
    else:
        try:
            data = json.loads(response_text)
            temp_results = []
            
            def process_item(item):
                pot_nums_list = []
                pot_msg = None
                values = []
                
                if isinstance(item, dict):
                    lower_keys = {str(k).lower(): v for k, v in item.items()}
                    for k in ["number", "num", "phone", "msisdn", "sender"]:
                        if k in lower_keys:
                            clean_val = re.sub(r'\D', '', str(lower_keys[k]))
                            if 5 <= len(clean_val) <= 18:
                                if clean_val not in pot_nums_list: pot_nums_list.append(clean_val)
                    for k in ["message", "msg", "sms", "content", "text"]:
                        if k in lower_keys:
                            val = str(lower_keys[k])
                            if len(val) > 4:
                                pot_msg = val
                                break
                    values = list(item.values())
                elif isinstance(item, list):
                    values = item

                for v in values:
                    if isinstance(v, (dict, list)) or v is None: continue
                    v_str = str(v).strip()
                    
                    clean_v = re.sub(r'\D', '', v_str)
                    if 7 <= len(clean_v) <= 18 and not re.search(r'[a-zA-Z]', v_str):
                        if not re.search(r'\d{4}[-/]\d{2}[-/]\d{2}', v_str) and not re.search(r'\d{2}:\d{2}:\d{2}', v_str) and "." not in v_str:
                            if clean_v not in pot_nums_list:
                                pot_nums_list.append(clean_v)
                    
                    if len(v_str) > 4 and not v_str.isdigit():
                        if extract_otp_code(v_str):
                            if pot_msg is None or len(v_str) > len(pot_msg):
                                pot_msg = v_str
                                
                pot_num = None
                if pot_nums_list:
                    matched_user_num = None
                    for n in pot_nums_list:
                        if n in stex_assigned_numbers or any(n in str(key) for key in stex_assigned_numbers.keys()):
                            matched_user_num = n
                            break
                    
                    if matched_user_num:
                        pot_num = matched_user_num
                    elif len(pot_nums_list) >= 2:
                        pot_num = pot_nums_list[1]
                    else:
                        pot_num = pot_nums_list[0]
                            
                if pot_num and pot_msg:
                    otp = extract_otp_code(pot_msg)
                    if otp:
                        temp_results.append({"number": pot_num, "message": pot_msg, "otp": otp})
                        
            def traverse_json(node):
                if isinstance(node, list):
                    if len(node) > 0 and not isinstance(node[0], (dict, list)):
                        process_item(node)
                    for child in node:
                        if isinstance(child, (dict, list)):
                            traverse_json(child)
                elif isinstance(node, dict):
                    process_item(node)
                    for val in node.values():
                        if isinstance(val, (dict, list)):
                            traverse_json(val)

            traverse_json(data)
            
            seen = set()
            for r in temp_results:
                uid = f"{r['number']}_{r['otp']}"
                if uid not in seen:
                    seen.add(uid)
                    results.append(r)
        except: pass
        
    return results

def _manual_default_cdr_url(p):
    """Return the correct SMS CDR page for known Inteliotech Manual login layouts."""
    login_url = str(p.get("login_url", "") or "").strip()
    if not login_url:
        return ""
    if not login_url.startswith("http"):
        login_url = "http://" + login_url
    low = login_url.casefold()
    # Known Inteliotech layouts are authoritative even when an older/stale msg_link is stored.
    if "smshadi.net" in low:
        return "http://smshadi.net/agent/SMSCDRReports"
    if "168.119.13.175" in low:
        return "http://168.119.13.175/ints/agent/SMSCDRReports"
    if "151.80.19.204" in low:
        return "http://151.80.19.204/ints/agent/SMSCDRReports"
    msg_link = str(p.get("msg_link", "") or "").strip()
    if msg_link:
        return msg_link if msg_link.startswith("http") else "http://" + msg_link
    base = login_url.split("/login", 1)[0].rstrip("/")
    return f"{base}/client/SMSCDRStats"


def _manual_extract_datatables_source(html_text, check_url):
    """Extract the exact DataTables sAjaxSource, including Inteliotech relative URLs."""
    soup = BeautifulSoup(html_text or "", "html.parser")
    patterns = (
        r'"sAjaxSource"\s*:\s*"((?:\\.|[^"\\])+)",',
        r"'sAjaxSource'\s*:\s*'((?:\\.|[^'\\])+)'",
        r'\bsAjaxSource\b\s*:\s*"((?:\\.|[^"\\])+)"',
        r"\bsAjaxSource\b\s*:\s*'((?:\\.|[^'\\])+)'",
        r'\bsAjaxSource\b\s*=\s*"((?:\\.|[^"\\])+)"',
        r"\bsAjaxSource\b\s*=\s*'((?:\\.|[^'\\])+)'",
        r'"ajax"\s*:\s*"((?:\\.|[^"\\])*data_smscdr\.php[^"\\]*)",'
        r"'ajax'\s*:\s*'((?:\\.|[^'\\])*data_smscdr\.php[^'\\]*)'",
    )
    for script in soup.find_all("script"):
        text = script.string or script.get_text() or ""
        for pattern in patterns:
            m = re.search(pattern, text, re.I)
            if m:
                raw = html.unescape(m.group(1))
                raw = raw.replace(r'\/', '/').replace(r'\u0026', '&')
                return urljoin(check_url, raw)
    # Last-resort scan of raw HTML in case the script tag was altered by a proxy/parser.
    raw_html = str(html_text or "")
    for pattern in patterns:
        m = re.search(pattern, raw_html, re.I)
        if m:
            raw = html.unescape(m.group(1)).replace(r'\/', '/').replace(r'\u0026', '&')
            return urljoin(check_url, raw)
    return ""


def _manual_decode_ajax_payload(text):
    """Decode normal JSON, JSON-string wrappers, and common DataTables JSONP wrappers."""
    raw = str(text or "").lstrip("\ufeff \r\n\t")
    if not raw:
        return None
    for candidate in (raw, raw[raw.find("{"):] if "{" in raw else raw, raw[raw.find("["):] if "[" in raw else raw):
        candidate = candidate.strip()
        if candidate.endswith(";"):
            candidate = candidate[:-1].rstrip()
        try:
            obj = json.loads(candidate)
            if isinstance(obj, str):
                try:
                    return json.loads(obj)
                except Exception:
                    return obj
            return obj
        except Exception:
            pass
    m = re.search(r'^\s*[A-Za-z_$][\w$]*\s*\((.*)\)\s*;?\s*$', raw, re.S)
    if m:
        try:
            return json.loads(m.group(1).strip())
        except Exception:
            pass
    return None


def _manual_hadi_force_config(p):
    """Apply HADI/Inteliotech's known 9-column SMS CDR schema without changing Auto panels."""
    q = dict(p or {})
    login_url = str(q.get("login_url", "") or "").casefold()
    name = str(q.get("name", "") or "").casefold()
    if "smshadi.net" in login_url or "hadi" in name:
        q.setdefault("num_col_name", "number")
        q.setdefault("msg_col_name", "sms")
        q["num_col_idx"] = 3
        q["msg_col_idx"] = 6
    return q


def _canonicalize_login_panel(p):
    q = dict(p or {})
    hay = " ".join(str(q.get(k) or "") for k in ("name", "panel_name", "panel_id", "login_url", "msg_link")).casefold()
    if "zyron" in hay or "151.80.19.204" in hay:
        q["login_url"] = "http://151.80.19.204/ints/login"
        q["msg_link"] = "http://151.80.19.204/ints/agent/SMSCDRReports"
    elif "flex" in hay or "168.119.13.175" in hay:
        q["login_url"] = "http://168.119.13.175/ints/login"
        q["msg_link"] = "http://168.119.13.175/ints/agent/SMSCDRReports"
    return q


def attempt_auto_login(p, idx):
    canonical = _canonicalize_login_panel(p)
    if isinstance(p, dict):
        p.update(canonical)
    p = canonical
    login_url = p.get("login_url", "").strip()
    if not login_url.startswith("http"):
        login_url = "http://" + login_url
        
    if not login_url.lower().endswith('/login') and not login_url.lower().endswith('.php'):
        login_url = f"{login_url.rstrip('/')}/login"
        
    session = requests.Session()
    login_retry = Retry(
        total=3,
        connect=3,
        read=2,
        backoff_factor=0.35,
        status_forcelist=(429, 500, 502, 503, 504),
        allowed_methods=frozenset({"GET", "POST"}),
        respect_retry_after_header=True,
    )
    login_adapter = HTTPAdapter(pool_connections=8, pool_maxsize=16, max_retries=login_retry)
    session.mount("http://", login_adapter)
    session.mount("https://", login_adapter)
    user_agents = (
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120.0.0.0 Safari/537.36",
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/123.0.0.0 Safari/537.36",
        "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/122.0.0.0 Safari/537.36",
    )
    session.headers.update({
        'User-Agent': random.choice(user_agents),
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'Connection': 'keep-alive',
    })
    
    try:
        res = session.get(login_url, timeout=15, allow_redirects=True)
        if res.status_code in (401, 403):
            session.headers.update({"Referer": login_url, "Upgrade-Insecure-Requests": "1"})
            res = session.get(login_url, timeout=15, allow_redirects=True)
        soup = BeautifulSoup(res.text, 'html.parser')
        all_text = res.text
        
        captcha_match = re.search(r'(\d+\s*[\+\-\*]\s*\d+)\s*[=\?:]', all_text)
        if not captcha_match:
            captcha_match = re.search(r'what is\s*(\d+\s*[\+\-\*]\s*\d+)', all_text, re.I)
        if not captcha_match:
            elements = soup.find_all(["label", "div", "span", "p", "strong"])
            for el in elements:
                txt = el.get_text(separator=" ", strip=True)
                if any(op in txt for op in ["+", "-", "*"]):
                    m = re.search(r'(\d+\s*[\+\-\*]\s*\d+)', txt)
                    if m:
                        captcha_match = m
                        break
                        
        captcha_text = captcha_match.group(1) if captcha_match else "0 + 0"
        answer = "0"
        m2 = re.search(r'(\d+)\s*([\+\-\*])\s*(\d+)', captcha_text)
        if m2:
            a, op, b = int(m2.group(1)), m2.group(2), int(m2.group(3))
            if op == '+': answer = str(a + b)
            elif op == '-': answer = str(a - b)
            elif op == '*': answer = str(a * b)

        form = soup.find("form")
        if not form:
            p["login_status"] = "❌ No login form found"
            return False
            
        action = form.get("action")
        from urllib.parse import urljoin
        post_url = urljoin(login_url, action) if action else login_url

        form_data = {}
        for hidden in form.find_all("input", type="hidden"):
            name = hidden.get("name")
            if name: form_data[name] = hidden.get("value") or ""
        
        user_input = form.find("input", {"name": re.compile(r"user|email|id", re.I)}) or \
                     form.find("input", {"type": "text", "placeholder": re.compile(r"user|email", re.I)}) or \
                     form.find("input", {"type": "text"})
                     
        pass_input = form.find("input", {"name": re.compile(r"pass", re.I)}) or \
                     form.find("input", {"type": "password"})
                     
        captcha_input = form.find("input", {"name": re.compile(r"^capt$", re.I)}) or \
                        form.find("input", {"placeholder": re.compile(r"answer|ans|code|verification|value|captcha", re.I)}) or \
                        form.find("input", {"name": re.compile(r"ans|captcha|ver|code|capt", re.I)})
        
        user_field = user_input.get("name") if user_input else "username"
        pass_field = pass_input.get("name") if pass_input else "password"
        captcha_field = captcha_input.get("name") if captcha_input else "answer"

        form_data[user_field] = p.get("username", "")
        form_data[pass_field] = p.get("password", "")
        if captcha_field:
            form_data[captcha_field] = answer

        login_req = session.post(post_url, data=form_data, allow_redirects=True, timeout=15)
        
        check_url = _manual_default_cdr_url(p) if _manual_panel_is_enabled_for_fetch(p) else ""
        if not check_url:
            msg_link = p.get("msg_link", "").strip()
            if not msg_link.startswith("http") and msg_link != "":
                msg_link = "http://" + msg_link
            check_url = msg_link if msg_link else f"{login_url.split('/login')[0]}/client/SMSCDRStats"
        
        check_res = session.get(check_url, timeout=10)
        
        success_text = (login_req.text + " " + check_res.text).lower()
        if any(marker in success_text for marker in ('logout', 'sms reports', 'sms cdr', 'sms stats', 'dashboard', 'cdrs')) or bool(BeautifulSoup(check_res.text or "", "html.parser").find("table")):
            panel_sessions[idx] = session
            p["login_status"] = "✅ Active & Fetching"
            try:
                            save_db()
            except Exception:
                pass
            return True
        else:
            p["login_status"] = f"❌ Login Failed (Math: {captcha_text} = {answer})"
            return False
            
    except Exception as e:
        p["login_status"] = f"❌ Error: {str(e)[:20]}"
        
    return False

def _process_auto_captcha_panel_item(p, item):
    """Preserve the existing Auto Captcha panel processing path exactly."""
    num = item["number"]
    otp = item["otp"]
    msg_text = item["message"]
    unique_id = f"{num}_{otp}"
    if unique_id not in processed_otps:
        processed_otps.add(unique_id)
        if len(processed_otps) > 5000:
            processed_otps.clear()
        char, iso = get_flag_and_code(num)
        manual_meta = _manual_number_metadata_lookup(num)
        configured_manual_service = str(manual_meta.get("service", "")).strip() if manual_meta else ""
        service_for_display = configured_manual_service or detect_service(msg_text) or "Service"
        app_full_name, prem_app_html = get_service_info_html(service_for_display, "")
        current_time = time.time()
        recent_traffic[:] = [t for t in recent_traffic if current_time - t.get("time", 0) <= 3600]
        recent_traffic.append({"service": app_full_name, "iso": iso, "flag": char, "number": num, "time": current_time})
        save_local_db()
        display_num = f"+{num}" if not str(num).startswith("+") else str(num)
        lang = detect_language(msg_text)
        lang_name = _lang_name(lang)
        display_msg = build_otp_group_message(display_num, iso, prem_app_html, lang_name)
        forward_otp_to_configured_groups(otp, display_msg, fast=True)
        owners = []
        panel_id = str(p.get("panel_id") or p.get("id") or "").strip()
        if str(p.get("source_type") or "").upper() == "MANUAL" and panel_id:
            try:
                owners = _manual_panel_owner_ids_for_panel(num, panel_id)
            except Exception:
                owners = []
        clean_api_num = str(num).replace("+", "").replace(" ", "").replace("-", "").strip()
        for uid, session_data in user_active_sessions.items():
            for act_num in session_data.get("nums", []):
                act_clean = str(act_num).replace("+", "").replace(" ", "").replace("-", "").strip()
                if act_clean == clean_api_num or (len(act_clean) >= 8 and act_clean.endswith(clean_api_num[-8:])) or (len(clean_api_num) >= 8 and clean_api_num.endswith(act_clean[-8:])):
                    owners.append(uid)
                    break
        if not owners:
            for stex_n, n_owner in stex_assigned_numbers.items():
                clean_stex = str(stex_n).replace("+", "").replace(" ", "").replace("-", "").strip()
                if clean_stex == clean_api_num or (len(clean_stex) >= 8 and clean_stex.endswith(clean_api_num[-8:])) or (len(clean_api_num) >= 8 and clean_api_num.endswith(act_clean[-8:])):
                    owners.append(n_owner)
        owners = list(dict.fromkeys(owners))[:1]
        for owner_id in owners:
            inbox_msg = build_otp_user_message(display_num, iso, prem_app_html, lang_name)
            inbox_kb = build_otp_user_keyboard(otp)["inline_keyboard"]
            reward_service = configured_manual_service or app_full_name
            reward_country = (str(manual_meta.get("country", "")).strip() if manual_meta else "") or iso
            reward = credit_otp_reward(owner_id, "PANEL", reward_service, reward_country, num, event_key=unique_id)
            sent = send_message(owner_id, render_body_text(inbox_msg + f"\n💰 <b>Reward Added:</b> +{reward:g} TK"), reply_markup={"inline_keyboard": inbox_kb})
            if sent is not None and str(p.get("source_type") or "").upper() == "MANUAL" and panel_id:
                try:
                    _manual_finalize_otp_number(num, panel_id=panel_id)
                except Exception:
                    pass

def _manual_panel_owner_ids_for_panel(number, panel_id):
    """O(1)-style owner resolution using the durable normalized-number lease index."""
    norm = _normalize_number_key(number)
    pid = str(panel_id or "").strip()
    if not norm or not pid:
        return []
    now = time.time()
    owners = []
    with manual_number_leases_lock:
        keys = list(manual_number_lease_index.get(norm, set()))
        if not keys:
            # Fallback for international-prefix differences between CDR and stock.
            keys = [k for k, lease in manual_number_leases.items()
                    if isinstance(lease, dict) and _manual_numbers_match(number, lease.get("number"))]
        if not keys:
            return []
        expired = []
        for key in keys:
            lease = manual_number_leases.get(key)
            if not isinstance(lease, dict):
                expired.append((key, norm))
                continue
            if str(lease.get("panel_id") or "").strip() != pid or not _manual_numbers_match(number, lease.get("number")):
                continue
            try:
                expires_at = float(lease.get("expires_at", 0.0) or 0.0)
            except Exception:
                expires_at = 0.0
            if now >= expires_at:
                expired.append((key, norm))
                continue
            try:
                owner = int(lease.get("owner_id") or 0)
            except Exception:
                owner = 0
            if owner:
                owners.append(owner)
        for key, key_norm in expired:
            manual_number_leases.pop(key, None)
            _manual_lease_index_remove(key, key_norm)
    return list(dict.fromkeys(owners))


def _record_manual_forward_candidate(panel_id, service, country, number, number_range="", now=None):
    """Keep only each Manual panel's most recently OTP-active number for 20 min."""
    now = float(time.time() if now is None else now)
    pid = str(panel_id or "").strip()
    number = str(number or "").strip()
    if not pid or not number:
        return False
    with manual_forward_candidates_lock:
        for key, row in list(manual_forward_candidates.items()):
            try:
                if now - float((row or {}).get("received_at", 0) or 0) > MANUAL_FORWARD_TTL:
                    manual_forward_candidates.pop(key, None)
            except Exception:
                manual_forward_candidates.pop(key, None)
        manual_forward_candidates[pid] = {
            "panel_id": pid,
            "service": str(service or "Service").strip() or "Service",
            "country": str(country or "XX").strip() or "XX",
            "number": number,
            "range": str(number_range or "").strip(),
            "received_at": now,
        }
    return True


def _manual_forward_rows(now=None):
    """Return unexpired latest-number rows, pruning stale local state."""
    now = float(time.time() if now is None else now)
    rows = []
    with manual_forward_candidates_lock:
        for key, row in list(manual_forward_candidates.items()):
            if not isinstance(row, dict):
                manual_forward_candidates.pop(key, None)
                continue
            try:
                age = now - float(row.get("received_at", 0) or 0)
            except Exception:
                age = MANUAL_FORWARD_TTL + 1
            if age > MANUAL_FORWARD_TTL:
                manual_forward_candidates.pop(key, None)
                continue
            if str(row.get("number") or "").strip():
                rows.append(dict(row))
    return rows


def _manual_record_inbox_traffic(panel_id, service, country, number, owner_id, number_range="", now=None):
    """Record one successful Manual-panel inbox delivery for traffic ranking.

    The metric is deliberately scoped to the originating manual panel and the
    service/country configured for the leased number. It never contributes to
    provider Active-Ranges ranking. The rolling window is one hour.
    """
    global manual_panel_traffic_window_started_at, manual_panel_traffic_stats
    now = float(time.time() if now is None else now)
    pid = str(panel_id or "").strip()
    svc = str(service or "").strip() or "Service"
    cnt = str(country or "").strip() or "Unknown"
    rng = str(number_range or "").strip()
    try:
        uid = int(owner_id)
    except Exception:
        uid = 0
    if not pid or not uid:
        return False
    with manual_panel_traffic_lock:
        if now - float(manual_panel_traffic_window_started_at or 0.0) >= 3600.0:
            manual_panel_traffic_stats.clear()
            manual_panel_traffic_window_started_at = now
        panel = manual_panel_traffic_stats.setdefault(pid, {"panel_name": pid, "hits": 0, "services": {}, "last_seen": 0.0})
        panel["hits"] = int(panel.get("hits", 0) or 0) + 1
        panel["last_seen"] = max(float(panel.get("last_seen", 0.0) or 0.0), now)
        service_node = panel.setdefault("services", {}).setdefault(svc, {"hits": 0, "countries": {}, "last_seen": 0.0})
        service_node["hits"] = int(service_node.get("hits", 0) or 0) + 1
        service_node["last_seen"] = max(float(service_node.get("last_seen", 0.0) or 0.0), now)
        country_node = service_node.setdefault("countries", {}).setdefault(cnt, {"hits": 0, "users": {}, "ranges": {}, "last_seen": 0.0})
        country_node["hits"] = int(country_node.get("hits", 0) or 0) + 1
        country_node["users"][str(uid)] = int(country_node.get("users", {}).get(str(uid), 0) or 0) + 1
        if rng:
            country_node["ranges"][rng] = int(country_node.get("ranges", {}).get(rng, 0) or 0) + 1
        country_node["last_seen"] = max(float(country_node.get("last_seen", 0.0) or 0.0), now)
    save_local_db()
    return True


def _manual_deliver_inbox_and_record(owner_id, inbox_text, reply_markup, panel_id, service, country, number, number_range=""):
    """Deliver one Manual-panel OTP with bounded fast retries.

    A number is considered completed only after Telegram acknowledges a successful
    send. This makes the lease itself the authoritative routing gate.
    """
    last_result = {"ok": False, "error": "manual_delivery_unknown"}
    for attempt in range(3):
        result = send_message_fast(owner_id, inbox_text, reply_markup)
        last_result = result if isinstance(result, dict) else {"ok": False, "result": result}
        if last_result.get("ok"):
            _manual_record_inbox_traffic(
                panel_id, service, country, number, owner_id, number_range=number_range
            )
            return last_result
        if attempt < 2:
            time.sleep(0.05 * (2 ** attempt))
    return last_result


def _manual_panel_traffic_rows():
    """Flatten rolling Manual-panel traffic into deterministic ranking rows."""
    now = time.time()
    with manual_panel_traffic_lock:
        if now - float(manual_panel_traffic_window_started_at or 0.0) >= 3600.0:
            return []
        rows = []
        for pid, panel in (manual_panel_traffic_stats or {}).items():
            if not isinstance(panel, dict):
                continue
            pname = str(panel.get("panel_name") or pid).strip() or pid
            panel_hits = int(panel.get("hits", 0) or 0)
            services = panel.get("services", {}) or {}
            service_rows = []
            for svc, svc_node in services.items():
                if not isinstance(svc_node, dict):
                    continue
                svc_hits = int(svc_node.get("hits", 0) or 0)
                countries = []
                for country, cnode in (svc_node.get("countries", {}) or {}).items():
                    if not isinstance(cnode, dict):
                        continue
                    hits = int(cnode.get("hits", 0) or 0)
                    users = cnode.get("users", {}) or {}
                    ranges = cnode.get("ranges", {}) or {}
                    top_range = ""
                    if ranges:
                        top_range = sorted(ranges.items(), key=lambda kv: (-int(kv[1]), _normalize_label(kv[0])))[0][0]
                    countries.append({
                        "country": str(country),
                        "hits": hits,
                        "users": len(users),
                        "top_range": top_range,
                        "last_seen": float(cnode.get("last_seen", 0.0) or 0.0),
                    })
                countries.sort(key=lambda x: (-x["hits"], -x["last_seen"], _normalize_label(x["country"])))
                service_rows.append({"service": str(svc), "hits": svc_hits, "countries": countries[:5], "last_seen": float(svc_node.get("last_seen", 0.0) or 0.0)})
            service_rows.sort(key=lambda x: (-x["hits"], -x["last_seen"], _normalize_label(x["service"])))
            rows.append({"panel_id": str(pid), "panel_name": pname, "hits": panel_hits, "services": service_rows[:8], "last_seen": float(panel.get("last_seen", 0.0) or 0.0)})
        rows.sort(key=lambda x: (-x["hits"], -x["last_seen"], _normalize_label(x["panel_name"])))
        return rows


def build_manual_panel_traffic_ui():
    rows = _manual_panel_traffic_rows()
    with manual_panel_traffic_lock:
        started = float(manual_panel_traffic_window_started_at or time.time())
    elapsed = max(0, int(time.time() - started))
    remaining = max(0, 3600 - elapsed)
    lines = [
        "📊 <b>MANUAL PANEL TRAFFIC</b>",
        "━━━━━━━━━━━━━━━━━━━━",
        f"Window: <b>60 minutes</b> • Reset in <b>{remaining // 60}m</b>",
        "",
    ]
    if not rows:
        lines.append("<i>No Manual-panel inbox traffic received yet.</i>")
    else:
        for rank, panel in enumerate(rows, 1):
            lines.append(f"<b>#{rank} {html.escape(panel['panel_name'])}</b> • <b>{panel['hits']}</b> inbox hits")
            for s_rank, svc in enumerate(panel["services"], 1):
                lines.append(f"  {s_rank}. <b>{html.escape(svc['service'])}</b> • {svc['hits']} hits")
                for c in svc["countries"][:5]:
                    range_part = f" • Top range: <code>{html.escape(c['top_range'])}</code>" if c['top_range'] else ""
                    lines.append(f"     ↳ {html.escape(c['country'])}: <b>{c['hits']}</b> hits • {c['users']} users{range_part}")
            lines.append("")
    kb = {"inline_keyboard": [
        [{"text": "Refresh Manual Traffic", "icon_custom_emoji_id": "5465368548702446780", "callback_data": "manual_panel_traffic", "style": "success"}],
        [{"text": "Back", "icon_custom_emoji_id": "5267490665117275176", "callback_data": "admin_traffic_menu", "style": "danger"}],
    ]}
    return _admin_category_text("MANUAL PANEL TRAFFIC", "\n".join(lines)), kb


def _process_manual_panel_item_fast(p, item):
    """Process one Manual-panel OTP with strict panel->number->user routing."""
    global processed_otps, recent_traffic
    num = str(item.get("number", ""))
    otp = str(item.get("otp", ""))
    msg_text = str(item.get("message", ""))
    if not num or not otp:
        return

    panel_id = str(p.get("panel_id") or p.get("id") or "").strip()
    norm_num = _normalize_number_key(num)
    if not panel_id or not norm_num:
        return
    unique_id = f"MANUAL:{panel_id}:{norm_num}:{otp}"

    with MANUAL_PANEL_OTP_LOCK:
        now_seen = time.time()
        for key, ts in list(manual_panel_seen_events.items()):
            try:
                if now_seen - float(ts or 0.0) > MANUAL_PANEL_SEEN_TTL:
                    manual_panel_seen_events.pop(key, None)
            except Exception:
                manual_panel_seen_events.pop(key, None)
        if unique_id in processed_otps or unique_id in manual_panel_inflight_otps:
            return
        seen_at = float(manual_panel_seen_events.get(unique_id, 0.0) or 0.0)
        if seen_at and now_seen - seen_at <= MANUAL_PANEL_SEEN_TTL:
            return
        manual_panel_inflight_otps.add(unique_id)
        manual_panel_seen_events[unique_id] = now_seen

    delivered_ok = False
    try:
        # Final authority: only an unexpired lease belonging to this exact panel
        # can receive the incoming SMS. No global/user fallback is used here.
        owners = _manual_panel_owner_ids_for_panel(num, panel_id)
        if not owners:
            with MANUAL_PANEL_OTP_LOCK:
                manual_panel_seen_events.pop(unique_id, None)
            return

        manual_meta = _manual_number_metadata_lookup(num) or {}
        meta_panel_id = str(manual_meta.get("panel_id") or "").strip()
        if meta_panel_id and meta_panel_id != panel_id:
            with MANUAL_PANEL_OTP_LOCK:
                manual_panel_seen_events.pop(unique_id, None)
            return

        char, iso = get_flag_and_code(num)
        configured_service = str(manual_meta.get("service") or "").strip()
        panel_service = str(p.get("service") or "").strip()
        service_for_display = configured_service or panel_service or detect_service(msg_text) or "Service"
        app_full_name, prem_app_html = get_service_info_html(service_for_display, msg_text)

        current_time = time.time()
        recent_traffic[:] = [t for t in recent_traffic if current_time - t.get("time", 0) <= 3600]
        recent_traffic.append({"service": app_full_name, "iso": iso, "flag": char, "number": num, "time": current_time})

        display_num = f"+{num}" if not str(num).startswith("+") else str(num)
        lang_name = _lang_name(detect_language(msg_text))
        # Manual and Auto inbox receipts share the exact same masked group format.
        group_msg = build_otp_group_message(display_num, iso, prem_app_html, lang_name)
        forward_otp_to_configured_groups(otp, group_msg, fast=True)
        inbox_msg = build_otp_user_message(display_num, iso, prem_app_html, lang_name)
        inbox_kb = build_otp_user_keyboard(otp)["inline_keyboard"]
        reward_service = configured_service or app_full_name
        reward_country = str(manual_meta.get("country") or iso).strip() or iso
        number_range = str(
            item.get("range") or item.get("prefix") or item.get("number_range") or item.get("numberRange") or ""
        ).strip()
        _record_manual_forward_candidate(
            panel_id, reward_service, reward_country, num, number_range, now=current_time
        )

        # Exactly one active lease is expected for one manual number. Keeping only
        # the first unique owner preserves the existing single-owner contract.
        owner_id = list(dict.fromkeys(owners))[0]
        reward = credit_otp_reward(
            owner_id, "PANEL", reward_service, reward_country, num, event_key=unique_id
        )
        result = _manual_deliver_inbox_and_record(
            owner_id,
            render_body_text(inbox_msg + f"\n💰 <b>Reward Added:</b> +{reward:g} TK"),
            {"inline_keyboard": inbox_kb},
            panel_id, reward_service, reward_country, num, number_range
        )

        if not (isinstance(result, dict) and result.get("ok")):
            # Failed delivery must remain retryable while the user's 20-minute lease
            # is still active. Do not mark the number Used and do not mark the event done.
            with MANUAL_PANEL_OTP_LOCK:
                manual_panel_seen_events.pop(unique_id, None)
            return

        delivered_ok = True
        _manual_finalize_otp_number(num, panel_id=panel_id, owner_ids=[owner_id])
        try:
            save_local_db()
        except Exception:
            pass
    except Exception as exc:
        with MANUAL_PANEL_OTP_LOCK:
            manual_panel_seen_events.pop(unique_id, None)
        _terminal_log(f"[MANUAL-PANEL] async processing failed number={num} otp={otp}: {exc}")
    finally:
        with MANUAL_PANEL_OTP_LOCK:
            manual_panel_inflight_otps.discard(unique_id)
            if delivered_ok:
                processed_otps.add(unique_id)
                if len(processed_otps) > 5000:
                    processed_otps = set(list(processed_otps)[-4000:])

def _manual_panel_request_url(panel):
    full_url = str(panel.get("full_api_url") or "").strip()
    url = str(panel.get("api_url") or "").strip()
    token = str(panel.get("token") or panel.get("api_key") or "").strip()
    if full_url:
        return full_url
    if not url:
        return ""
    if "{token}" in url or "{key}" in url:
        return url.replace("{token}", token).replace("{key}", token)
    if "token=" in url or "key=" in url:
        return url
    sep = "&" if "?" in url else "?"
    return f"{url}{sep}token={token}"


def _manual_panel_active_number_set(panel_id, now=None):
    """Return only currently leased numbers for one panel; avoids scanning all users."""
    pid = str(panel_id or "").strip()
    if not pid:
        return set()
    now = float(time.time() if now is None else now)
    active = set()
    expired = []
    with manual_number_leases_lock:
        for norm, keys in list(manual_number_lease_index.items()):
            for key in list(keys):
                lease = manual_number_leases.get(key)
                if not isinstance(lease, dict):
                    expired.append((key, norm))
                    continue
                if str(lease.get("panel_id") or "").strip() != pid:
                    continue
                try:
                    expires_at = float(lease.get("expires_at", 0.0) or 0.0)
                except Exception:
                    expires_at = 0.0
                if now >= expires_at:
                    expired.append((key, norm))
                    continue
                active.add(norm)
        for key, norm in expired:
            manual_number_leases.pop(key, None)
            _manual_lease_index_remove(key, norm)
    return active


def _manual_filter_records_to_active_numbers(records, panel_id):
    """Keep only records whose normalized Number currently belongs to this panel."""
    active_numbers = _manual_panel_active_number_set(panel_id)
    if not active_numbers:
        return []
    out = []
    for record in records or []:
        if not isinstance(record, dict):
            continue
        norm = _normalize_number_key(record.get("number"))
        if norm and any(_manual_numbers_match(norm, active) for active in active_numbers):
            out.append(record)
    return out


def _manual_set_login_status(panel_id, status, idx=None, save=True):
    """Persist a Manual login-panel status on the canonical bot_settings record.

    Manual panel registry entries are snapshots; background workers must never
    rely on mutating those snapshots to update the local source-of-truth.
    """
    pid = str(panel_id or "").strip()
    target = None
    target_idx = idx
    panels = bot_settings.get("panels", []) or []
    if target_idx is not None:
        try:
            target_idx = int(target_idx)
        except (TypeError, ValueError):
            target_idx = None
    if target_idx is not None and 0 <= target_idx < len(panels) and isinstance(panels[target_idx], dict):
        candidate = panels[target_idx]
        candidate_pid = str(candidate.get("panel_id") or candidate.get("id") or "").strip()
        if not pid or candidate_pid == pid:
            target = candidate
        else:
            target_idx = None
    if target is None and pid:
        for i, candidate in enumerate(panels):
            if not isinstance(candidate, dict):
                continue
            candidate_pid = str(candidate.get("panel_id") or candidate.get("id") or "").strip()
            if candidate_pid == pid:
                target = candidate
                target_idx = i
                break
    if target is None:
        return False
    new_status = str(status or "").strip()
    if not new_status:
        return False
    target["login_status"] = new_status
    target["login_status_updated_at"] = time.time()
    try:
        if save:
            save_db()
    except Exception:
        pass
    return True


def _manual_is_login_panel(p):
    """True for any configured login/session panel, including legacy Auto panels."""
    if not isinstance(p, dict):
        return False
    return bool(str(p.get("login_url") or "").strip())


def _manual_start_live_login_check(idx):
    """Start one background direct-panel login/CDR health check for a Manual login panel."""
    try:
        idx = int(idx)
    except (TypeError, ValueError):
        return False
    panels = bot_settings.get("panels", []) or []
    if idx < 0 or idx >= len(panels) or not isinstance(panels[idx], dict):
        return False
    panel = panels[idx]
    if not _manual_is_login_panel(panel):
        return False
    username = str(panel.get("username") or "").strip()
    password = str(panel.get("password") or "").strip()
    if not username or not password:
        _manual_set_login_status(panel.get("panel_id") or panel.get("id") or idx, "⚪ Credentials Not Set", idx=idx)
        return False

    pid = str(panel.get("panel_id") or panel.get("id") or idx).strip()
    with _MANUAL_LIVE_CHECK_LOCK:
        if idx in _MANUAL_LIVE_CHECK_INFLIGHT:
            return False
        _MANUAL_LIVE_CHECK_INFLIGHT.add(idx)
    try:
        _manual_set_login_status(pid, "🔄 Checking Login & SMS Data...", idx=idx)
        ok = attempt_auto_login(panel, idx)
        if not ok:
            # attempt_auto_login already writes a concrete failure to the canonical panel.
            return True
        sess = panel_sessions.get(idx)
        if sess is None:
            _manual_set_login_status(pid, "❌ Session Not Available", idx=idx)
            return True
        check_url = _manual_default_cdr_url(panel) or str(panel.get("msg_link") or "").strip()
        if not check_url:
            login_url = str(panel.get("login_url") or "").strip()
            check_url = f"{login_url.rstrip('/')}/agent/SMSCDRReports" if login_url else ""
        if check_url:
            try:
                fetch_cpt_panel_cdrs(panel, sess, check_url)
            except Exception:
                # Login succeeded; a temporary/empty CDR response must not downgrade the
                # panel health state. The fetch loop will retry when needed.
                pass
        _manual_set_login_status(pid, "✅ Active & Fetching", idx=idx)
        try:
            panel["last_successful_check"] = time.time()
            panel["last_data_check"] = time.time()
            save_db()
        except Exception:
            pass
        return True
    except Exception as exc:
        _manual_set_login_status(pid, f"❌ Check Error: {str(exc)[:40]}", idx=idx)
        return False
    finally:
        with _MANUAL_LIVE_CHECK_LOCK:
            _MANUAL_LIVE_CHECK_INFLIGHT.discard(idx)


def _manual_panel_fetch_once(panel):
    """Single demand-driven Manual-panel fetch for both API and login-based panels."""
    panel_id = str(panel.get("panel_id") or panel.get("id") or panel.get("name") or "").strip()
    if not panel_id:
        return
    with _manual_panel_fetch_lock:
        if panel_id in _manual_panel_fetch_inflight:
            return
        _manual_panel_fetch_inflight.add(panel_id)
    try:
        if str(panel.get("status", "ON")).upper() != "ON":
            return
        # Demand-driven: no leased number means this panel must not poll at all.
        if not _manual_panel_active_number_set(panel_id):
            return

        try:
            limit = max(1, int(panel.get("records", 0) or 0))
        except Exception:
            limit = 0

        # Login-based Manual panels (HADI/FLEX/ZYRON style) use the existing
        # authenticated session + dedicated Manual CDR parser. They must not be
        # treated as ordinary API panels merely because their historical config
        # contains type="Auto Captcha Panel".
        is_login_panel = bool(str(panel.get("login_url") or "").strip())
        if is_login_panel:
            idx = None
            stored_panel = None
            for i, stored in enumerate(bot_settings.get("panels", []) or []):
                if not isinstance(stored, dict):
                    continue
                if str(stored.get("panel_id") or stored.get("id") or "").strip() == panel_id:
                    idx = i
                    stored_panel = stored
                    break
            if idx is None or stored_panel is None:
                return
            # Canonical local record is always the source of login/session state.
            panel = stored_panel
            active_targets = _manual_panel_active_number_set(panel_id)
            if not active_targets:
                return
            sess = panel_sessions.get(idx)
            if sess is None:
                now = time.time()
                try:
                    last_attempt = float(panel.get("last_login_attempt", 0.0) or 0.0)
                except Exception:
                    last_attempt = 0.0
                if now - last_attempt < 5.0:
                    return
                stored = bot_settings["panels"][idx]
                stored["last_login_attempt"] = now
                panel["last_login_attempt"] = now
                if not attempt_auto_login(stored, idx):
                    return
                sess = panel_sessions.get(idx)
            if sess is None:
                return
            check_url = _manual_default_cdr_url(panel)
            if not check_url:
                login_url = str(panel.get("login_url") or "").strip()
                check_url = f"{login_url.rstrip('/')}/agent/SMSCDRReports" if login_url else ""
            parsed, _ = _fetch_manual_panel_cdrs(
                panel, sess, check_url, target_numbers=active_targets
            )
            parsed = _manual_filter_records_to_active_numbers(parsed, panel_id)
            _manual_set_login_status(panel_id, "✅ Active & Fetching", idx=idx)
        else:
            url = _manual_panel_request_url(panel)
            if not url:
                return
            sess = _manual_panel_http_sessions_by_id.get(panel_id)
            if sess is None:
                sess = requests.Session()
                adapter = HTTPAdapter(pool_connections=2, pool_maxsize=2, max_retries=0)
                sess.mount("http://", adapter)
                sess.mount("https://", adapter)
                sess.headers.update({"Connection": "keep-alive", "User-Agent": "FRD-ManualPanel/3.0"})
                _manual_panel_http_sessions_by_id[panel_id] = sess
            params = {}
            if limit > 0 and "limit=" not in url.lower():
                params["limit"] = limit
            try:
                res = sess.get(url, params=params or None, timeout=MANUAL_PANEL_HTTP_TIMEOUT)
                parsed = parse_panel_response(res.text, panel)
            except requests.RequestException:
                parsed = []
            except Exception:
                parsed = []

        if not parsed:
            return
        parsed = _manual_filter_records_to_active_numbers(parsed, panel_id)
        if not parsed:
            return
        if limit > 0:
            parsed = parsed[:limit]
        for item in parsed:
            try:
                _manual_panel_processing_pool.submit(_process_manual_panel_item_fast, panel.copy(), item.copy())
            except Exception:
                pass
    except Exception as exc:
        _terminal_log(f"[MANUAL-PANELS] fetch failed panel={panel_id}: {exc}")
    finally:
        with _manual_panel_fetch_lock:
            _manual_panel_fetch_inflight.discard(panel_id)


def manual_panels_listener():
    """Parallel low-latency listener for Manual API panels only."""
    while True:
        try:
            now = time.monotonic()
            due_panels = []
            for panel in _manual_panel_registry():
                pid = str(panel.get("panel_id") or "").strip()
                if not pid or pid == MANUAL_ELITESMS_PANEL_ID:
                    continue
                # All source_type=MANUAL panels belong here, including legacy
                # login-based panels stored as type="Auto Captcha Panel" (HADI/FLEX/ZYRON).
                if str(panel.get("source_type") or "MANUAL").upper() != "MANUAL":
                    continue
                if not _manual_panel_active_number_set(pid):
                    _manual_panel_next_due.pop(pid, None)
                    continue
                try:
                    interval = max(0.50, float(panel.get("poll_interval", MANUAL_PANEL_POLL_INTERVAL) or MANUAL_PANEL_POLL_INTERVAL))
                except Exception:
                    interval = MANUAL_PANEL_POLL_INTERVAL
                due = _manual_panel_next_due.get(pid, 0.0)
                if now >= due:
                    _manual_panel_next_due[pid] = now + interval
                    due_panels.append(panel)
            for panel in due_panels:
                try:
                    _manual_panel_fetch_pool.submit(_manual_panel_fetch_once, dict(panel))
                except Exception:
                    pass
            LOCAL_STOP.wait(0.10 if due_panels else min(0.25, MANUAL_PANEL_POLL_INTERVAL))
        except Exception as exc:
            _terminal_log(f"[MANUAL-PANELS] listener error: {exc}")
            LOCAL_STOP.wait(0.25)


def _auto_panel_runtime_key(panel, idx):
    pid = str((panel or {}).get("panel_id") or (panel or {}).get("id") or (panel or {}).get("name") or idx).strip()
    return f"{idx}:{pid}"


def _auto_panel_state(panel, idx):
    key = _auto_panel_runtime_key(panel, idx)
    with _auto_panel_runtime_lock:
        state = _auto_panel_runtime.get(key)
        if state is None:
            state = {
                "panel_id": key,
                "consecutive_failures": 0,
                "last_success": 0.0,
                "last_error": "",
                "last_error_at": 0.0,
                "last_fetch": 0.0,
                "last_records": 0,
                "last_login_attempt": 0.0,
                "next_retry_at": 0.0,
                "generation": 0,
            }
            _auto_panel_runtime[key] = state
        return state


def _auto_panel_note_success(panel, idx, records=0):
    key = _auto_panel_runtime_key(panel, idx)
    now = time.monotonic()
    with _auto_panel_runtime_lock:
        state = _auto_panel_runtime.setdefault(key, {
            "panel_id": key, "consecutive_failures": 0, "last_success": 0.0,
            "last_error": "", "last_error_at": 0.0, "last_fetch": 0.0,
            "last_records": 0, "last_login_attempt": 0.0, "next_retry_at": 0.0, "generation": 0,
        })
        state["consecutive_failures"] = 0
        state["last_success"] = now
        state["last_fetch"] = now
        state["last_records"] = int(records or 0)
        state["last_error"] = ""
        state["next_retry_at"] = 0.0
        state["generation"] = int(state.get("generation", 0) or 0) + 1


def _auto_panel_note_failure(panel, idx, exc):
    key = _auto_panel_runtime_key(panel, idx)
    now = time.monotonic()
    message = str(exc or "fetch failed").strip()[:120] or "fetch failed"
    with _auto_panel_runtime_lock:
        state = _auto_panel_runtime.setdefault(key, {
            "panel_id": key, "consecutive_failures": 0, "last_success": 0.0,
            "last_error": "", "last_error_at": 0.0, "last_fetch": 0.0,
            "last_records": 0, "last_login_attempt": 0.0, "next_retry_at": 0.0, "generation": 0,
        })
        failures = int(state.get("consecutive_failures", 0) or 0) + 1
        state["consecutive_failures"] = failures
        state["last_error"] = message
        state["last_error_at"] = now
        state["last_fetch"] = now
        exponent = max(0, failures - AUTO_PANEL_MAX_FAILURES_BEFORE_BACKOFF)
        backoff = min(AUTO_PANEL_BACKOFF_MAX, AUTO_PANEL_BACKOFF_BASE * (2 ** exponent))
        state["next_retry_at"] = now + backoff
        return backoff


def _auto_panel_get_session(panel, idx):
    """Create/reuse a dedicated HTTP session for one Auto Captcha panel."""
    key = _auto_panel_runtime_key(panel, idx)
    session = _auto_panel_http_sessions_by_id.get(key)
    if session is not None:
        return session
    session = requests.Session()
    retry = Retry(
        total=2,
        connect=2,
        read=1,
        backoff_factor=0.25,
        status_forcelist=(429, 500, 502, 503, 504),
        allowed_methods=frozenset({"GET"}),
        respect_retry_after_header=True,
    )
    adapter = HTTPAdapter(pool_connections=4, pool_maxsize=4, max_retries=retry)
    session.mount("http://", adapter)
    session.mount("https://", adapter)
    session.headers.update({
        "Connection": "keep-alive",
        "Accept": "text/html,application/xhtml+xml,application/json;q=0.9,*/*;q=0.8",
        "User-Agent": "FRD-AutoPanel/4.0",
    })
    _auto_panel_http_sessions_by_id[key] = session
    return session


def _auto_panel_fetch_once(panel, idx):
    """Fetch one Auto Captcha panel with isolated scheduling and failure recovery."""
    if not isinstance(panel, dict):
        return
    panel_id = str(panel.get("panel_id") or panel.get("id") or panel.get("name") or idx).strip()
    inflight_key = _auto_panel_runtime_key(panel, idx)
    with _auto_panel_fetch_lock:
        if inflight_key in _auto_panel_fetch_inflight:
            return
        _auto_panel_fetch_inflight.add(inflight_key)
    try:
        if str(panel.get("status", "ON")).upper() != "ON":
            return
        state = _auto_panel_state(panel, idx)
        if AUTO_PANEL_ENGINE_V2 and time.monotonic() < float(state.get("next_retry_at", 0.0) or 0.0):
            return

        # ``panel_sessions`` is historically indexed by list position because the
        # manual-panel engine also uses that convention. Auto panels can be edited
        # or deleted from Admin, so bind the index to a stable runtime identity and
        # discard a stale session when the panel occupying that index changes.
        with _auto_panel_runtime_lock:
            previous_binding = _auto_panel_binding_by_idx.get(int(idx))
            if previous_binding and previous_binding != inflight_key:
                stale_session = panel_sessions.pop(idx, None)
                if stale_session is not None:
                    try:
                        stale_session.close()
                    except Exception:
                        pass
            _auto_panel_binding_by_idx[int(idx)] = inflight_key

        sess = panel_sessions.get(idx)
        if not sess:
            now_wall = time.time()
            state = _auto_panel_state(panel, idx)
            try:
                last_attempt = float(state.get("last_login_attempt", 0.0) or 0.0)
            except Exception:
                last_attempt = 0.0
            # Persist the login-attempt cooldown in runtime state rather than in a
            # per-submit panel copy. This prevents a failing provider from being
            # hammered every scheduler tick.
            if now_wall - last_attempt < 5.0:
                return
            state["last_login_attempt"] = now_wall
            panel["last_login_attempt"] = now_wall
            if not attempt_auto_login(panel, idx):
                _auto_panel_note_failure(panel, idx, "login failed")
                return
            sess = panel_sessions.get(idx)
            if sess:
                _auto_panel_note_success(panel, idx, 0)
        if not sess:
            _auto_panel_note_failure(panel, idx, "session unavailable")
            return

        login_url = str(panel.get("login_url", "") or "").strip()
        if not login_url.startswith("http"):
            login_url = "http://" + login_url
        msg_link = str(panel.get("msg_link", "") or "").strip()
        if not msg_link.startswith("http") and msg_link:
            msg_link = "http://" + msg_link
        check_url = msg_link if msg_link else f"{login_url.split('/login')[0]}/client/SMSCDRStats"

        parsed_data, _ = fetch_cpt_panel_cdrs(panel, sess, check_url)
        discovered_ajax = str(panel.get("cdr_ajax_url", "") or "").strip()
        if discovered_ajax:
            try:
                stored_panels = bot_settings.get("panels", []) or []
                if 0 <= int(idx) < len(stored_panels) and isinstance(stored_panels[idx], dict):
                    if stored_panels[idx].get("cdr_ajax_url") != discovered_ajax:
                        stored_panels[idx]["cdr_ajax_url"] = discovered_ajax
            except Exception:
                pass
        if not parsed_data:
            _auto_panel_note_success(panel, idx, 0)
            panel["login_status"] = "✅ Active & Fetching"
            return

        try:
            limit = int(panel.get("records", 0) or 0)
        except Exception:
            limit = 0
        if limit > 0:
            parsed_data = parsed_data[:limit]
        parsed_data = parsed_data[:AUTO_PANEL_MAX_INFLIGHT_RECORDS]

        panel["login_status"] = "✅ Active & Fetching"
        _auto_panel_note_success(panel, idx, len(parsed_data))
        for item in parsed_data:
            if not isinstance(item, dict):
                continue
            try:
                _auto_panel_processing_pool.submit(
                    _process_auto_captcha_panel_item, panel.copy(), item.copy()
                )
            except Exception:
                # Do not make a worker submission failure invalidate the panel session.
                continue
    except Exception as exc:
        panel["login_status"] = "❌ Session Expired (Retrying...)"
        stale_session = panel_sessions.pop(idx, None)
        if stale_session is not None:
            try:
                stale_session.close()
            except Exception:
                pass
        stale_http = _auto_panel_http_sessions_by_id.pop(inflight_key, None)
        if stale_http is not None:
            try:
                stale_http.close()
            except Exception:
                pass
        with _auto_panel_runtime_lock:
            _auto_panel_binding_by_idx.pop(int(idx), None)
        _auto_panel_note_failure(panel, idx, exc)
        _terminal_log(f"[AUTO-PANELS] fetch failed panel={panel_id}: {exc}")
    finally:
        with _auto_panel_fetch_lock:
            _auto_panel_fetch_inflight.discard(inflight_key)


def auto_captcha_panels_listener():
    """Parallel low-latency listener for configured Auto Captcha panels."""
    while True:
        try:
            now = time.monotonic()
            due = []
            active_keys = set()
            for idx, panel in enumerate(bot_settings.get("panels", []) or []):
                if not isinstance(panel, dict) or panel.get("status") != "ON":
                    continue
                if str(panel.get("type") or "").strip() != "Auto Captcha Panel":
                    continue
                # Manual login panels remain owned by the demand-driven Manual listener.
                if str(panel.get("source_type") or "").strip().upper() == "MANUAL":
                    continue
                key = _auto_panel_runtime_key(panel, idx)
                active_keys.add(key)
                state = _auto_panel_state(panel, idx)
                try:
                    interval = max(0.50, float(
                        panel.get("poll_interval", AUTO_PANEL_POLL_INTERVAL)
                        or AUTO_PANEL_POLL_INTERVAL
                    ))
                except Exception:
                    interval = AUTO_PANEL_POLL_INTERVAL

                next_due = _auto_panel_next_due.get(key, 0.0)
                retry_at = float(state.get("next_retry_at", 0.0) or 0.0)
                if retry_at > now:
                    next_due = max(next_due, retry_at)

                if now >= next_due:
                    _auto_panel_next_due[key] = now + interval
                    due.append((idx, dict(panel)))

            # Prune scheduler/runtime entries for removed panels.
            for key in list(_auto_panel_next_due):
                if key not in active_keys:
                    _auto_panel_next_due.pop(key, None)
            with _auto_panel_runtime_lock:
                for key in list(_auto_panel_runtime):
                    if key not in active_keys:
                        _auto_panel_runtime.pop(key, None)
                for idx, key in list(_auto_panel_binding_by_idx.items()):
                    if key not in active_keys:
                        _auto_panel_binding_by_idx.pop(idx, None)
                        stale_session = panel_sessions.pop(idx, None)
                        if stale_session is not None:
                            try:
                                stale_session.close()
                            except Exception:
                                pass

            for key in list(_auto_panel_http_sessions_by_id):
                if key not in active_keys:
                    stale_http = _auto_panel_http_sessions_by_id.pop(key, None)
                    if stale_http is not None:
                        try:
                            stale_http.close()
                        except Exception:
                            pass

            for idx, panel in due:
                try:
                    _auto_panel_fetch_pool.submit(_auto_panel_fetch_once, panel, idx)
                except Exception:
                    pass
            LOCAL_STOP.wait(0.05 if due else min(0.50, AUTO_PANEL_POLL_INTERVAL))
        except Exception as exc:
            _terminal_log(f"[AUTO-PANELS] listener error: {exc}")
            LOCAL_STOP.wait(0.05)

def panel_monitor_thread():
    global processed_otps, recent_traffic, panel_sessions
    while True:
        try:
            for idx, p in enumerate(bot_settings.get("panels", [])):
                if p.get("status") == "ON":
                    # Auto Captcha panels use the dedicated parallel listener below.
                    if p.get("type") == "Auto Captcha Panel":
                        continue
                    # Manual API panels use their isolated parallel listener below.
                    # Auto Captcha and all non-manual provider routing remain on this original path.
                    if p.get("type") != "Auto Captcha Panel" and str(p.get("source_type") or "").upper() == "MANUAL":
                        continue
                    if p.get("type") == "Auto Captcha Panel":
                        sess = panel_sessions.get(idx)
                        
                        if not sess:
                            now = time.time()
                            if now - p.get("last_login_attempt", 0) < 30: 
                                continue 
                            p["last_login_attempt"] = now
                            
                            success = attempt_auto_login(p, idx)
                            save_db()
                            if not success:
                                continue 
                            sess = panel_sessions.get(idx)
                            
                        try:
                            parsed_data, res_text = fetch_cpt_panel_cdrs(p, sess, p["msg_link"])
                            p["login_status"] = "✅ Active & Fetching"
                        except Exception as e:
                            p["login_status"] = "❌ Session Expired (Retrying...)"
                            del panel_sessions[idx]
                            save_db()
                            continue

                    elif p.get("api_url") or p.get("full_api_url"): 
                        full_url = p.get("full_api_url", "").strip()
                        url = p.get("api_url", "").strip()
                        token = p.get("token", "").strip()
                        if not full_url and not url: continue
                        
                        urls_to_try = []
                        if full_url:
                            urls_to_try.append(full_url)
                        else:
                            if "{token}" in url or "{key}" in url:
                                urls_to_try.append(url.replace("{token}", token).replace("{key}", token))
                            elif "token=" in url or "key=" in url:
                                urls_to_try.append(url)
                            else:
                                sep = '&' if '?' in url else '?'
                                urls_to_try.append(f"{url}{sep}token={token}")
                                urls_to_try.append(f"{url}{sep}key={token}&start=0")
                                urls_to_try.append(f"{url}{sep}key={token}")
                            
                        parsed_data = []
                        headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36', 'Connection': 'keep-alive'}
                        sess = manual_panel_http_sessions.get(idx)
                        if sess is None:
                            sess = requests.Session()
                            adapter = HTTPAdapter(pool_connections=8, pool_maxsize=8, max_retries=0)
                            sess.mount('http://', adapter)
                            sess.mount('https://', adapter)
                            sess.headers.update(headers)
                            manual_panel_http_sessions[idx] = sess
                        for try_url in urls_to_try:
                            try:
                                res = sess.get(try_url, timeout=MANUAL_PANEL_HTTP_TIMEOUT)
                                parsed_data = parse_panel_response(res.text, p)
                                if parsed_data:
                                    if not full_url and try_url != url and token:
                                        p["api_url"] = try_url.replace(token, "{token}")
                                        save_db()
                                    break
                            except: continue
                        if not parsed_data: continue
                    else:
                        continue
                    
                    if p.get("type") != "Auto Captcha Panel":
                        limit = p.get("records", 0)
                        if limit > 0: parsed_data = parsed_data[:limit]
                        
                    for item in parsed_data:
                        # Auto Captcha path remains exactly on its original branch.
                        # API Panel records are Manual-panel traffic and carry a stable
                        # panel_id so identical numbers on different panels never cross-route.
                        if p.get("type") == "Auto Captcha Panel":
                            _process_auto_captcha_panel_item(p, item)
                        else:
                            try:
                                manual_p = p.copy()
                                manual_p.setdefault("source_type", "MANUAL")
                                manual_p.setdefault("panel_id", f"manual_api_{idx}")
                                manual_p.setdefault("panel_name", manual_p.get("name", f"Manual Panel {idx+1}"))
                                _manual_panel_processing_pool.submit(_process_manual_panel_item_fast, manual_p, item.copy())
                            except Exception:
                                # Saturated worker pool: leave the item unprocessed so
                                # the next poll can pick it up again.
                                pass

        except Exception as e:
            pass
        LOCAL_STOP.wait(MANUAL_PANEL_POLL_INTERVAL)

user_cache = {}

def _sanitize_user_record(data, user_id):
    record = {}
    if not isinstance(data, dict):
        data = {}
    record["user_id"] = int(user_id)
    try:
        record["balance"] = float(data.get("balance", 0.0) or 0.0)
    except Exception:
        record["balance"] = 0.0

    # Non-financial fields required by existing bot functionality.
    record["total_refers"] = int(data.get("total_refers", 0) or 0)
    record["total_otps"] = int(data.get("total_otps", 0) or 0)
    record["banned"] = bool(data.get("banned", False))
    record["verified"] = bool(data.get("verified", False))
    record["referred_by"] = data.get("referred_by")
    record["ref_paid"] = bool(data.get("ref_paid", False))

    # Sensitive fields are optional and only exist when the user has set them.
    if str(data.get("two_fa_secret", "") or "").strip():
        record["two_fa_secret"] = str(data["two_fa_secret"]).strip().replace(" ", "")
    if str(data.get("last_withdraw_method", "") or "").strip():
        record["last_withdraw_method"] = str(data["last_withdraw_method"]).strip()
    if str(data.get("last_withdraw_number", "") or "").strip():
        record["last_withdraw_number"] = str(data["last_withdraw_number"]).strip()
    return record

def _touch_local_user_profile(uid, record=None):
    uid = int(uid)
    if record is not None:
        local_user_profiles[uid] = dict(record)
    local_user_profile_last_seen[uid] = time.time()
    if len(local_user_profiles) > MAX_LOCAL_USER_PROFILES:
        excess = len(local_user_profiles) - MAX_LOCAL_USER_PROFILES
        oldest = sorted(local_user_profile_last_seen.items(), key=lambda kv: kv[1])[:max(1, excess)]
        for old_uid, _ in oldest:
            local_user_profiles.pop(int(old_uid), None)
            local_user_profile_last_seen.pop(int(old_uid), None)

def _write_user_record(user_id, record, merge=True):
    """Persist user details locally; queue them for the hourly Firebase user sync."""
    uid = int(user_id)
    clean = {k: record[k] for k in USER_REMOTE_FIELDS if k in record}
    clean["user_id"] = uid
    with USER_CACHE_LOCK:
        cached = user_cache.get(uid)
        if not isinstance(cached, dict):
            cached = {"user_id": uid, "balance": 0.0, "total_refers": 0, "total_otps": 0,
                      "banned": False, "verified": False, "ref_paid": False}
            user_cache[uid] = cached
        if merge:
            cached.update(clean)
        else:
            cached.clear(); cached.update(clean)
        _touch_local_user_profile(uid, cached)
    with LEDGER_LOCK:
        pending_user_profile_updates.setdefault(uid, {}).update(clean)
    save_db()
    return True

def _local_unsynced_for_user(user_id, remote_sync_id=None):
    """Return local deltas that are not yet confirmed by the remote sync marker."""
    uid=int(user_id)
    balance_delta=float(pending_user_balance_deltas.get(uid,0.0) or 0.0)
    otp_count=int(pending_user_otp_counts.get(uid,0) or 0)
    batch=pending_user_sync_batches.get(uid)
    if batch and str(batch.get("sync_id","")) != str(remote_sync_id or ""):
        balance_delta += float(batch.get("balance_delta",0.0) or 0.0)
        otp_count += int(batch.get("otp_count",0) or 0)
    return balance_delta, otp_count

_FIREBASE_HYDRATION_POOL = ThreadPoolExecutor(max_workers=4, thread_name_prefix="firebase-hydrate")
_FIREBASE_HYDRATION_LOCK = threading.RLock()
_FIREBASE_HYDRATION_INFLIGHT = set()

def _default_local_user_record(user_id):
    uid = int(user_id)
    fallback = {"user_id": uid, "balance": 0.0, "total_refers": 0, "total_otps": 0,
                "banned": False, "verified": False, "ref_paid": False}
    dbal, dotp = _local_unsynced_for_user(uid)
    fallback["balance"] += dbal
    fallback["balance"] -= float(pending_user_withdrawal_reservations.get(uid, 0.0) or 0.0)
    fallback["total_otps"] += dotp
    return fallback

def _hydrate_user_from_firestore(user_id):
    uid = int(user_id)
    try:
        if not db:
            return
        _debug_log(f"Firebase hydrate START uid={uid}")
        doc_ref = db.collection("users").document(str(uid))
        doc = doc_ref.get(timeout=3.0)
        if doc.exists:
            raw = doc.to_dict() or {}
            remote_sync_id = str(raw.get("last_local_sync_id", "") or "")
            record = _sanitize_user_record(raw, uid)
            required_fields = ("user_id", "balance", "total_refers", "total_otps", "banned", "verified", "ref_paid")
            if any(field not in raw for field in required_fields):
                try:
                    _write_user_record(uid, dict(record), merge=True)
                except Exception:
                    pass
        else:
            remote_sync_id = ""
            record = _sanitize_user_record({}, uid)
            try:
                _write_user_record(uid, record, merge=False)
            except Exception:
                pass
        with USER_CACHE_LOCK:
            dbal, dotp = _local_unsynced_for_user(uid, remote_sync_id)
            record["balance"] += dbal
            record["balance"] -= float(pending_user_withdrawal_reservations.get(uid, 0.0) or 0.0)
            record["total_otps"] += dotp
            user_cache[uid] = record
            _touch_local_user_profile(uid, record)
            save_db()
        _debug_log(f"Firebase hydrate OK uid={uid}")
    except Exception as exc:
        _debug_log(f"Firebase hydrate FAIL uid={uid}: {type(exc).__name__}: {str(exc)[:180]}")
    finally:
        with _FIREBASE_HYDRATION_LOCK:
            _FIREBASE_HYDRATION_INFLIGHT.discard(uid)

def _schedule_user_firestore_hydration(user_id):
    uid = int(user_id)
    if not db:
        return
    with _FIREBASE_HYDRATION_LOCK:
        if uid in _FIREBASE_HYDRATION_INFLIGHT:
            return
        _FIREBASE_HYDRATION_INFLIGHT.add(uid)
    try:
        _FIREBASE_HYDRATION_POOL.submit(_hydrate_user_from_firestore, uid)
    except Exception:
        with _FIREBASE_HYDRATION_LOCK:
            _FIREBASE_HYDRATION_INFLIGHT.discard(uid)

def get_user(user_id):
    """Fast local-first user lookup; Firebase hydration never blocks Telegram handlers."""
    uid = int(user_id)
    started = time.perf_counter()
    with USER_CACHE_LOCK:
        cached = user_cache.get(uid)
        if cached is not None:
            _touch_local_user_profile(uid, cached)
            _debug_log(f"get_user CACHE uid={uid} elapsed={_debug_duration_ms(started):.0f}ms")
            return cached
        local_cached = local_user_profiles.get(uid)
        if isinstance(local_cached, dict):
            cached = dict(local_cached)
            user_cache[uid] = cached
            _touch_local_user_profile(uid, cached)
            cached["balance"] = float(cached.get("balance", 0.0) or 0.0) - float(pending_user_withdrawal_reservations.get(uid, 0.0) or 0.0)
            _schedule_user_firestore_hydration(uid)
            _debug_log(f"get_user LOCAL_PROFILE uid={uid} elapsed={_debug_duration_ms(started):.0f}ms")
            return cached
    fallback = _default_local_user_record(uid)
    with USER_CACHE_LOCK:
        user_cache[uid] = fallback
        _touch_local_user_profile(uid, fallback)
    _schedule_user_firestore_hydration(uid)
    _debug_log(f"get_user LOCAL_FALLBACK uid={uid} elapsed={_debug_duration_ms(started):.0f}ms")
    return fallback

def update_user_fields(user_id, **fields):
    uid = int(user_id)
    allowed = {k: v for k, v in fields.items()
               if k in USER_REMOTE_FIELDS and k not in {"balance", "total_otps"}}
    if not allowed:
        return True
    with USER_CACHE_LOCK:
        cached = user_cache.get(uid)
        if not isinstance(cached, dict):
            cached = {"user_id": uid, "balance": 0.0, "total_refers": 0, "total_otps": 0,
                      "banned": False, "verified": False, "ref_paid": False}
            user_cache[uid] = cached
        cached.update(allowed)
        _touch_local_user_profile(uid, cached)
    with LEDGER_LOCK:
        pending_user_profile_updates.setdefault(uid, {}).update(allowed)
        last_user_ledger_activity_at[uid] = time.time()
    save_db()
    return True

def _local_user_mutation(user_id, amount=0.0, otp_count=0):
    global last_otp_activity_at
    user_id=int(user_id); amount=float(amount); otp_count=int(otp_count)
    now=time.time()

    # A financial mutation must start from the best known authoritative balance.
    # If the user is not cached yet, load Firebase once (when available) before
    # applying the local delta. This prevents an uncached user from being treated
    # as a zero-balance account. When Firebase is unavailable, get_user() still
    # merges any durable local pending deltas from the local snapshot.
    with LEDGER_LOCK:
        with USER_CACHE_LOCK:
            cached = user_cache.get(user_id)
        if cached is None:
            cached = get_user(user_id)

        with USER_CACHE_LOCK:
            u=user_cache.get(user_id)
            if u is None:
                u=cached if isinstance(cached,dict) else {"user_id":user_id,"balance":0.0,"total_refers":0,"total_otps":0,"banned":False,"verified":False,"ref_paid":False}
                user_cache[user_id]=u
            u["balance"]=float(u.get("balance",0.0) or 0.0)+amount
            if otp_count:
                u["total_otps"]=int(u.get("total_otps",0) or 0)+otp_count
            if amount:
                pending_user_balance_deltas[user_id]=float(pending_user_balance_deltas.get(user_id,0.0) or 0.0)+amount
            if otp_count:
                pending_user_otp_counts[user_id]=int(pending_user_otp_counts.get(user_id,0) or 0)+otp_count
            _touch_local_user_profile(user_id, u)
            last_user_ledger_activity_at[user_id]=now
            if otp_count:
                last_otp_activity_at=now

    # Financial state must be on disk before returning. The write is atomic and
    # fsynced by _write_local_snapshot(), so restart/update cannot silently lose
    # a just-applied balance mutation.
    return save_db_sync()

def _rate_provider(provider):
    p=str(provider or "").strip().upper()
    return {"STEXSMS":"STEX","VOLTXSMS":"VOLTX","ZENEXNETWORK":"ZENEX","MANUAL NUMBER":"MANUAL","AUTO PANEL":"PANEL"}.get(p,p or "GLOBAL")


def _premium_flag_html_for_country(country):
    """Resolve ISO/calling-code/full-name labels to the admin-uploaded premium flag."""
    raw = str(country or "").strip()
    norm = _normalize_label(raw)
    flags = bot_settings.get("premium_flags", {}) or {}
    for code, data in flags.items():
        aliases = {
            _normalize_label(str(code)),
            _normalize_label(data.get("iso", "")),
            _normalize_label(data.get("name", "")),
        }
        if norm in aliases:
            eid = str(data.get("id", "") or "").strip()
            char = data.get("char", "🌍") or "🌍"
            return f'<tg-emoji emoji-id="{eid}">{char}</tg-emoji>' if eid else str(char)
    try:
        return get_flag_info_html(raw)
    except Exception:
        return "🌍"


def _bootstrap_premium_flags_from_local_txt():
    """Load missing premium flag mappings from a colocated Flag Emojis.txt.

    Admin-configured flags already present in local state are never overwritten.
    This is a startup fallback so a deployment can immediately render the uploaded
    Premium Flags file even when the local settings snapshot predates the upload.
    """
    try:
        target = BASE_DIR / "Flag Emojis.txt"
        if not target.exists():
            return 0
        flags = bot_settings.setdefault("premium_flags", {})
        added = 0
        for raw_line in target.read_text(encoding="utf-8", errors="ignore").splitlines():
            line = str(raw_line or "").strip()
            if not line or line.startswith("#"):
                continue
            m = re.search(r"^(.*?)\((\d{1,4})\)\s*\(([A-Za-z]{2,3})\)\s+[^\{]+?(\{.*\})$", line)
            if not m:
                continue
            name = m.group(1).strip()
            code = m.group(2).strip()
            iso = m.group(3).upper().strip()
            meta = {}
            blob = m.group(4).strip()
            for candidate in (blob, blob[1:-1] if blob.startswith("{{") and blob.endswith("}}") else ""):
                if not candidate:
                    continue
                try:
                    parsed = json.loads(candidate)
                except Exception:
                    continue
                if isinstance(parsed, dict):
                    meta = parsed
                    break
            char = str(meta.get("emoji") or meta.get("char") or "").strip()
            eid = str(meta.get("id") or meta.get("emoji_id") or meta.get("custom_emoji_id") or "").strip()
            if code and iso and name and char and eid.isdigit() and code not in flags:
                flags[code] = {"char": char, "iso": iso, "name": name, "id": eid}
                added += 1
        return added
    except Exception:
        return 0


def _premium_flag_id_for_country(country):
    raw = str(country or "").strip()
    norm = _normalize_label(raw)
    for code, data in (bot_settings.get("premium_flags", {}) or {}).items():
        aliases = {
            _normalize_label(str(code)),
            _normalize_label(data.get("iso", "")),
            _normalize_label(data.get("name", "")),
        }
        if norm in aliases:
            return str(data.get("id", "") or "5780471598922337683")
    return ""


