def _write_prepared_analysis_state_now(state):
    try:
        path = Path(DB_FILE)
        path.parent.mkdir(parents=True, exist_ok=True)
        with LOCAL_WRITE_LOCK:
            data = {}
            if path.is_file():
                with path.open("r", encoding="utf-8") as fh:
                    loaded = json.load(fh)
                if isinstance(loaded, dict):
                    data = loaded
            data["analysis_state"] = json.loads(json.dumps(state, ensure_ascii=False))
            tmp = path.with_name(path.name + ".tmp")
            with tmp.open("w", encoding="utf-8") as fh:
                json.dump(data, fh, ensure_ascii=False, separators=(",", ":"))
                fh.flush()
                os.fsync(fh.fileno())
            os.replace(tmp, path)
        return True
    except Exception as exc:
        _terminal_log(f"[ANALYSIS] prepared-state save failed: {exc}")
        return False

def _persist_prepared_analysis_state_async(state):
    global _PREPARED_ANALYSIS_WRITE_VERSION
    if not isinstance(state, dict):
        return False
    with _PREPARED_ANALYSIS_WRITE_LOCK:
        _PREPARED_ANALYSIS_WRITE_VERSION += 1
        generation = _PREPARED_ANALYSIS_WRITE_VERSION
        snapshot = json.loads(json.dumps(state, ensure_ascii=False))
    def _worker():
        with _PREPARED_ANALYSIS_WRITE_LOCK:
            if generation != _PREPARED_ANALYSIS_WRITE_VERSION:
                return
        _write_prepared_analysis_state_now(snapshot)
    try:
        _PREPARED_ANALYSIS_WRITE_POOL.submit(_worker)
        return True
    except Exception:
        return False

