def _fixed_premium_service_emoji_html(service, display_name=None):
    norm = _normalize_label(service)
    did = FIXED_PREMIUM_SERVICE_EMOJI_IDS.get(norm)
    if not did and display_name:
        did = FIXED_PREMIUM_SERVICE_EMOJI_IDS.get(_normalize_label(display_name))
    if did:
        visible = display_name or service or "Service"
        return f'<tg-emoji emoji-id="{did}">📱</tg-emoji>'
    return ""

def _pretty_service_display_name(service):
    """Return a clean user-facing service label with provider identity removed."""
    raw = str(service or "").strip()
    if not raw:
        return "Service"

    # Provider/config suffixes should never leak into user-facing button labels.
    # Repeat until stable so labels like ``FACEBOOK_ZNX_VTX`` are fully cleaned.
    clean = raw
    for _ in range(3):
        next_clean = re.sub(r"(?:[_\- ]+)(?:ZNX|VTX|STEX)$", "", clean, flags=re.IGNORECASE).strip(" _-")
        if next_clean == clean:
            break
        clean = next_clean

    aliases = {
        "facebook znx": "Facebook",
        "facebook_vznx": "Facebook",
        "instagram znx": "Instagram",
        "whatsapp znx": "WhatsApp",
        "telegram znx": "Telegram",
        "tiktok znx": "TikTok",
        "tik tok znx": "TikTok",
        "facebook pc clone": "FB Forgot",
        "fb pc clone": "FB Forgot",
        "facebook clone": "FB Forgot",
        "fb clone": "FB Forgot",
        "pc clone": "FB Forgot",
        "fb forgot znx": "FB Forgot",
        "fb forgot vtx": "FB Forgot",
        "fb forgot stex": "FB Forgot",
    }
    return aliases.get(_normalize_label(clean), clean)


def _service_emoji_aliases(service):
    """Generate exact/variant aliases for Premium Emoji resolution.

    The user-facing service label is never rewritten here. This function only
    derives lookup keys so names such as ``Facebook V2`` or ``FB Forgot_ZNX``
    can still receive the correct Premium Emoji.
    """
    raw = str(service or "").strip()
    pretty = _pretty_service_display_name(raw)
    aliases = {_normalize_label(raw), _normalize_label(pretty)}

    # Strip only explicit provider transport suffixes for icon detection.
    base = re.sub(r"(?:[_\- ]+)(?:ZNX|VTX|STEX)$", "", raw, flags=re.IGNORECASE).strip(" _-")
    if base:
        aliases.add(_normalize_label(base))

    # Preserve the dedicated FB Clone identity.
    if _is_fb_clone_range_item({"service": raw, "tag": raw}):
        aliases.update({"fb pc clone", "facebook pc clone", "fb clone"})

    # Add a canonical fixed-service key when the configured label contains a
    # known service token (e.g. Facebook V2, WhatsApp Business 2).
    fixed_keys = sorted(FIXED_PREMIUM_SERVICE_EMOJI_IDS.keys(), key=len, reverse=True)
    for key in fixed_keys:
        if re.search(rf"(?<![a-z0-9]){re.escape(key)}(?![a-z0-9])", _normalize_label(base or raw)):
            aliases.add(key)
    return {x for x in aliases if x}


def _detected_fixed_service_key(service):
    """Detect a known fixed-logo service inside a custom configured label."""
    raw = _normalize_label(_pretty_service_display_name(str(service or "").strip()))
    if not raw:
        return ""
    # Prefer the most specific/longest aliases first.
    for key in sorted(FIXED_PREMIUM_SERVICE_EMOJI_IDS.keys(), key=len, reverse=True):
        if raw == key or re.search(rf"(?<![a-z0-9]){re.escape(key)}(?![a-z0-9])", raw):
            return key
    # SERVICE_SMS_KEYWORDS gives broader aliases such as ``fb``/``insta``.
    try:
        for canonical, keywords in SERVICE_SMS_KEYWORDS.items():
            if canonical not in FIXED_PREMIUM_SERVICE_EMOJI_IDS:
                continue
            for kw in sorted((str(x).strip().casefold() for x in keywords), key=len, reverse=True):
                if kw and (raw == kw or re.search(rf"(?<![a-z0-9]){re.escape(kw)}(?![a-z0-9])", raw)):
                    return canonical
    except Exception:
        pass
    return ""

def _premium_service_record(service):
    """Resolve a configured service to its exact Premium Emoji record."""
    configured = _configured_service_catalog()
    canonical = configured.get(_normalize_label(service)) or str(service or "").strip()
    target_aliases = _service_emoji_aliases(canonical) | _service_emoji_aliases(service)
    apps = bot_settings.get("premium_apps", {}) or {}
    if isinstance(apps, dict):
        for key, data in apps.items():
            if not isinstance(data, dict):
                continue
            aliases = {
                _normalize_label(str(key)),
                _normalize_label(str(data.get("name", ""))),
                _normalize_label(str(data.get("service", ""))),
            }
            if target_aliases & aliases:
                # Keep the admin/provider service label, but hide only explicit
                # provider transport suffixes such as _ZNX/_VTX/_STEX from the
                # user-facing name. This also lets FB FORGOT_ZNX resolve to the
                # configured FB Forgot Premium Emoji instead of displaying the
                # raw provider suffix.
                display_source = str(data.get("name") or canonical).strip()
                return _pretty_service_display_name(display_source), data

    # Fixed core-service emojis are the final deterministic fallback.
    for alias in target_aliases:
        fixed_id = FIXED_PREMIUM_SERVICE_EMOJI_IDS.get(alias)
        if fixed_id:
            name = _pretty_service_display_name(canonical)
            return name, {"char": "📱", "id": fixed_id, "name": name}
    return _pretty_service_display_name(canonical), None


def _center_country_header_html(flag_html, country, short_name):
    """Build a left-aligned country header for the number screen."""
    country = str(country or "Unknown").strip()
    short_name = str(short_name or "XX").strip().upper()
    # Keep the country row flush-left. Do not add em-space/visual-centering
    # padding, so the flag + country name always start from the left edge.
    return f"{flag_html} <b>{html.escape(country)} ({html.escape(short_name)})</b>"


def _brand_new_number_line_html():
    """Exact requested FRD Prime brand line with the uploaded Premium Fire emoji."""
    fire = _premium_body_emoji_html("🔥")
    return f"<b>Speed Up</b> {fire}"

_PREPARED_MENU_CACHE_LOCK = threading.RLock()
_PREPARED_MENU_CACHE = {}
_PREPARED_MENU_CACHE_MAX = 512

def _prepared_menu_cache_get(key):
    with _PREPARED_MENU_CACHE_LOCK:
        value = _PREPARED_MENU_CACHE.get(key)
        return value

def _prepared_menu_cache_put(key, value):
    with _PREPARED_MENU_CACHE_LOCK:
        if len(_PREPARED_MENU_CACHE) >= _PREPARED_MENU_CACHE_MAX:
            try:
                _PREPARED_MENU_CACHE.pop(next(iter(_PREPARED_MENU_CACHE)))
            except Exception:
                _PREPARED_MENU_CACHE.clear()
        _PREPARED_MENU_CACHE[key] = value

def _render_fast_services_menu(snapshot=None):
    snap = snapshot or _fast_ui_snapshot()
    cache_key = ("services", int(snap.get("version", 0) or 0), int(_analysis_snapshot().get("version", 0) or 0))
    cached = _prepared_menu_cache_get(cache_key)
    if cached is not None:
        return cached
    c_msg = bot_settings.get("custom_messages", {}).get("get_number", {})
    txt = render_user_body_text(c_msg.get("text", f"{PEM['pin']} Select Service"))
    apps_db = bot_settings.get("premium_apps", {}) or {}
    analysis = _analysis_snapshot()
    ranked = analysis.get("services", {}) or {}
    order = list(analysis.get("service_order", ()) or ())
    if not order:
        order = list(snap.get("services", ()) or ())
    configured = _configured_service_catalog()
    services = []
    seen = set()
    for name in order:
        canonical = configured.get(_normalize_label(name))
        if canonical and _normalize_label(canonical) not in seen:
            services.append(canonical); seen.add(_normalize_label(canonical))
    # Keep configured services visible even with zero traffic; they are simply
    # placed after services that currently have evidence.
    for name in snap.get("services", ()):
        canonical = configured.get(_normalize_label(name))
        if canonical and _normalize_label(canonical) not in seen:
            services.append(canonical); seen.add(_normalize_label(canonical))
    # Match the analytical order for every service. FB Forgot is ranked by its
    # own tagged provider evidence rather than being pinned below the others.
    services.sort(key=lambda x: (
        -float((ranked.get(_normalize_label(x), {}) or {}).get("service_score", 0.0) or 0.0),
        -int((ranked.get(_normalize_label(x), {}) or {}).get("total_hits", 0) or 0),
        -int((ranked.get(_normalize_label(x), {}) or {}).get("recent_traffic_180s", 0) or 0),
        _normalize_label(_pretty_service_display_name(x)),
    ))

    # Final UI guard: two config keys can still resolve to the same public label.
    # Never render the same user-facing service twice.
    deduped = []
    seen_public = set()
    for s in services:
        public = _normalize_label(_pretty_service_display_name(s))
        if not public or public in seen_public:
            continue
        seen_public.add(public)
        deduped.append(FB_FORGOT_CANONICAL_NAME if public == _normalize_label(FB_FORGOT_CANONICAL_NAME) else s)
    services = deduped

    buttons = []
    for rank, s in enumerate(services, 1):
        emoji_id = _service_emoji_id(s)
        button = {
            "text": f"{_pretty_service_display_name(s)}{' 🔥' if rank == 1 else ''}",
            "callback_data": f"g_s_{s}",
            "style": "primary",
        }
        if emoji_id:
            button["icon_custom_emoji_id"] = emoji_id
        buttons.append(button)
    kb = _two_column_rows(buttons)
    for b in c_msg.get("buttons", []):
        b_copy = b.copy(); b_copy.setdefault("style", "primary"); kb.append([b_copy])
    kb.append([{"text": "Close", "icon_custom_emoji_id": "5420130255174146570", "callback_data": "close_msg", "style": "danger"}])
    result = (txt, {"inline_keyboard": kb})
    _prepared_menu_cache_put(cache_key, result)
    return result

def _prepared_active_range_country_fallback(service, active_ranges=None):
    """Build Top-3 country evidence locally from the prepared Active-Ranges feed."""
    target = _resolve_configured_service_name(service) or str(service or "").strip()
    if not target:
        return []
    rows = {}
    routes = active_ranges
    if routes is None:
        try:
            with _ANALYSIS_STATE_LOCK:
                routes = list((_ANALYSIS_STATE.get("active_ranges", ()) or ()))
        except Exception:
            routes = []
    for item in routes or []:
        if not isinstance(item, dict):
            continue
        try:
            raw_service = _analysis_route_service(item)
            if not raw_service:
                continue
            canonical = _facebook_routing_service(item)
            if _normalize_label(target) == _normalize_label(FB_CLONE_SERVICE_NAME):
                if not _is_fb_clone_range_item(item):
                    continue
            elif _normalize_label(target) == "facebook":
                if _is_fb_clone_range_item(item):
                    continue
            elif not _service_match_for_range(raw_service, target):
                continue
            country = _analysis_route_country(item)
            rng = _analysis_route_range(item)
            if not country and rng:
                try:
                    country = _detect_country_from_range(rng, target)
                except Exception:
                    country = ""
            if not country or not rng:
                continue
            hits = _analysis_route_hits(item)
            key = _normalize_label(country)
            node = rows.setdefault(key, {"country": country, "hits": 0, "range": "", "range_hits": -1})
            node["hits"] += hits
            if hits > node["range_hits"]:
                node["range"] = rng
                node["range_hits"] = hits
        except Exception:
            continue
    result = sorted(rows.values(), key=lambda x: (-int(x["hits"]), -int(x["range_hits"]), _normalize_label(x["country"])))
    return result[:3]


def _render_fast_countries_menu(service, snapshot=None):
    snap = snapshot or _fast_ui_snapshot()
    service = str(service or "").strip()
    analysis_version = int(_analysis_snapshot().get("version", 0) or 0)
    cache_key = ("countries", _normalize_label(service), int(snap.get("version", 0) or 0), analysis_version)
    cached = _prepared_menu_cache_get(cache_key)
    if cached is not None:
        return cached
    configured = _configured_service_catalog()
    canonical_service = configured.get(_normalize_label(service))
    if not canonical_service:
        return render_user_body_text("❌ <b>Service is not configured.</b>"), {"inline_keyboard": [[{"text": "Back", "icon_custom_emoji_id": "5267490665117275176", "callback_data": "back_to_services", "style": "danger"}]]}

    # Primary source is continuous analysis: exactly Top-3 countries ordered by
    # descending hits. If analysis has no countries yet, preserve existing saved
    # configured countries as a startup fallback instead of showing a blank menu.
    analysis = _analysis_snapshot()
    stat = (analysis.get("services", {}) or {}).get(_normalize_label(canonical_service), {}) or {}
    ranked_countries = list(stat.get("countries", ()) or ())
    if ranked_countries:
        country_items = ranked_countries[:3]
    elif _normalize_label(canonical_service) == _normalize_label(FB_CLONE_SERVICE_NAME):
        # Direct live-source fallback fixes a cold/transition window where the
        # dedicated clone service exists but the prepared ranking is still warming.
        try:
            with _ANALYSIS_STATE_LOCK:
                active_for_clone = list((_ANALYSIS_STATE.get("active_ranges", ()) or ()))
            clone_rows = _fb_clone_country_top_ranges(active_for_clone)
        except Exception:
            clone_rows = []
        country_items = [
            {"country": r.get("country", ""), "hits": int(r.get("hits", 0) or 0),
             "top_range": str(r.get("range", "") or ""), "top_range_hits": int(r.get("range_hits", 0) or 0)}
            for r in clone_rows[:3]
        ]
    else:
        # First recover directly from the latest prepared Active-Ranges feed.
        # This is local-only and keeps the user click instant even when the full
        # ranked snapshot is between refresh generations.
        direct_items = _prepared_active_range_country_fallback(canonical_service)
        if direct_items:
            country_items = [
                {"country": r.get("country", ""), "hits": int(r.get("hits", 0) or 0),
                 "top_range": str(r.get("range", "") or ""), "top_range_hits": int(r.get("range_hits", 0) or 0)}
                for r in direct_items
            ]
        else:
            fallback = list(_configured_service_country_union(canonical_service))[:3]
            country_items = []
            for c in fallback:
                route = _best_analyzed_route(canonical_service, c) or {}
                country_items.append({
                    "country": c,
                    "hits": int(route.get("hits", 0) or 0),
                    "top_range": str(route.get("range", "") or ""),
                    "top_range_hits": int(route.get("hits", 0) or 0),
                })

    c_msg = bot_settings.get("custom_messages", {}).get("select_country", {})
    raw_txt = c_msg.get("text", "📌 Select a country for {service}:").replace("{service}", canonical_service)
    body_lines = [raw_txt, "", "<b>Top 3 countries by hits</b>"]
    buttons = []
    for rank, node in enumerate(country_items, 1):
        c = str(node.get("country", "") or "").strip()
        if not c:
            continue
        premium_id = _premium_flag_id_for_country(c)
        price = snap.get("prices", {}).get((canonical_service, _normalize_label(c)))
        if price is None:
            price = get_reward_rate("MANUAL", canonical_service, c, bot_settings.get("otp_reward", 0.0))
        hits = int(node.get("hits", 0) or 0)
        top_rng = str(node.get("top_range", "") or "").strip()
        iso_short = _country_short_name(c).upper() or "XX"
        fire_html = f" {_premium_body_emoji_html('🔥')}" if rank == 1 else ""
        range_text = f" • <code>{html.escape(top_rng)}</code>" if top_rng else " • <i>range N/A</i>"
        body_lines.append(f"{rank}. {_premium_flag_html_for_country(c)} <b>{html.escape(iso_short)}</b> • <b>{hits}</b> hits{range_text}{fire_html}")
        label = f"{_country_short_name(c).upper()} · {hits}"
        buttons.append({
            "text": label,
            "icon_custom_emoji_id": premium_id,
            "callback_data": f"g_c_{canonical_service}_{c}",
            "style": "success",
        })
    kb = _two_column_rows(buttons)
    for b in c_msg.get("buttons", []):
        b_copy = b.copy(); b_copy.setdefault("style", "primary"); kb.append([b_copy])
    kb.append([{"text": "Back", "icon_custom_emoji_id": "5267490665117275176", "callback_data": "back_to_services", "style": "danger"}])
    txt = render_user_body_text("\n".join(body_lines))
    result = (txt, {"inline_keyboard": kb})
    _prepared_menu_cache_put(cache_key, result)
    return result

def _fast_ui_worker():
    # UI-only worker. Expensive/full intelligence research is owned exclusively
    # by the unified three-minute provider checkpoint or an explicit Admin Refresh.
    # User interactions therefore consume only prepared local snapshots.
    while not _FAST_UI_STOP.is_set():
        try:
            now = time.time()
            if _FAST_UI_DIRTY.is_set():
                _FAST_UI_DIRTY.clear()
                snap = _build_fast_ui_snapshot()
            else:
                snap = _fast_ui_snapshot()

            if _UI_PUBLISH_DIRTY.is_set() or (now - _LAST_UI_PUBLISH) >= _UI_PUBLISH_INTERVAL:
                _publish_active_menus(snap, force=_UI_PUBLISH_DIRTY.is_set())

            _flush_live_ui_registry(force=False)
        except Exception as exc:
            _terminal_log(f"[FAST_UI] worker error: {exc}")
        _FAST_UI_STOP.wait(_FAST_UI_REFRESH_INTERVAL)


_SERVICE_COUNTRY_CACHE = {}
_SERVICE_COUNTRY_CACHE_TTL = 1.5

def _configured_service_country_union(service):
    """Collect countries only for the selected service across all configured providers/local stock."""
    _cache_key = _normalize_label(service)
    _cached = _SERVICE_COUNTRY_CACHE.get(_cache_key)
    _now = time.monotonic()
    try:
        _cache_snapshot_version = _FAST_UI_VERSION
    except Exception:
        _cache_snapshot_version = 0
    if _cached and (_now - _cached[0]) < _SERVICE_COUNTRY_CACHE_TTL and (_cached[2] if len(_cached) > 2 else 0) == _cache_snapshot_version:
        return list(_cached[1])
    target = _normalize_label(service)
    countries = {}

    def add(source):
        if not isinstance(source, dict):
            return
        for srv, values in source.items():
            if _normalize_label(srv) != target or not isinstance(values, dict):
                continue
            for country in values.keys():
                label = str(country).strip()
                if label:
                    countries[_normalize_label(label)] = label

    for batch in number_batches.values():
        if _normalize_label(batch.get("service", "")) == target and batch.get("numbers"):
            label = str(batch.get("country", "")).strip()
            if label:
                countries[_normalize_label(label)] = label

    add(bot_settings.get("stex_services", {}))
    add(bot_settings.get("voltx_services", {}))
    add(bot_settings.get("zenex_services", {}))

    # Prefer the premium-flag database's canonical country name when configured
    # data uses ISO/calling-code aliases.
    for key, label in list(countries.items()):
        for code, data in (bot_settings.get("premium_flags", {}) or {}).items():
            aliases = {_normalize_label(str(code)), _normalize_label(data.get("iso", "")), _normalize_label(data.get("name", ""))}
            if _normalize_label(label) in aliases and data.get("name"):
                countries[key] = str(data.get("name")).strip()
                break
    result = sorted(set(countries.values()), key=lambda x: _normalize_label(x))
    _SERVICE_COUNTRY_CACHE[_cache_key] = (_now, tuple(result), _cache_snapshot_version)
    return result


def _service_match_alias_keys(value):
    """Return known canonical service identities found inside a display label."""
    norm = _normalize_label(value)
    if not norm:
        return set()

    canonical_aliases = {
        "fb": "facebook",
        "facebook": "facebook",
        "fb clone": "fb forgot",
        "facebook pc clone": "fb forgot",
        "pc clone": "fb forgot",
        "fb new": "facebook",
        "new fb": "facebook",
        "facebook new": "facebook",
        "tik tok": "tiktok",
        "tiktok": "tiktok",
    }
    found = set()
    exact = canonical_aliases.get(norm, norm)
    if exact == "fb forgot" or "fb pc clone" in norm or "fb clone" in norm:
        # Dedicated clone identity is exclusive; do not also classify it as
        # normal Facebook merely because the label contains ``fb``.
        return {"fb forgot"}
    if exact in SERVICE_SMS_KEYWORDS:
        found.add(exact)

    # Premium-App records are allowed to define custom/provider aliases.
    apps = bot_settings.get("premium_apps", {}) or {}
    if isinstance(apps, dict):
        for key, data in apps.items():
            if not isinstance(data, dict):
                continue
            for raw_alias in (key, data.get("name", ""), data.get("service", "")):
                alias = _normalize_label(raw_alias)
                if not alias:
                    continue
                canonical = canonical_aliases.get(alias, alias)
                if alias == norm or (len(alias) >= 4 and (norm.startswith(alias) or norm.endswith(alias))):
                    found.add(canonical)

    # Known service/SMS aliases allow labels such as "WhatsApp VIP" or
    # "𝗪𝗵𝗮𝘁𝘀𝗔𝗽𝗽 Premium" to resolve without depending on typography/emoji.
    for canonical, aliases in SERVICE_SMS_KEYWORDS.items():
        for raw_alias in sorted({canonical, *(str(x) for x in aliases)}, key=lambda x: len(_normalize_label(x)), reverse=True):
            alias = _normalize_label(raw_alias)
            if not alias:
                continue
            if alias == norm or re.search(rf"(?<![a-z0-9]){re.escape(alias)}(?![a-z0-9])", norm):
                found.add(canonical)
                break
            if len(alias) >= 4 and (norm.startswith(alias) or norm.endswith(alias)):
                found.add(canonical)
                break
    return found


def _service_match_for_range(api_service, configured_service):
    """Match provider/configured services across emojis, HTML and display fonts."""
    a = _normalize_label(api_service)
    c = _normalize_label(configured_service)
    if a and c and a == c:
        return True
    if not a or not c:
        return False

    # The configured service label is allowed to decorate the known service name
    # with arbitrary words, emoji or typography. Match only through known aliases,
    # never by unconstrained fuzzy similarity.
    a_known = _service_match_alias_keys(api_service)
    c_known = _service_match_alias_keys(configured_service)
    shared = a_known & c_known
    if shared:
        # FB Forgot is a protected identity. The clone token may only match
        # another clone token; it can never fall back to normal Facebook.
        if "fb forgot" in (a_known | c_known):
            return "fb forgot" in a_known and "fb forgot" in c_known
        return True

    # Premium-App records can explicitly bridge a provider label and configured
    # label that have no raw string equality.
    apps = bot_settings.get("premium_apps", {}) or {}
    if isinstance(apps, dict):
        for key, data in apps.items():
            if not isinstance(data, dict):
                continue
            aliases = {
                _normalize_label(str(key)),
                _normalize_label(str(data.get("name", ""))),
                _normalize_label(str(data.get("service", ""))),
            }
            aliases.discard("")
            if not aliases:
                continue
            a_hit = any(x == a or (len(x) >= 4 and (a.startswith(x) or a.endswith(x))) for x in aliases)
            c_hit = any(x == c or (len(x) >= 4 and (c.startswith(x) or c.endswith(x))) for x in aliases)
            if a_hit and c_hit:
                return True
    return False


def _country_code_owner_names(code):
    """Return unique full-country owners for a calling code in the built-in directory."""
    code = str(code or "").strip()
    if not code or not code.isdigit():
        return set()
    owners = set()
    for key, entry in _COUNTRY_DIRECTORY_CACHE.items():
        codes = {str(x) for x in (entry.get("codes", set()) or set())}
        if code not in codes:
            continue
        # ISO/alpha-2 directory aliases are not separate countries.
        if re.fullmatch(r"[A-Za-z]{2}", key):
            continue
        owners.add(key)
    return owners


def _country_full_name_for_alias(norm):
    """Resolve a 2-letter/static country alias to its paired full name when possible."""
    norm = _normalize_label(norm)
    if not norm or not re.fullmatch(r"[a-z]{2}", norm):
        return ""
    items = list((ZENEX_COUNTRY_CALLING_CODES or {}).items())
    for idx, (key, values) in enumerate(items):
        if _normalize_label(key) != norm:
            continue
        codes = {str(x) for x in (values or [])}
        # The bundled directory stores common full-name/ISO pairs consecutively.
        for j in (idx - 1, idx + 1, idx - 2, idx + 2):
            if 0 <= j < len(items):
                other, other_values = items[j]
                if _normalize_label(other) == norm:
                    continue
                if codes & {str(x) for x in (other_values or [])} and len(_normalize_label(other)) > 2:
                    return str(other).strip()
        # Fallback: when the code owner is unique, use it.
        owners = _country_code_owner_names(next(iter(codes), "")) if codes else set()
        if len(owners) == 1:
            return next(iter(owners))
    return ""


def _country_identity_aliases(label):
    """Return safe aliases for a country label without cross-wiring shared calling codes."""
    raw = str(label or "").strip()
    norm = _normalize_label(raw)
    aliases = {norm} if norm else set()
    codes = set(_country_codes_for_label(raw)) if raw else set()

    common = COMMON_COUNTRY_BROADCAST_ALIASES.get(norm)
    if common:
        aliases.add(_normalize_label(common))

    # Match a premium flag only when the text label itself identifies that entry,
    # or when a numeric code uniquely belongs to one full country. This prevents
    # the US flag entry for code 1 from incorrectly matching Canada/other NANP regions.
    for code, fdata in (bot_settings.get("premium_flags", {}) or {}).items():
        flag_aliases = {
            _normalize_label(str(code)),
            _normalize_label(str(fdata.get("iso", ""))),
            _normalize_label(str(fdata.get("name", ""))),
        }
        if norm and norm in flag_aliases and (not norm.isdigit() or len(_country_code_owner_names(norm)) == 1):
            aliases.update(x for x in flag_aliases if x)
            break

    # Resolve standard directory aliases (full name and ISO) to their unique
    # country owner when the calling code is not shared.
    for key, entry in _COUNTRY_DIRECTORY_CACHE.items():
        if norm and norm == key:
            aliases.add(key)
            entry_codes = {str(x) for x in (entry.get("codes", set()) or set())}
            codes.update(entry_codes)
            paired = _country_full_name_for_alias(norm)
            if paired:
                aliases.add(_normalize_label(paired))
            for code in entry_codes:
                owners = _country_code_owner_names(code)
                if len(owners) == 1:
                    aliases.update(owners)
            break

    # A bare numeric calling code identifies a country only when it is unique.
    if norm.isdigit():
        for code in codes or {norm}:
            owners = _country_code_owner_names(code)
            if len(owners) == 1:
                aliases.update(owners)

    return aliases, {str(x) for x in codes if str(x).isdigit()}


def _country_labels_match(requested, stored):
    """Match two country labels while keeping shared calling codes unambiguous."""
    req_aliases, req_codes = _country_identity_aliases(requested)
    st_aliases, st_codes = _country_identity_aliases(stored)
    if req_aliases & st_aliases:
        return True

    # A numeric label can safely stand for a country only when its calling code is
    # unique in our country directory. This deliberately refuses +1-style sharing.
    if req_codes & st_codes:
        for code in sorted(req_codes & st_codes, key=lambda x: (-len(x), x)):
            owners = set()
            for key, entry in _COUNTRY_DIRECTORY_CACHE.items():
                if code in {str(x) for x in (entry.get("codes", set()) or set())}:
                    owners.add(key)
            if len(owners) == 1:
                return True
    return False


def _number_matches_prefix(number, prefix):
    nd = _normalize_number_key(number)
    pd = re.sub(r"\D", "", str(prefix or ""))
    return bool(nd and pd and nd.startswith(pd))


def _parse_service_country_callback(data, prefix):
    """Parse service/country callback payload without breaking underscore-containing names."""
    raw = str(data or "")
    if not raw.startswith(prefix):
        return "", ""
    payload = raw[len(prefix):]
    if "_" not in payload:
        return payload.strip(), ""

    candidates = set()
    for b in (number_batches or {}).values():
        if isinstance(b, dict):
            v = str(b.get("service", "") or "").strip()
            if v:
                candidates.add(v)
    for key in ("stex_services", "voltx_services", "zenex_services"):
        for v in (bot_settings.get(key, {}) or {}).keys():
            v = str(v or "").strip()
            if v:
                candidates.add(v)

    # Longest-first prevents a short service name from stealing a longer one.
    for service in sorted(candidates, key=lambda x: len(x), reverse=True):
        if payload.startswith(service + "_"):
            return service.strip(), payload[len(service) + 1:].strip()

    service, country = payload.split("_", 1)
    return service.strip(), country.strip()


def _service_labels_match(requested, stored):
    """Match manual stock services using exact normalized names plus known app aliases."""
    req = _normalize_label(requested)
    st = _normalize_label(stored)
    if req and req == st:
        return True
    if not req or not st:
        return False
    apps = bot_settings.get("premium_apps", {}) or {}
    for key, data in apps.items():
        aliases = {_normalize_label(key), _normalize_label(data.get("name", ""))}
        if req in aliases and st in aliases:
            return True
    for base, variants in (SERVICE_SMS_KEYWORDS or {}).items():
        vals = {_normalize_label(base)} | {_normalize_label(x) for x in (variants or [])}
        if req in vals and st in vals:
            return True
    return False


def _manual_lease_index_add(lease_key, number):
    norm = _normalize_number_key(number)
    if norm:
        manual_number_lease_index.setdefault(norm, set()).add(str(lease_key))


def _manual_lease_index_remove(lease_key, number=None):
    norm = _normalize_number_key(number) if number else str(lease_key or "").split(":", 1)[0].strip()
    keys = manual_number_lease_index.get(norm)
    if not keys:
        return
    keys.discard(str(lease_key))
    if not keys:
        manual_number_lease_index.pop(norm, None)


def _manual_number_has_active_lease(number, now=None):
    norm = _normalize_number_key(number)
    if not norm:
        return False
    now = float(time.time() if now is None else now)
    with manual_number_leases_lock:
        for key in list(manual_number_lease_index.get(norm, set())):
            lease = manual_number_leases.get(key)
            if not isinstance(lease, dict):
                _manual_lease_index_remove(key, norm)
                continue
            try:
                if now < float(lease.get("expires_at", 0.0) or 0.0):
                    return True
            except Exception:
                pass
            manual_number_leases.pop(key, None)
            _manual_lease_index_remove(key, norm)
    return False


def _manual_try_claim_number(chat_id, panel_id, panel_name, service, country, number, source_batch_id, now=None):
    """Atomically reserve a manual number for its 20-minute OTP window."""
    now = float(time.time() if now is None else now)
    norm = _normalize_number_key(number)
    if not norm:
        return False
    key = f"{norm}:{int(chat_id)}"
    with manual_number_leases_lock:
        for other_key in list(manual_number_lease_index.get(norm, set())):
            lease = manual_number_leases.get(other_key)
            if not isinstance(lease, dict):
                _manual_lease_index_remove(other_key, norm)
                continue
            try:
                active = now < float(lease.get("expires_at", 0.0) or 0.0)
            except Exception:
                active = False
            if active:
                return False
            manual_number_leases.pop(other_key, None)
            _manual_lease_index_remove(other_key, norm)
        lease = {
            "number": str(number), "owner_id": int(chat_id), "panel_id": str(panel_id),
            "panel_name": str(panel_name), "service": str(service), "country": str(country),
            "started_at": now, "expires_at": now + MANUAL_LEASE_SECONDS,
        }
        if str(source_batch_id or "").strip():
            lease["source_batch_id"] = str(source_batch_id).strip()
        manual_number_leases[key] = lease
        _manual_lease_index_add(key, norm)
    return True


def _manual_stock_candidates(service, country, chat_id, prefix=None):
    """Return safe local-stock candidates for Get Number."""
    result = []
    target_service = str(service or "").strip()
    target_country = str(country or "").strip()
    for b_id, batch in (number_batches or {}).items():
        if not isinstance(batch, dict):
            continue
        if str(batch.get("source_type", "MANUAL")).upper() not in ("MANUAL", ""):
            continue
        if not _service_labels_match(target_service, batch.get("service", "")):
            continue
        batch_country = str(batch.get("country", "")).strip()
        if not _country_labels_match(target_country, batch_country):
            continue
        for idx, obj in enumerate(batch.get("numbers") or []):
            if not isinstance(obj, dict):
                continue
            num = str(obj.get("num", "")).strip()
            if not num:
                continue
            used = obj.get("used_by", []) or []
            used_norm = {str(x) for x in used}
            if str(chat_id) in used_norm:
                continue
            if _manual_number_has_active_lease(num):
                continue
            if prefix and not _number_matches_prefix(num, prefix):
                continue
            result.append((b_id, idx))
    return result


def _configured_provider_ranges(service, country, provider):
    """Find configured provider ranges across normalized service/country aliases."""
    p = str(provider or "").strip().upper()
    key = {"STEX": "stex_services", "VOLTX": "voltx_services", "ZENEX": "zenex_services"}.get(p)
    if not key:
        return []
    source = bot_settings.get(key, {}) or {}
    for srv, countries in source.items():
        if not _service_labels_match(service, srv) or not isinstance(countries, dict):
            continue
        for cnt, ranges in countries.items():
            if _country_labels_match(country, cnt):
                if isinstance(ranges, list):
                    return [str(x).strip() for x in ranges if str(x).strip()]
                if ranges:
                    return [str(ranges).strip()]
    return []

def get_reward_rate(provider, service, country, fallback=0.0):
    p=_rate_provider(provider); s=_normalize_label(str(service or "")).upper(); c=(_country_short_name(str(country or "")) or str(country or "")).strip().upper()
    sm=((bot_settings.get("reward_rates",{}) or {}).get(p,{}) or {}).get(s,{})
    if isinstance(sm,dict):
        for k,v in sm.items():
            if ((_country_short_name(str(k)) or str(k)).strip().upper())==c:
                try: return float(v)
                except Exception: pass
    try: return float(fallback or 0.0)
    except Exception: return 0.0

def set_reward_rate(provider, service, country, rate):
    rate=float(rate)
    if rate<0: raise ValueError("rate")
    p=_rate_provider(provider); s=_normalize_label(str(service or "")).upper(); c=(_country_short_name(str(country or "")) or str(country or "")).strip().upper()
    bot_settings.setdefault("reward_rates",{}).setdefault(p,{}).setdefault(s,{})[c]=rate
    save_db()
    return p,s,c,rate

@lru_cache(maxsize=8192)
def _normalize_number_key(number):
    """Normalize phone numbers for stable rate/owner matching across +, spaces, dashes, etc."""
    return re.sub(r"\D", "", str(number or "").strip())


def _manual_numbers_match(left, right):
    """Match panel numbers despite +, country-code and formatting differences."""
    a = _normalize_number_key(left)
    b = _normalize_number_key(right)
    if not a or not b:
        return False
    if a == b:
        return True
    # CDRs sometimes include an international prefix while uploaded stock is
    # stored in national format. Require a long suffix to avoid false matches.
    return (len(a) >= 8 and len(b) >= 8 and (a.endswith(b[-10:]) or b.endswith(a[-10:])))

def _cleanup_recent_otp_rewarded_numbers(now=None, persist=False):
    """Expire exact phone-number OTP dedupe entries after 20 minutes.

    Only numbers for which an OTP reward was actually processed are stored here.
    Expired entries are removed from the local persistent snapshot so the file does
    not grow forever.
    """
    now=float(time.time() if now is None else now)
    removed=False
    with LEDGER_LOCK:
        for key, ts in list(recent_otp_rewarded_numbers.items()):
            try:
                expired=(now-float(ts)) >= OTP_NUMBER_DEDUPE_TTL
            except Exception:
                expired=True
            if expired:
                recent_otp_rewarded_numbers.pop(key, None)
                removed=True
    if removed and persist:
        save_db_sync()
    return removed

def _manual_number_metadata_lookup(number):
    """Return durable metadata for a manually uploaded full number.

    Manual numbers carry their configured provider/service/country independently
    from the incoming SMS text. This keeps the configured service authoritative
    even when a panel/API message has no recognizable service keyword.
    """
    raw = str(number or "").strip()
    if not raw:
        return None
    norm = _normalize_number_key(raw)
    for key in (raw, raw.replace("+", ""), norm):
        if key and key in manual_number_metadata:
            data = manual_number_metadata.get(key)
            if isinstance(data, dict) and str(data.get("service", "")).strip():
                return dict(data)
    # Last-resort reconstruction from manual batch records.
    for batch in number_batches.values():
        if not isinstance(batch, dict) or str(batch.get("source_type", "MANUAL")).upper() != "MANUAL":
            continue
        for item in (batch.get("numbers") or []):
            if not isinstance(item, dict):
                continue
            item_num = str(item.get("num", "")).strip()
            if item_num and _normalize_number_key(item_num) == norm:
                return {
                    "provider": str(batch.get("provider") or "MANUAL"),
                    "service": str(batch.get("service") or ""),
                    "country": str(batch.get("country") or ""),
                    "rate": float(batch.get("rate", 0.0) or 0.0),
                }
    return None


def _remember_assigned_number_route(number, owner_id, provider, service, country, number_range=""):
    key = _normalize_number_key(number)
    if not key or not owner_id:
        return False
    assigned_number_routes[key] = {
        "owner_id": int(owner_id),
        "provider": str(provider or "").strip().upper(),
        "service": str(service or "").strip(),
        "country": str(country or "").strip(),
        "range": str(number_range or "").strip(),
        "assigned_at": time.time(),
    }
    return True

def _assigned_number_route(number, provider=None):
    key = _normalize_number_key(number)
    route = assigned_number_routes.get(key) if key else None
    if not isinstance(route, dict):
        return None
    try:
        if (time.time() - float(route.get("assigned_at", 0.0) or 0.0)) >= ASSIGNED_ROUTE_TTL:
            assigned_number_routes.pop(key, None)
            return None
    except Exception:
        pass
    wanted = str(provider or "").strip().upper()
    actual = str(route.get("provider", "") or "").strip().upper()
    if wanted and actual and wanted != actual:
        return None
    return dict(route)

def _cleanup_assigned_number_routes(now=None, persist=False):
    now = float(time.time() if now is None else now)
    removed = False
    for key, route in list(assigned_number_routes.items()):
        try:
            ts = float(route.get("assigned_at", 0.0) or 0.0)
        except Exception:
            ts = 0.0
        if not ts or now - ts >= ASSIGNED_ROUTE_TTL:
            assigned_number_routes.pop(key, None)
            removed = True
    if removed and persist:
        save_db_sync()
    return removed

def _manual_panel_owner_ids(number):
    """Resolve a manually assigned number owner from durable local state."""
    raw = str(number or "").strip()
    if not raw:
        return []
    norm = _normalize_number_key(raw)
    for key in (raw, raw.replace("+", ""), norm):
        try:
            uid = manual_number_owners.get(key)
            if uid is not None:
                return [int(uid)]
        except Exception:
            pass
    # Recovery path for older local DBs that predate manual_number_owners.
    clean = raw.replace("+", "").replace(" ", "").replace("-", "").strip()
    for uid, session_data in user_active_sessions.items():
        for act_num in session_data.get("nums", []):
            act_clean = str(act_num).replace("+", "").replace(" ", "").replace("-", "").strip()
            if act_clean == clean or (len(act_clean) >= 8 and act_clean.endswith(clean[-8:])) or (len(clean) >= 8 and clean.endswith(act_clean[-8:])):
                return [int(uid)]
    return []


def _manual_number_rate(number, owner_id=None):
    """Resolve a manual-upload rate directly from durable batch data as a safety net.

    This is intentionally checked at OTP-credit time so a manual upload rate is
    never lost just because a runtime assignment map was missed, reformatted,
    or rebuilt after a restart.
    """
    raw = str(number or "").strip()
    norm = _normalize_number_key(raw)

    # Primary path: durable manual-upload rate keyed by the complete number.
    for key in (raw, raw.replace("+", ""), norm):
        if key and key in manual_number_reward_rates:
            try:
                return float(manual_number_reward_rates[key])
            except Exception:
                pass

    # Fast path: the per-assignment durable map.
    for key in (raw, raw.replace("+", ""), norm):
        if key and key in assigned_number_rates:
            try:
                return float(assigned_number_rates[key])
            except Exception:
                pass

    # Durable source of truth: the original MANUAL upload batch.
    for batch in number_batches.values():
        if not isinstance(batch, dict) or str(batch.get("source_type", "MANUAL")).upper() != "MANUAL":
            continue
        batch_rate = batch.get("rate", None)
        if batch_rate is None:
            continue
        for item in (batch.get("numbers") or []):
            if not isinstance(item, dict):
                continue
            item_num = item.get("num", "")
            if _normalize_number_key(item_num) != norm:
                continue
            if owner_id is not None:
                used_by = item.get("used_by") or []
                try:
                    if int(owner_id) not in {int(x) for x in used_by}:
                        continue
                except Exception:
                    if str(owner_id) not in {str(x) for x in used_by}:
                        continue
            try:
                rate = float(batch_rate)
                # Cache the normalized lookup for subsequent OTPs on the same number.
                assigned_number_rates[norm] = rate
                assigned_number_rates[raw] = rate
                return rate
            except Exception:
                return None
    return None

def credit_otp_reward(user_id, provider, service, country, number, fallback=0.0, event_key=""):
    """Credit a reward exactly once per distinct OTP event.

    The provider event identifier (for example ZenEX ``nid`` or a provider OTP id)
    is the primary idempotency key. This deliberately does *not* suppress a new OTP
    merely because it arrived on the same full phone number, so resend/new-code events
    can each earn their configured reward.
    """
    global credited_otp_events
    raw_num = str(number or "").strip()

    # Keep the legacy exact-number cleanup for backward-compatible local state hygiene,
    # but do not use the phone number as the reward eligibility key anymore.
    _cleanup_recent_otp_rewarded_numbers()

    # Manual upload rates always win over provider/country fallback rates.
    assigned = _manual_number_rate(raw_num, owner_id=user_id)
    reward = float(assigned) if assigned is not None else get_reward_rate(provider, service, country, fallback)
    try:
        reward = float(reward)
    except Exception:
        reward = 0.0
    if reward < 0:
        reward = 0.0

    # Idempotency is event-based: the same provider event cannot be credited twice,
    # while a different OTP event for the same number is eligible for its own reward.
    # Every current OTP ingestion path supplies a stable event_key.
    effective_event_key = str(event_key or "").strip()
    if not effective_event_key:
        # Legacy callers without an event id get a unique local key rather than a
        # number-based block; this preserves the requested "every OTP receives reward"
        # semantics while all modern provider paths remain exactly-once.
        effective_event_key = f"LEGACY:{provider}:{raw_num}:{uuid.uuid4().hex}"

    with LEDGER_LOCK:
        if effective_event_key in credited_otp_events:
            return 0.0
        credited_otp_events.add(effective_event_key)
        # Bound memory without touching the durable local OTP ledger semantics.
        if len(credited_otp_events) > 50000:
            credited_otp_events = set(list(credited_otp_events)[-40000:])

    # Balance mutation is persisted before the caller continues, so a crash cannot
    # acknowledge the OTP without saving the reward/OTP ledger state.
    if not _local_user_mutation(user_id, reward, 1):
        with LEDGER_LOCK:
            credited_otp_events.discard(effective_event_key)
        return 0.0

    # Only the aggregate OTP counter is retained for Firebase sync. Detailed OTP payloads are not stored remotely.
    save_db_sync()
    return reward

def _run_user_sync_transaction(ref, sync_id, balance_delta, otp_count, profile_fields=None):
    """Atomically apply one pending user ledger batch with an idempotency marker.

    Must be invoked through Firestore's transactional runner. This avoids relying
    on Transaction.get() iteration semantics and guarantees the read/write occurs
    inside an active transaction.
    """
    try:
        transactional = getattr(firestore, "transactional", None)
    except Exception:
        transactional = None
    if not callable(transactional):
        raise RuntimeError("Firestore transactional runner is unavailable")

    @transactional
    def _tx(transaction):
        snap = ref.get(transaction=transaction)
        raw = snap.to_dict() if getattr(snap, "exists", False) else {}
        if str(raw.get("last_local_sync_id", "") or "") == str(sync_id):
            return True
        payload = {"user_id": int(ref.id), "last_local_sync_id": str(sync_id)}
        for _k, _v in (profile_fields or {}).items():
            if _k in USER_REMOTE_FIELDS and _k not in {"balance", "total_otps", "last_local_sync_id"}:
                payload[_k] = _v
        if balance_delta:
            payload["balance"] = firestore.Increment(float(balance_delta))
        if otp_count:
            payload["total_otps"] = firestore.Increment(int(otp_count))
        transaction.set(ref, payload, merge=True)
        return True

    # The transactional decorator owns begin/retry/commit lifecycle.
    return bool(_tx(db.transaction()))


def _sync_local_user_ledger(force=False):
    """Hourly local-first Firebase sync: only user balance, OTP count and user details."""
    if not db:
        return False
    now = time.time()
    successful = []
    any_failed = False
    with LEDGER_LOCK, USER_CACHE_LOCK:
        candidate_uids = set(pending_user_balance_deltas) | set(pending_user_otp_counts) | set(pending_user_profile_updates)
        for uid in candidate_uids:
            if not force:
                if float(user_sync_retry_after.get(uid, 0.0) or 0.0) > now:
                    continue
                last_activity = float(last_user_ledger_activity_at.get(uid, 0.0) or 0.0)
                if last_activity and (now - last_activity) < BALANCE_SYNC_IDLE_SECONDS:
                    continue
                pending_created = float(
                    (pending_user_sync_batches.get(uid) or {}).get("created_at", 0.0) or 0.0
                )
                pending_touch = max(last_activity, pending_created)
                if pending_touch and (now - pending_touch) < BALANCE_SYNC_IDLE_SECONDS:
                    continue
            if uid not in pending_user_sync_batches:
                pending_user_sync_batches[int(uid)] = {
                    "sync_id": uuid.uuid4().hex,
                    "user_id": int(uid),
                    "balance_delta": float(pending_user_balance_deltas.pop(uid, 0.0) or 0.0),
                    "otp_count": int(pending_user_otp_counts.pop(uid, 0) or 0),
                    "profile": dict(pending_user_profile_updates.pop(uid, {}) or {}),
                    "created_at": now,
                }
        if pending_user_sync_batches:
            save_db_sync()
    if not pending_user_sync_batches:
        return True
    with LEDGER_LOCK:
        batches_snapshot = {uid: dict(batch) for uid, batch in pending_user_sync_batches.items()}
    for uid, batch in batches_snapshot.items():
        try:
            ref = db.collection("users").document(str(uid))
            _run_user_sync_transaction(ref, str(batch["sync_id"]),
                                        float(batch.get("balance_delta", 0.0) or 0.0),
                                        int(batch.get("otp_count", 0) or 0),
                                        dict(batch.get("profile", {}) or {}))
            with LEDGER_LOCK:
                user_sync_retry_after.pop(uid, None)
            successful.append(uid)
        except Exception as exc:
            any_failed = True
            with LEDGER_LOCK:
                user_sync_retry_after[int(uid)] = time.time() + 3600
            _terminal_log(f"[LEDGER] hourly Firebase sync failed uid={uid}; retry scheduled: {exc}")
    with LEDGER_LOCK, USER_CACHE_LOCK:
        for uid in successful:
            pending_user_sync_batches.pop(uid, None)
            # Detailed OTP payloads never go to Firebase; discard their local queue once the aggregate counter is synced.
            pending_otp_records[:] = [r for r in pending_otp_records if int(r.get("user_id", -1)) != int(uid)]
        save_db_sync()
    return bool(successful) and not any_failed

def _balance_sync_worker():
    """Hourly Firebase flush. All configuration/traffic/range data remains local-only."""
    global last_firebase_user_sync_at
    next_flush = time.monotonic()
    while not LOCAL_STOP.is_set():
        try:
            _cleanup_recent_otp_rewarded_numbers(persist=True)
            if time.monotonic() >= next_flush:
                synced = _sync_local_user_ledger(False)
                if synced:
                    last_firebase_user_sync_at = time.time()
                    save_db_sync()
                next_flush = time.monotonic() + FIREBASE_USER_SYNC_CHECK_INTERVAL
        except Exception as exc:
            _terminal_log(f"[LEDGER] worker error: {exc}")
            next_flush = time.monotonic() + 60
        LOCAL_STOP.wait(FIREBASE_USER_SYNC_CHECK_INTERVAL)

def _force_sync_user_ledger(user_id):
    """Flush one user's pending 30-minute ledger immediately before withdrawal.

    Withdrawal is a strong-consistency boundary: all locally pending OTP/referral/admin
    balance mutations for this user are pushed to Firebase first, then Firebase is read
    again as the authoritative source. Withdrawal reservations are deliberately excluded.
    """
    uid = int(user_id)
    if not db:
        return False
    now = time.time()
    batch = None
    with LEDGER_LOCK, USER_CACHE_LOCK:
        if uid not in pending_user_sync_batches:
            delta = float(pending_user_balance_deltas.pop(uid, 0.0) or 0.0)
            otp_count = int(pending_user_otp_counts.pop(uid, 0) or 0)
            profile = dict(pending_user_profile_updates.pop(uid, {}) or {})
            records = [r for r in pending_otp_records if int(r.get("user_id", -1)) == uid]
            if delta or otp_count or profile or records:
                pending_user_sync_batches[uid] = {
                    "sync_id": uuid.uuid4().hex,
                    "user_id": uid,
                    "balance_delta": delta,
                    "otp_count": otp_count,
                    "profile": profile,
                    "records": records,
                    "created_at": now,
                }
        batch = dict(pending_user_sync_batches.get(uid) or {})
        if batch:
            save_db_sync()

    if batch:
        try:
            ref = db.collection("users").document(str(uid))
            _run_user_sync_transaction(
                ref, str(batch["sync_id"]),
                float(batch.get("balance_delta", 0.0) or 0.0),
                int(batch.get("otp_count", 0) or 0),
                dict(batch.get("profile", {}) or {}),
            )
            with LEDGER_LOCK, USER_CACHE_LOCK:
                pending_user_sync_batches.pop(uid, None)
                user_sync_retry_after.pop(uid, None)
                pending_otp_records[:] = [r for r in pending_otp_records if int(r.get("user_id", -1)) != uid]
                save_db_sync()
        except Exception as exc:
            _terminal_log(f"[WITHDRAWAL] pre-withdraw Firebase sync failed uid={uid}: {exc}")
            with LEDGER_LOCK:
                # If promotion happened, it stays durable for the normal 30-minute retry.
                user_sync_retry_after[uid] = time.time() + BALANCE_SYNC_IDLE_SECONDS
            save_db_sync()
            return False

    # Fresh authoritative Firebase read after sync.
    try:
        snap = db.collection("users").document(str(uid)).get()
        if not getattr(snap, "exists", False):
            return False
        raw = snap.to_dict() or {}
        remote = _sanitize_user_record(raw, uid)
        with USER_CACHE_LOCK:
            # Any new local mutations created while the remote read was happening remain effective.
            extra_delta, extra_otp = _local_unsynced_for_user(uid, str(raw.get("last_local_sync_id", "") or ""))
            remote["balance"] += extra_delta
            remote["balance"] -= float(pending_user_withdrawal_reservations.get(uid, 0.0) or 0.0)
            remote["total_otps"] += extra_otp
            user_cache[uid] = remote
        return True
    except Exception as exc:
        _terminal_log(f"[WITHDRAWAL] authoritative Firebase read failed uid={uid}: {exc}")
        return False


def _refresh_withdrawal_balance(user_id):
    """Return the effective balance after an immediate Firebase reconciliation."""
    uid = int(user_id)
    def local_fallback():
        # Keep the Withdrawal button usable during a transient Firebase outage.
        # Pending local OTP/referral mutations are already reflected in the local
        # user snapshot; the reservation is always subtracted before display.
        try:
            local = get_user(uid) or {}
            return max(0.0, float(local.get("balance", 0.0) or 0.0) - float(
                pending_user_withdrawal_reservations.get(uid, 0.0) or 0.0
            ))
        except Exception:
            return None
    if not _force_sync_user_ledger(uid):
        return local_fallback()
    try:
        snap = db.collection("users").document(str(uid)).get()
        if not getattr(snap, "exists", False):
            return None
        raw = snap.to_dict() or {}
        remote = _sanitize_user_record(raw, uid)
        with USER_CACHE_LOCK:
            pending_delta, pending_otp = _local_unsynced_for_user(uid, str(raw.get("last_local_sync_id", "") or ""))
            # The reservation is local-only until ACCEPT.
            effective = float(remote.get("balance", 0.0) or 0.0) + pending_delta - float(pending_user_withdrawal_reservations.get(uid, 0.0) or 0.0)
            remote["balance"] = effective
            remote["total_otps"] = int(remote.get("total_otps", 0) or 0) + pending_otp
            user_cache[uid] = remote
            return effective
    except Exception as exc:
        _terminal_log(f"[WITHDRAWAL] balance refresh failed uid={uid}: {exc}")
        return local_fallback()


def _reserve_withdrawal_locally(user_id, amount):
    uid = int(user_id); amount = float(amount)
    if amount <= 0:
        return False
    with LEDGER_LOCK, USER_CACHE_LOCK:
        current = user_cache.get(uid)
        if current is None:
            return False
        available = float(current.get("balance", 0.0) or 0.0)
        if available + 1e-9 < amount:
            return False
        pending_user_withdrawal_reservations[uid] = float(pending_user_withdrawal_reservations.get(uid, 0.0) or 0.0) + amount
        current["balance"] = available - amount
    return save_db_sync()


def _release_withdrawal_reservation(user_id, amount, restore_local=True):
    uid = int(user_id); amount = float(amount)
    with LEDGER_LOCK, USER_CACHE_LOCK:
        old = float(pending_user_withdrawal_reservations.get(uid, 0.0) or 0.0)
        new = max(0.0, old - amount)
        if new > 1e-9:
            pending_user_withdrawal_reservations[uid] = new
        else:
            pending_user_withdrawal_reservations.pop(uid, None)
        if restore_local:
            if uid not in user_cache:
                user_cache[uid] = get_user(uid)
            user_cache[uid]["balance"] = float(user_cache[uid].get("balance", 0.0) or 0.0) + amount
    return save_db_sync()


def _firestore_withdrawal_accept(req_id, user_id, amount, admin_id):
    """Atomically debit Firebase on ACCEPT and mark the request awaiting TX ID."""
    if not db:
        return False, "Firebase unavailable"
    uid = int(user_id); amount = float(amount); req_id = str(req_id)
    transactional = getattr(firestore, "transactional", None)
    if not callable(transactional):
        return False, "Firestore transaction unavailable"
    try:
        @transactional
        def _tx(transaction):
            uref = db.collection("users").document(str(uid))
            wref = db.collection("withdrawals").document(req_id)
            usnap = uref.get(transaction=transaction)
            wsnap = wref.get(transaction=transaction)
            wraw = wsnap.to_dict() if getattr(wsnap, "exists", False) else {}
            status = str(wraw.get("status", "pending") or "pending")
            if status != "pending":
                raise RuntimeError(f"withdrawal status is {status}")
            uraw = usnap.to_dict() if getattr(usnap, "exists", False) else {}
            balance = float(uraw.get("balance", 0.0) or 0.0)
            if balance + 1e-9 < amount:
                raise RuntimeError(f"Firebase balance insufficient: {balance:g}")
            transaction.set(uref, {"user_id": uid, "balance": firestore.Increment(-amount)}, merge=True)
            transaction.set(wref, {
                "status": "awaiting_txid",
                "firebase_debited": True,
                "approval_admin_id": str(admin_id),
                "accepted_at": firestore.SERVER_TIMESTAMP,
            }, merge=True)
            return True
        _tx(db.transaction())
        return True, "ok"
    except Exception as exc:
        return False, str(exc)


def _firestore_withdrawal_refund(req_id, user_id, amount, final_status, admin_id):
    """Atomically refund Firebase exactly once for an accepted withdrawal cancellation."""
    if not db:
        return False, "Firebase unavailable"
    uid = int(user_id); amount = float(amount); req_id = str(req_id)
    transactional = getattr(firestore, "transactional", None)
    if not callable(transactional):
        return False, "Firestore transaction unavailable"
    try:
        @transactional
        def _tx(transaction):
            uref = db.collection("users").document(str(uid))
            wref = db.collection("withdrawals").document(req_id)
            wsnap = wref.get(transaction=transaction)
            wraw = wsnap.to_dict() if getattr(wsnap, "exists", False) else {}
            status = str(wraw.get("status", "") or "")
            if status == final_status:
                return True
            if status != "awaiting_txid" or not bool(wraw.get("firebase_debited", False)):
                raise RuntimeError(f"withdrawal is not refundable: {status}")
            transaction.set(uref, {"user_id": uid, "balance": firestore.Increment(amount)}, merge=True)
            transaction.set(wref, {
                "status": final_status,
                "firebase_debited": False,
                "processed_by": str(admin_id),
                "refunded_at": firestore.SERVER_TIMESTAMP,
            }, merge=True)
            return True
        _tx(db.transaction())
        return True, "ok"
    except Exception as exc:
        return False, str(exc)


def _firestore_withdrawal_reject_pending(req_id, admin_id):
    if not db:
        return False, "Firebase unavailable"
    try:
        doc = db.collection("withdrawals").document(str(req_id))
        transactional = getattr(firestore, "transactional", None)
        if not callable(transactional):
            return False, "Firestore transaction unavailable"
        @transactional
        def _tx(transaction):
            snap = doc.get(transaction=transaction)
            raw = snap.to_dict() if getattr(snap, "exists", False) else {}
            status = str(raw.get("status", "") or "")
            if status == "rejected":
                return True
            if status != "pending" or bool(raw.get("firebase_debited", False)):
                raise RuntimeError(f"withdrawal is not pending: {status}")
            transaction.set(doc, {"status": "rejected", "processed_by": str(admin_id)}, merge=True)
            return True
        _tx(db.transaction())
        return True, "ok"
    except Exception as exc:
        return False, str(exc)

def update_balance(user_id, amount):
    return _local_user_mutation(user_id,float(amount),0)

def _local_increment_user_field(user_id, field, delta=1):
    uid = int(user_id)
    user = get_user(uid)
    current = int(user.get(field, 0) or 0) if field != "balance" else float(user.get(field, 0.0) or 0.0)
    new_value = current + (float(delta) if field == "balance" else int(delta))
    update_user_fields(uid, **{field: new_value})
    return new_value

def add_referral(inviter_id, new_user_id):
    inviter_id = int(inviter_id)
    new_user_id = int(new_user_id)
    try:
        new_user = get_user(new_user_id)
        if new_user.get("referred_by") or new_user.get("ref_paid"):
            return
        update_user_fields(new_user_id, referred_by=inviter_id, ref_paid=False)
        reward = float(bot_settings.get("refer_reward", 0.2) or 0.0)
        if reward > 0 and update_balance(inviter_id, reward):
            _local_increment_user_field(inviter_id, "total_refers", 1)
            ref_msg = (
                f"{PEM['gift']} <b>New Referral !</b>\n"
                f"------------------\n"
                f"🔥 <b>You Received {reward:g} TK</b>\n"
                f"------------------\n"
                f"{PEM['user']} <b>From User ID:</b> <code>{new_user_id}</code>"
            )
            send_message(inviter_id, render_body_text(ref_msg))
    except Exception as exc:
        _terminal_log(f"[Referral] failed inviter={inviter_id} new={new_user_id}: {exc}")

def get_cancel_kb():
    return {"inline_keyboard": [[{"text": "Cancel", "icon_custom_emoji_id": "5267490665117275176", "callback_data": "cancel_state", "style": "danger"}]]}

def frd_button_target_url():
    raw = str(bot_settings.get("frd_button_username", "") or "").strip()
    if not raw:
        return ""
    raw = raw.replace("https://", "").replace("http://", "")
    raw = raw.replace("t.me/", "").replace("telegram.me/", "")
    raw = raw.lstrip("@").split("?", 1)[0].split("/", 1)[0].strip()
    if not re.fullmatch(r"[A-Za-z0-9_]{5,64}", raw):
        return ""
    return f"https://t.me/{raw}"

