def _manual_provider_name(batch):
    if not isinstance(batch, dict):
        return ""
    if str(batch.get("source_type", "MANUAL")).upper() != "MANUAL":
        return ""
    return str(batch.get("provider") or "MANUAL").strip().upper()


def _manual_provider_structure():
    """Build Provider -> Service -> Country structure from manual uploads only."""
    tree = {}
    for bid, b in number_batches.items():
        provider = _manual_provider_name(b)
        if not provider:
            continue
        service = str(b.get("service", "")).strip().upper()
        country = str(b.get("country", "")).strip().upper()
        if not service or not country:
            continue
        node = tree.setdefault(provider, {}).setdefault(service, {})
        bucket = node.setdefault(country, {"batches": [], "numbers": [], "rate": None})
        bucket["batches"].append(bid)
        bucket["numbers"].extend([(b.get("numbers") or [])])
        if bucket["rate"] is None:
            try: bucket["rate"] = float(b.get("rate"))
            except Exception: pass
    for provider in tree:
        for service in tree[provider]:
            for country in tree[provider][service]:
                flat=[]
                for group in tree[provider][service][country]["numbers"]:
                    flat.extend(group)
                tree[provider][service][country]["numbers"] = flat
    return tree


def _manual_admin_token(kind, *parts):
    token = uuid.uuid4().hex[:10]
    manual_provider_admin_tokens[token] = (kind, tuple(str(x) for x in parts))
    return token


def _manual_admin_get_token(token):
    return manual_provider_admin_tokens.get(token)


