def manual_country_numbers_detail(provider, service, country, page=0):
    tree=_manual_provider_structure(); nums=tree.get(provider, {}).get(service, {}).get(country, {}).get("numbers", [])
    per_page=20; total=len(nums); start=page*per_page; chunk=nums[start:start+per_page]
    lines=[f"🏢 <b>{html.escape(provider)}</b>",f"🧩 <b>{html.escape(service)}</b>",f"🌍 <b>{html.escape(country)}</b>","━━━━━━━━━━━━━━━━━━━━",f"📱 Total: <b>{total}</b>",""]
    if not chunk: lines.append("<i>No active numbers in this group.</i>")
    else:
        for i,n in enumerate(chunk,start+1):
            raw=str(n.get("num", "")) if isinstance(n,dict) else str(n)
            lines.append(f"{i}. <code>{html.escape(raw)}</code>")
    nav=[]
    if page>0:
        tok=_manual_admin_token('numbers_page', provider, service, country, page-1)
        nav.append({"text":"◀️ Prev","callback_data":f"mnpn_{tok}","style":"primary"})
    if start+per_page<total:
        tok=_manual_admin_token('numbers_page', provider, service, country, page+1)
        nav.append({"text":"Next ▶️","callback_data":f"mnpn_{tok}","style":"primary"})
    kb=[]
    if nav: kb.append(nav)
    kb.append([{"text":"Back","callback_data":f"mnpc_{_manual_admin_token('country', provider, service, country)}","style":"danger"}])
    lines.append("━━━━━━━━━━━━━━━━━━━━")
    return render_body_text("\n".join(lines)), {"inline_keyboard":kb}



def _update_manual_group_rate(provider, service, country, rate):
    rate=float(rate)
    changed=0
    target_norms=set()
    for b in number_batches.values():
        if _manual_provider_name(b)!=provider: continue
        if str(b.get("service","")).strip().upper()!=service or str(b.get("country","")).strip().upper()!=country: continue
        b["rate"]=rate
        for item in b.get("numbers") or []:
            if not isinstance(item,dict): continue
            n=str(item.get("num", "")).strip()
            if not n: continue
            target_norms.add(_normalize_number_key(n)); changed+=1
            manual_number_reward_rates[n]=rate
            manual_number_reward_rates[_normalize_number_key(n)]=rate
            assigned_number_rates[n]=rate
            assigned_number_rates[_normalize_number_key(n)]=rate
            meta=manual_number_metadata.get(n) or manual_number_metadata.get(_normalize_number_key(n)) or {}
            meta=dict(meta); meta.update({"provider":provider,"service":service,"country":country,"rate":rate,"updated_at":time.time()})
            manual_number_metadata[n]=meta; manual_number_metadata[_normalize_number_key(n)]=dict(meta)
    # Also update durable metadata/rate for previously assigned or already-removed numbers.
    # Their metadata survives stock cleanup, so changing this provider/service/country
    # rate must continue to affect those numbers if they can still produce an OTP.
    for key, meta in list(manual_number_metadata.items()):
        if str(meta.get("provider","")).strip().upper()!=provider:
            continue
        if str(meta.get("service","")).strip().upper()!=service:
            continue
        if str(meta.get("country","")).strip().upper()!=country:
            continue
        meta=dict(meta); meta["rate"]=rate; meta["updated_at"]=time.time(); manual_number_metadata[key]=meta
        manual_number_reward_rates[key]=rate
        assigned_number_rates[key]=rate
    save_db()
    return changed

