def _normalize_zenex_global_feed(payload):
    if not isinstance(payload, dict):
        return []

    raw = payload.get("data", [])
    # ZenEX documentation returns data as a list. Be tolerant of wrapper shapes
    # so a harmless response-envelope change does not blank recent intelligence.
    if isinstance(raw, dict):
        for key in ("records", "items", "results", "broadcast", "global_broadcast", "events"):
            candidate = raw.get(key)
            if isinstance(candidate, list):
                raw = candidate
                break
    if not isinstance(raw, list):
        for key in ("records", "items", "results", "broadcast", "global_broadcast", "events"):
            candidate = payload.get(key)
            if isinstance(candidate, list):
                raw = candidate
                break
    if not isinstance(raw, list):
        return []

    records = []
    seen = set()

    for item in raw:
        if not isinstance(item, dict):
            continue

        service = str(item.get("service", "Unknown")).strip() or "Unknown"
        country = str(item.get("country", "Unknown")).strip() or "Unknown"
        operator = str(item.get("operator", "")).strip()
        number = str(item.get("number", "")).strip()

        raw_time = item.get("time", 0)
        try:
            raw_time_num = float(raw_time)
            ts = raw_time_num / 1000.0 if raw_time_num > 10_000_000_000 else raw_time_num
        except (TypeError, ValueError):
            ts = 0.0

        record_id = str(item.get("id", "")).strip()
        dedupe_key = record_id or f"{service}|{country}|{number}|{ts}|{operator}"

        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)

        records.append({
            "id": record_id,
            "service": service,
            "country": country,
            "operator": operator,
            "number": number,
            "time": ts,
            "source": "zenex-global"
        })

    return records

def fetch_zenex_global_traffic(force=False):
    global zenex_global_traffic, zenex_global_traffic_last_fetch, zenex_global_traffic_last_fetch_ok, zenex_global_traffic_last_error, zenex_global_traffic_last_status_code

    now = time.time()
    local_ttl = 5.0

    with zenex_global_traffic_lock:
        if (
            not force
            and zenex_global_traffic
            and (now - zenex_global_traffic_last_fetch) < local_ttl
        ):
            return list(zenex_global_traffic)

    keys = [str(k).strip() for k in (bot_settings.get("zenex_keys", []) or []) if str(k).strip()]
    # Keep every configured key for testing/rotation, but always retain the
    # bootstrap credential as a last-resort authenticated path when a stale DB
    # key is still present. Never log the key value itself.
    if ZENEX_BOOTSTRAP_KEY and ZENEX_BOOTSTRAP_KEY not in keys:
        keys.append(str(ZENEX_BOOTSTRAP_KEY).strip())
    if not keys:
        with zenex_global_traffic_lock:
            zenex_global_traffic_last_fetch_ok = False
            zenex_global_traffic_last_status_code = 0
            zenex_global_traffic_last_error = "No ZenEX API key configured."
            return list(zenex_global_traffic)

    last_error = None
    for key_index, api_key in enumerate(keys, 1):
        try:
            response = ZENEX_HTTP.get(
                ZENEX_GLOBAL_TRAFFIC_URL,
                timeout=8,
                headers={
                    "mapikey": api_key,
                    "Accept": "application/json",
                    "User-Agent": "NumberBot/ZenEX-Traffic",
                },
            )
            with zenex_global_traffic_lock:
                zenex_global_traffic_last_status_code = int(getattr(response, "status_code", 0) or 0)
            response.raise_for_status()
            payload = response.json()
            if isinstance(payload, dict) and payload.get("success") is False:
                raise ValueError(str(payload.get("message") or "ZenEX Global Broadcast reported failure"))
            records = _normalize_zenex_global_feed(payload)

            with zenex_global_traffic_lock:
                zenex_global_traffic = records[:1000]
                zenex_global_traffic_last_fetch = now
                zenex_global_traffic_last_fetch_ok = True
                zenex_global_traffic_last_status_code = int(getattr(response, "status_code", 200) or 200)
                zenex_global_traffic_last_error = ""
                result = list(zenex_global_traffic)
            try:
                _rebuild_live_traffic_intelligence(result)
            except Exception:
                pass
            if INTELLIGENCE_TERMINAL:
                _intelligence_terminal_log(
                    f"[RECENT BROADCAST] AUTH=OK | records={len(result)} | key_slot={key_index}/{len(keys)}"
                )
            return result
        except Exception as exc:
            last_error = exc
            continue

    with zenex_global_traffic_lock:
        zenex_global_traffic_last_fetch_ok = False
        # Keep the last observed HTTP status (e.g. 401) so the terminal tells us
        # whether the failure is authentication, rate limiting, or transport.
        zenex_global_traffic_last_error = str(last_error or "Unknown Global Broadcast error")[:240]
        result = list(zenex_global_traffic)
    if INTELLIGENCE_TERMINAL:
        _intelligence_terminal_log(
            f"[RECENT BROADCAST] AUTH=FAILED | keys_tried={len(keys)} | error={str(last_error or 'unknown')[:180]}"
        )
    return result

def zenex_global_traffic_listener():
    global zenex_global_traffic_last_fetch

    while True:
        try:
            records = fetch_zenex_global_traffic(force=True)
            if INTELLIGENCE_TERMINAL:
                now = time.time()
                fresh = 0
                newest_age = None
                for item in records or []:
                    try:
                        ts = float(item.get("time", 0) or 0)
                    except Exception:
                        ts = 0.0
                    if ts <= 0:
                        continue
                    age = max(0.0, now - ts)
                    newest_age = age if newest_age is None else min(newest_age, age)
                    if age <= AUTO_INTELLIGENCE_RECENT_WINDOW:
                        fresh += 1
                _intelligence_terminal_log(
                    f"[RECENT BROADCAST] fetched={len(records or [])} | fresh<=600s={fresh} "
                    f"| newest_age={('%.1fs' % newest_age) if newest_age is not None else 'n/a'} "
                    f"| fetch_status={'LIVE' if zenex_global_traffic_last_fetch_ok else 'CACHED/ERROR'}"
                )
        except Exception as exc:
            _intelligence_terminal_log(f"[RECENT BROADCAST] fetch error: {exc}")
        time.sleep(5)

def _country_directory():
    """Return normalized country aliases -> metadata for standard ISO regions.

    phonenumbers supplies calling codes; the existing ZenEX map supplies legacy
    aliases/territories. This avoids hard-coding a short, incomplete country list.
    """
    directory = {}
    for name, call_codes in ZENEX_COUNTRY_CALLING_CODES.items():
        for code in call_codes:
            directory.setdefault(_normalize_label(name), {"codes": set()})["codes"].add(str(code))

    if pycountry and phonenumbers:
        for region in pycountry.countries:
            iso = getattr(region, "alpha_2", "")
            if not iso:
                continue
            try:
                code = int(phonenumbers.country_code_for_region(iso))
            except Exception:
                code = 0
            if not code:
                continue
            names = {getattr(region, "name", ""), iso}
            for alias in names:
                if alias:
                    directory.setdefault(_normalize_label(alias), {"codes": set()})["codes"].add(str(code))
    # Critical territories commonly used by the bot and absent in the older table.
    directory.setdefault("montenegro", {"codes": set()})["codes"].add("382")
    directory.setdefault("me", {"codes": set()})["codes"].add("382")
    return directory

_COUNTRY_DIRECTORY_CACHE = _country_directory()


def _country_codes_for_label(label):
    raw = str(label or "").strip()
    normalized = _normalize_label(raw)
    flags = bot_settings.get("premium_flags", {}) or {}
    codes = set()

    digits = re.sub(r"[^0-9]", "", raw)
    if digits and 1 <= len(digits) <= 4:
        if digits in flags or any(str(k) == digits for k in flags):
            codes.add(digits)
        elif phonenumbers:
            # Accept a bare calling code if the library knows it.
            try:
                regions = phonenumbers.region_codes_for_country_code(int(digits))
                if regions:
                    codes.add(digits)
            except Exception:
                pass

    entry = _COUNTRY_DIRECTORY_CACHE.get(normalized)
    if entry:
        codes.update(entry.get("codes", set()))

    # Premium flag name/ISO fallback.
    if not codes:
        for code, data in flags.items():
            aliases = {_normalize_label(data.get("iso", "")), _normalize_label(data.get("name", ""))}
            if normalized in aliases:
                codes.add(str(code))
                break

    # Existing configured range fallback. Admin-configured ranges are the local
    # source of truth when a country is not present in the bundled directory.
    # Prefer the longest 1-4 digit international-looking prefix; when
    # libphonenumber is available, only accept prefixes that it recognizes.
    if not codes:
        configured = bot_settings.get("zenex_services", {}) or {}
        prefix_candidates = []
        for _, countries in configured.items():
            if not isinstance(countries, dict):
                continue
            for existing_country, ranges in countries.items():
                if _normalize_label(existing_country) != normalized:
                    continue
                for rng in (ranges if isinstance(ranges, list) else [ranges]):
                    rd = re.sub(r"[^0-9]", "", str(rng))
                    if not rd:
                        continue
                    for width in (4, 3, 2, 1):
                        if len(rd) < width:
                            continue
                        pref = rd[:width]
                        if phonenumbers:
                            try:
                                if not phonenumbers.region_codes_for_country_code(int(pref)):
                                    continue
                            except Exception:
                                continue
                        prefix_candidates.append(pref)
                    break
        if prefix_candidates:
            codes.update(sorted(set(prefix_candidates), key=lambda x: (-len(x), x)))
    return sorted({str(c) for c in codes if str(c).isdigit()}, key=lambda x: (-len(x), x))


def _service_key(value):
    return _normalize_label(value)


def _canonical_service_matches(api_service, configured_service):
    # Service name must match exactly after normalization. We intentionally do
    # not use loose substring/fuzzy matching because it can cross-wire routes.
    return bool(_service_key(api_service) and _service_key(api_service) == _service_key(configured_service))


def _configured_targets():
    configured = bot_settings.get("zenex_services", {}) or {}
    for service, countries in configured.items():
        if not isinstance(countries, dict):
            continue
        for country in countries.keys():
            codes = _country_codes_for_label(country)
            if codes:
                yield str(service), str(country), codes


def _all_configured_code_owners():
    owners = {}
    for service, country, codes in _configured_targets():
        for code in codes:
            owners.setdefault(code, set()).add((_normalize_label(service), _normalize_label(country)))
    return owners



def _recover_configured_country_for_range(service_name, range_value, current_item=None):
    """Recover a blank-country route without misusing shared calling codes.

    Recovery order is intentionally:
      1) latest valid analyzed snapshot,
      2) persisted validated Active-Ranges snapshot,
      3) configured country fallback (only when unambiguous).
    """
    service_key = _normalize_label(service_name)
    raw_range = str(range_value or "").strip()
    digits = re.sub(r"[^0-9]", "", raw_range)
    if not service_key or not digits:
        return ""

    def same_range(left):
        ld = re.sub(r"[^0-9]", "", str(left or ""))
        return bool(ld and (digits == ld or digits.startswith(ld) or ld.startswith(digits)))

    # 1) Latest valid analyzed snapshot.
    try:
        with _ANALYSIS_STATE_LOCK:
            previous = dict(_ANALYSIS_STATE or {})
        previous_services = previous.get("services", {}) or {}
        row = previous_services.get(service_key, {}) or {}
        matches = []
        for node in list(row.get("countries", ()) or ()):
            if not isinstance(node, dict):
                continue
            country = str(node.get("country", "") or "").strip()
            top_range = str(node.get("top_range", "") or "").strip()
            if country and same_range(top_range):
                matches.append(country)
        if len({_normalize_label(x) for x in matches}) == 1:
            return matches[0]
        for item in list(previous.get("active_ranges", ()) or ()):
            if not isinstance(item, dict):
                continue
            api_service = str(
                item.get("service", "") or item.get("service_name", "")
                or item.get("serviceName", "") or item.get("app", "")
                or item.get("application", "") or item.get("sid", "") or ""
            ).strip()
            if not _service_match_for_range(api_service, service_name):
                continue
            if not same_range(item.get("range", "") or item.get("prefix", "")):
                continue
            country = str(
                item.get("country", "") or item.get("country_name", "")
                or item.get("countryName", "") or item.get("iso", "")
                or item.get("country_code", "") or item.get("countryCode", "") or ""
            ).strip()
            if country and _normalize_label(country) not in {"unknown", "xx", "other", "others"}:
                matches.append(_country_full_name(country) or country)
        if len({_normalize_label(x) for x in matches}) == 1:
            return matches[0]
    except Exception:
        pass

    # 2) Persisted validated Active-Ranges snapshot.
    try:
        saved = bot_settings.get("zenex_active_range_snapshot", {}) or {}
        values = saved.get("active_ranges") if isinstance(saved, dict) else None
        if not isinstance(values, list) and isinstance(saved, dict):
            values = saved.get("ranges")
        matches = []
        if isinstance(values, list):
            for item in values:
                if not isinstance(item, dict):
                    continue
                api_service = str(
                    item.get("service", "") or item.get("service_name", "")
                    or item.get("serviceName", "") or item.get("app", "")
                    or item.get("application", "") or item.get("sid", "") or ""
                ).strip()
                if not _service_match_for_range(api_service, service_name):
                    continue
                if not same_range(item.get("range", "") or item.get("prefix", "")):
                    continue
                country = str(
                    item.get("country", "") or item.get("country_name", "")
                    or item.get("countryName", "") or item.get("iso", "")
                    or item.get("country_code", "") or item.get("countryCode", "") or ""
                ).strip()
                if country and _normalize_label(country) not in {"unknown", "xx", "other", "others"}:
                    matches.append(_country_full_name(country) or country)
        if len({_normalize_label(x) for x in matches}) == 1:
            return matches[0]
    except Exception:
        pass

    # 3) Configured-country fallback. Never guess a country solely from a shared
    # calling code such as +1 when more than one country is configured.
    configured_countries = []
    try:
        for cfg_service, country, country_codes in _configured_targets():
            if not _service_match_for_range(cfg_service, service_name):
                continue
            if not country:
                continue
            item = dict(current_item or {})
            item.setdefault("range", raw_range)
            item.pop("country", None)
            item.pop("country_name", None)
            item.pop("countryName", None)
            if _item_country_matches(item, country, country_codes, cfg_service):
                configured_countries.append(str(country).strip())
    except Exception:
        pass
    unique = {}
    for country in configured_countries:
        unique[_normalize_label(country)] = country
    if len(unique) == 1:
        return next(iter(unique.values()))

    return ""


def _item_country_matches(item, cfg_country, country_codes, cfg_service=None):
    """Match an Active-Ranges item to a configured country.

    Some Active-Ranges payloads omit country metadata, so the range prefix is
    used as a fallback. The prefix must be unambiguous *within the configured
    service*, not globally: the same country calling code can legitimately be
    configured for multiple services.
    """
    raw_country = str(
        item.get("country", "")
        or item.get("country_name", "")
        or item.get("countryName", "")
        or item.get("country_code", "")
        or item.get("countryCode", "")
        or item.get("iso", "")
        or item.get("cc", "")
        or item.get("countryISO", "")
        or item.get("country_iso", "")
    ).strip()
    raw_norm = _normalize_label(raw_country)
    if raw_country and raw_norm not in {"unknown", "xx", "other", "others"}:
        a = raw_norm
        c = _normalize_label(cfg_country)
        if a == c:
            return True
        if any(a == _normalize_label(alias) for alias in {str(x) for x in country_codes}):
            return True
        flags = bot_settings.get("premium_flags", {}) or {}
        for code in country_codes:
            data = flags.get(str(code), {})
            if a in {_normalize_label(data.get("iso", "")), _normalize_label(data.get("name", ""))}:
                return True
        return False

    raw_range = str(item.get("range", "") or item.get("prefix", "") or item.get("number_range", "") or item.get("numberRange", "")).strip()
    digits = re.sub(r"[^0-9]", "", raw_range)
    if not digits:
        return False

    # When the provider omitted/marked country as Unknown, resolve it from the
    # actual range before falling back to configured calling-code ownership.
    detected_country = _detect_country_from_range(raw_range)
    if detected_country:
        if _normalize_label(detected_country) == _normalize_label(cfg_country):
            return True
        try:
            if _normalize_label(_country_full_name(detected_country)) == _normalize_label(cfg_country):
                return True
        except Exception:
            pass

    # Country calling codes can be shared by several configured services.
    # Because the service was already matched by the caller, only require the
    # code to be unambiguous within that same service when full detection fails.
    target_service = _normalize_label(cfg_service or "")
    same_service_owners = {}
    configured = bot_settings.get("zenex_services", {}) or {}
    if target_service:
        for service, countries in configured.items():
            if _normalize_label(service) != target_service or not isinstance(countries, dict):
                continue
            for country in countries.keys():
                for code in _country_codes_for_label(country):
                    same_service_owners.setdefault(str(code), set()).add(_normalize_label(country))

    for code in country_codes:
        owners = same_service_owners.get(str(code), set())
        if digits.startswith(str(code)) and (not owners or len(owners) == 1 and _normalize_label(cfg_country) in owners):
            return True
    return False


def _select_top_range_from_candidates(candidates):
    """Return one deterministic Top-1 range from provider rows.

    A provider may emit the same number range in multiple rows (for example with
    separate tags).  Those rows describe one route, so their hits must be added
    before choosing the winner.  Without this aggregation the persisted route
    could disagree with the analytical Top-1 route shown to users.
    """
    grouped = {}
    for hits, raw_range, tag, api_service in candidates:
        node = grouped.setdefault(raw_range, {
            "hits": 0, "tag": "", "tag_hits": -1, "api_service": api_service,
        })
        node["hits"] += max(0, int(hits or 0))
        # Keep a stable representative tag for display/notifications only; it
        # never affects the hit-based range decision.
        if (int(hits or 0), _normalize_label(tag)) > (node["tag_hits"], _normalize_label(node["tag"])):
            node["tag"] = tag
            node["tag_hits"] = int(hits or 0)
            node["api_service"] = api_service
    if not grouped:
        return None
    raw_range, row = sorted(
        grouped.items(), key=lambda kv: (-int(kv[1]["hits"]), str(kv[0]))
    )[0]
    return {
        "range": raw_range,
        "hits": int(row["hits"]),
        "tag": row["tag"],
        "api_service": row["api_service"],
    }


def _select_configured_top_ranges(active_ranges):
    selected = {}
    for cfg_service, cfg_country, country_codes in _configured_targets():
        candidates = []
        cfg_norm = _normalize_label(cfg_service)
        for item in active_ranges:
            api_service = str(
                item.get("service", "")
                or item.get("service_name", "")
                or item.get("serviceName", "")
                or item.get("app", "")
                or item.get("application", "")
                or item.get("sid", "")
            ).strip()
            if _is_bare_fb_clone_service(item) or _is_reserved_fb_clone_conflict(item):
                continue
            clone_item = _is_fb_clone_range_item(item)
            fb_source_item = _is_facebook_range_service(api_service)

            # The exact ``Fb Clone`` tag is the only route that goes to the
            # dedicated clone service. Every other Facebook-family row goes to
            # normal Facebook, regardless of its tag.
            effective_service = _facebook_routing_service(item)

            if cfg_norm == "facebook":
                if clone_item:
                    continue
                if not _service_match_for_range(effective_service, cfg_service):
                    continue
            elif cfg_norm == _normalize_label(FB_CLONE_SERVICE_NAME):
                if not clone_item:
                    continue
                # PC Clone ranges are provider-side Facebook/Meta/etc. names,
                # so the explicit tag is enough to establish this destination.
            else:
                if clone_item or fb_source_item:
                    continue
                if not _service_match_for_range(effective_service, cfg_service):
                    continue

            raw_range = str(
                item.get("range", "")
                or item.get("prefix", "")
                or item.get("number_range", "")
                or item.get("numberRange", "")
            ).strip()
            if not raw_range or not _item_country_matches(item, cfg_country, country_codes, cfg_service):
                continue
            try:
                hit_value = (
                    item.get("hits", 0)
                    or item.get("hit", 0)
                    or item.get("count", 0)
                    or item.get("access", 0)
                    or (item.get("stats", {}) or {}).get("hits", 0)
                )
                hits = int(float(hit_value or 0))
            except (TypeError, ValueError):
                hits = 0
            tag = str(item.get("tag", "") or item.get("label", "")).strip()
            candidates.append((hits, raw_range, tag, api_service))
        top = _select_top_range_from_candidates(candidates)
        if top:
            selected[(cfg_service, cfg_country)] = {
                "range": top["range"], "hits": top["hits"],
                "tag": top["tag"], "api_service": top["api_service"],
                "country_codes": country_codes,
            }
    return selected


def _build_range_change_broadcast(changes):
    """Build a compact Premium-Emoji notification with Facebook variant labels."""
    lines = []
    for item in changes:
        service = str(item.get("service", "Unknown")).strip()
        country = str(item.get("country", "Unknown")).strip()
        tag = str(item.get("tag", "") or "").strip()
        service_name, service_html = get_service_info_html(service)
        variant = _facebook_variant_label(service, tag)
        service_name = _pretty_service_display_name(service_name)
        display_service = f"{service_name} • {variant}" if variant else service_name

        country_html = _premium_flag_html_for_country(country)

        old_range = item.get("old_range")
        new_range = item.get("new_range")
        if old_range and new_range:
            range_line = f"\nRange: <code>{html.escape(str(old_range))}</code> → <code>{html.escape(str(new_range))}</code>"
        elif new_range:
            range_line = f"\nRange: <code>{html.escape(str(new_range))}</code>"
        else:
            range_line = ""
        lines.append(
            f"{service_html} <b>{html.escape(display_service)}</b> High Access {PEM['fire']}\n"
            f"{country_html} <b>{html.escape(country)}</b> {PEM['fire']}{range_line}"
        )
    return render_body_text("\n\n".join(lines))

def _build_range_fs_snapshot(updated_settings):
    """Compatibility helper retained for callers; range state stays local-only."""
    return {}

def _write_firestore_settings_sync(settings_snapshot):
    # Compatibility no-op: range/configuration state is local-only.
    return True

def refresh_configured_zenex_ranges(force=False, broadcast_all=False, active_ranges_override=None, analyzed_apply=False, notify_admin=False):
    """Fetch ZenEX Active Ranges and atomically publish configured Top-1 state.

    Commit order is intentionally: ZenEX validation -> local storage -> notification.
    Firebase is never part of range/configuration persistence.
    """
    global zenex_range_status, zenex_range_last_refresh, zenex_next_auto_refresh_at, zenex_range_scan_running, bot_settings
    with zenex_range_lock:
        if zenex_range_scan_running:
            return {"ok": False, "status": "busy", "message": "Range refresh already running."}
        zenex_range_scan_running = True

    try:
        keys = [str(k).strip() for k in bot_settings.get("zenex_keys", []) if str(k).strip()]
        if not keys:
            return {"ok": False, "status": "error", "message": "No ZenEX API key configured."}

        # Click/analysis apply uses the latest background snapshot and performs no
        # provider network round-trip. Scheduled refreshes leave this override empty
        # and fetch a fresh Active-Ranges snapshot every three minutes.
        if active_ranges_override is not None:
            active_ranges = [dict(x) for x in list(active_ranges_override or []) if isinstance(x, dict)]
            candidate = {"cached": True, "success": True, "data": {"active_ranges": active_ranges}}
        else:
            headers = {"mapikey": keys[0], "Accept": "application/json", "User-Agent": "FRD-RangeSync/2.0"}
            last_error = None
            active_ranges = None

        if active_ranges_override is None:
            for attempt in range(3):
                try:
                    response = ZENEX_HTTP.get(
                        f"{ZENEX_BASE_URL}/v1/active-ranges",
                        headers=headers,
                        timeout=(5, 15),
                    )
                    response.raise_for_status()
                    candidate = response.json()
                    if isinstance(candidate, dict) and candidate.get("success") is not True:
                        raise ValueError(f"ZenEX Active Ranges API reported failure: {candidate.get('message', 'unknown error')}")

                    active = None
                    if isinstance(candidate, dict):
                        containers = [candidate]
                        data = candidate.get("data")
                        if isinstance(data, dict):
                            containers.insert(0, data)
                        for container in containers:
                            for key in ("active_ranges", "activeRanges", "ranges", "routes", "items", "results"):
                                value = container.get(key)
                                if isinstance(value, list):
                                    active = value
                                    break
                            if active is not None:
                                break
                            if isinstance(container.get("active"), list):
                                active = container.get("active")
                                break
                        if active is None and isinstance(data, list):
                            active = data
                    elif isinstance(candidate, list):
                        active = candidate

                    if not isinstance(active, list):
                        raise ValueError("Invalid Active Ranges response format.")

                    # Validate individual route objects without allowing one bad
                    # object to crash the complete refresh. API variants sometimes
                    # use app/sid and prefix/number_range instead of service/range.
                    active_ranges = []
                    for item in active:
                        if not isinstance(item, dict):
                            continue
                        route = str(
                            item.get("range", "")
                            or item.get("prefix", "")
                            or item.get("number_range", "")
                            or item.get("numberRange", "")
                        ).strip()
                        service = str(
                            item.get("service", "")
                            or item.get("service_name", "")
                            or item.get("serviceName", "")
                            or item.get("app", "")
                            or item.get("application", "")
                            or item.get("sid", "")
                        ).strip()
                        if not route or not service:
                            continue
                        item = dict(item)
                        item.setdefault("range", route)
                        item.setdefault("service", service)
                        active_ranges.append(item)
                    break
                except (requests.RequestException, ValueError) as exc:
                    last_error = str(exc)
                    if attempt < 2:
                        time.sleep(1 << attempt)

            if active_ranges is None:
                status_payload = {
                    "state": "error",
                    "last_error": last_error or "Unknown error",
                    "updated_at": time.time(),
                }
                bot_settings["zenex_range_status"] = status_payload
                return {"ok": False, "status": "error", "message": f"Range refresh failed: {last_error or 'Unknown error'}"}

        # Every successful scheduled provider scan refreshes the snapshot used by
        # subsequent zero-I/O user/admin Refresh clicks.
        _set_analyzed_active_ranges(active_ranges)
        # The fresh provider snapshot is now available to the same realtime intelligence
        # engine used for user clicks. This is local-only work; no extra provider request.
        try:
            _build_continuous_analysis_snapshot()
        except Exception as _analysis_exc:
            _terminal_log(f"[ZenEX] Intelligent apply analysis skipped: {_analysis_exc}")
        _prepared_apply_analysis = _analysis_snapshot()

        # Diagnostic-only: show every current service/country Top-Hit range with
        # its provider tag and canonical Facebook destination in the terminal.
        _print_top_hit_ranges_to_terminal(active_ranges)

        # Exact "Fb Clone" tags are isolated into the dedicated virtual service.
        # Normal Facebook ranges/tags are never copied into FB Forgot, and clone
        # ranges are excluded from the normal Facebook selection path.
        _sync_fb_clone_virtual_service(active_ranges=active_ranges, persist=False)

        configured_target_count = sum(1 for _ in _configured_targets())
        if not active_ranges and configured_target_count:
            bot_settings["zenex_range_status"] = {
                "state": "stale",
                "source": "zenex_active_ranges",
                "last_error": "Active-Ranges returned an empty set; existing range state was preserved.",
                "updated_at": time.time(),
                "active_ranges": 0,
                "configured_matches": 0,
                "updated_pairs": 0,
                "changed_pairs": 0,
            }
            save_db_sync()
            return {
                "ok": False,
                "status": "stale",
                "message": "ZenEX Active Ranges returned no routes; existing configuration was preserved.",
            }
        selected = _select_configured_top_ranges(active_ranges)

        # Discover the Top-3 countries for each service directly from Active Ranges.
        # Each discovered country gets exactly one Top-1 range; protected countries
        # (Force Delete OFF) are preserved and may make the total exceed three.
        discovered = {}
        for item in active_ranges:
            raw_api_service = str(
                item.get("service", "")
                or item.get("service_name", "")
                or item.get("serviceName", "")
                or item.get("app", "")
                or item.get("application", "")
                or item.get("sid", "")
            ).strip()
            raw_range = str(
                item.get("range", "")
                or item.get("prefix", "")
                or item.get("number_range", "")
                or item.get("numberRange", "")
            ).strip()
            if not raw_api_service or not raw_range:
                continue
            if _is_bare_fb_clone_service(item) or _is_reserved_fb_clone_conflict(item):
                continue

            # Resolve the provider row through the single authoritative Facebook
            # routing rule: exact ``Fb Clone`` tag -> FB Forgot; every other
            # Facebook-family tag/no-tag -> normal Facebook. Non-Facebook services
            # keep their provider service name unchanged.
            api_service = _facebook_routing_service(item)
            try:
                hit_value = item.get("hits", 0) or item.get("hit", 0) or item.get("count", 0) or item.get("access", 0) or (item.get("stats", {}) or {}).get("hits", 0)
                hits = int(float(hit_value or 0))
            except (TypeError, ValueError):
                hits = 0
            raw_country = str(item.get("country", "") or item.get("country_name", "") or item.get("countryName", "") or item.get("iso", "") or item.get("country_code", "") or "").strip()
            raw_country_norm = _normalize_label(raw_country)
            if raw_country and not (api_service == "Facebook" and raw_country_norm in {"unknown", "xx", "other", "others"}):
                country = _country_full_name(raw_country)
                if _normalize_label(country) in {"unknown", "xx", "other", "others"}:
                    country = raw_country
            else:
                country = ""
                try:
                    country = _detect_country_from_range(raw_range)
                except Exception:
                    country = ""
                if not country:
                    try:
                        _, country, _ = _country_display_from_number(raw_range)
                    except Exception:
                        country = "Unknown"
            if not country or country == "Unknown":
                continue
            svc_node = discovered.setdefault(api_service, {})
            cnode = svc_node.setdefault(country, {"hits": 0, "ranges": {}})
            cnode["hits"] += hits if hits > 0 else 1
            cnode["ranges"][raw_range] = cnode["ranges"].get(raw_range, 0) + max(hits, 1)

        configured_service_names = list((bot_settings.get("zenex_services", {}) or {}).keys())
        for api_service, countries_meta in discovered.items():
            # Never create a user-visible service from provider data. Active Ranges
            # may contain many provider-side services, but only services explicitly
            # configured by the administrator are allowed into the bot state.
            service_name = next(
                (x for x in configured_service_names if _service_match_for_range(api_service, x)),
                None,
            )
            if not service_name:
                continue
            analysis_service_row = ((_prepared_apply_analysis.get("services", {}) or {}).get(_normalize_label(service_name), {}) or {})
            analysis_countries = {
                _normalize_label(str(row.get("country", "") or "")): dict(row)
                for row in (analysis_service_row.get("countries", ()) or ())
                if isinstance(row, dict)
            }
            ranked_countries = sorted(
                countries_meta.items(),
                key=lambda kv: (
                    -float(analysis_countries.get(_normalize_label(kv[0]), {}).get("country_score", 0.0) or 0.0),
                    -int(kv[1]["hits"]),
                    _normalize_label(kv[0]),
                ),
            )
            auto_ranked = ranked_countries[:3]
            for country, meta_row in auto_ranked:
                ranges_ranked = sorted(meta_row["ranges"].items(), key=lambda kv: (-int(kv[1]), str(kv[0])))
                if ranges_ranked:
                    best_range, best_hits = ranges_ranked[0]
                    analysis_row = analysis_countries.get(_normalize_label(country), {})
                    intelligent_range = str(analysis_row.get("top_range", "") or "").strip()
                    intelligent_hits = int(analysis_row.get("top_range_hits", best_hits) or best_hits)
                    # Facebook/FB Forgot stays tag-locked inside the canonical analysis.
                    if intelligent_range and not _is_facebook_range_service(service_name):
                        best_range, best_hits = intelligent_range, intelligent_hits
                    selected[(service_name, country)] = {
                        "range": best_range, "hits": int(best_hits),
                        "tag": str(analysis_row.get("top_range_tag", "") or ""),
                        "api_service": api_service,
                        "country_codes": _country_codes_for_label(country),
                    }

        # Build the complete proposed configuration in memory first.
        proposed_settings = json.loads(json.dumps(bot_settings, ensure_ascii=False))
        services = proposed_settings.setdefault("zenex_services", {})
        meta = proposed_settings.setdefault("zenex_range_meta", {})
        previous_active_snapshot = proposed_settings.get("zenex_active_range_snapshot", {}) or {}
        snapshot_initialized = bool(previous_active_snapshot)
        if not isinstance(previous_active_snapshot, dict):
            previous_active_snapshot = {}
            snapshot_initialized = False
        next_active_snapshot = {}
        updated = 0
        matched = 0
        changed_pairs = []
        now_ts = time.time()

        # First add discovered Top-3 countries to each service.
        # Service-level AUTO OFF is authoritative: do not auto-create, auto-update,
        # or auto-prune any country/range inside that service. This preserves the
        # administrator's manual control for the whole service.
        for api_service, countries_meta in discovered.items():
            if (not _fb_pc_clone_enabled()) and any(_normalize_label(x) == _normalize_label(FB_CLONE_SERVICE_NAME) for x in (api_service,)):
                continue
            service_name = api_service
            for existing_service in list(services.keys()):
                if _service_match_for_range(api_service, existing_service):
                    service_name = existing_service
                    break
            if _normalize_label(service_name) == _normalize_label(FB_CLONE_SERVICE_NAME) and not _fb_pc_clone_enabled():
                continue
            service_bucket = services.get(service_name)
            if not isinstance(service_bucket, dict):
                # Provider data may only create countries under an explicitly
                # configured service. A service itself is never created from feed data.
                continue

            service_auto_on = _is_pair_auto_range_enabled("ZENEX", service_name, "__scope_probe__")
            if not service_auto_on:
                continue

            for country, meta_row in sorted(countries_meta.items(), key=lambda kv: (-int(kv[1]["hits"]), _normalize_label(kv[0])))[:3]:
                key = (service_name, country)
                # An explicit country-level AUTO OFF also prevents a missing country
                # from being auto-created again. The administrator can add it back
                # manually whenever desired.
                pair_override = _range_mode_store("ZENEX").get(_range_pair_key(service_name, country))
                if country not in service_bucket and pair_override is False:
                    continue
                if country not in service_bucket:
                    # New discovered countries inherit the service/provider AUTO state;
                    # do not materialize a forced True country override.
                    service_bucket[country] = []
                    _range_force_delete_store("ZENEX").setdefault(_range_pair_key(service_name, country), True)
                target = selected.get(key)
                if target and _is_pair_auto_range_enabled("ZENEX", service_name, country):
                    current = service_bucket.get(country, [])
                    previous_range = current[0] if isinstance(current, list) and current else None
                    new_range = target["range"]
                    if current != [new_range]:
                        service_bucket[country] = [new_range]
                        updated += 1
                    if previous_range != new_range and new_range:
                        changed_pairs.append({"service": service_name, "country": country, "old_range": previous_range, "new_range": new_range, "hits": target["hits"], "tag": target.get("tag", "")})

        for cfg_service, countries in list(services.items()):
            if _normalize_label(cfg_service) == _normalize_label(FB_CLONE_SERVICE_NAME) and not _fb_pc_clone_enabled():
                continue
            # Service-level AUTO OFF means the whole service is manual. Never delete,
            # trim, replace, or create anything automatically in this service.
            if not _is_pair_auto_range_enabled("ZENEX", cfg_service, "__scope_probe__"):
                continue
            if not isinstance(countries, dict):
                continue
            for cfg_country in list(countries.keys()):
                if not _is_pair_auto_range_enabled("ZENEX", cfg_service, cfg_country):
                    continue
                target = selected.get((cfg_service, cfg_country))
                if not target:
                    current = countries.get(cfg_country)
                    if isinstance(current, list) and len(current) > 1:
                        countries[cfg_country] = current[:1]
                        updated += 1
                    continue

                matched += 1
                current = countries.get(cfg_country, [])
                previous_range = current[0] if isinstance(current, list) and current else None
                new_range = target["range"]

                # Hard Top-1 invariant: exactly one stored range.
                if current != [new_range]:
                    countries[cfg_country] = [new_range]
                    updated += 1

                if previous_range != new_range and new_range:
                    changed_pairs.append({
                        "service": cfg_service,
                        "country": cfg_country,
                        "old_range": previous_range,
                        "new_range": new_range,
                        "hits": target["hits"],
                        "tag": target.get("tag", ""),
                    })

                meta[f"{_normalize_label(cfg_service)}::{_normalize_label(cfg_country)}"] = {
                    "service": cfg_service,
                    "country": cfg_country,
                    "range": new_range,
                    "hits": int(target["hits"]),
                    "tag": target["tag"],
                    "updated_at": now_ts,
                    "source": "zenex_active_ranges",
                }

        # Persist the exact validated provider snapshot so startup/admin refresh
        # can recover instantly even if the in-memory analysis worker has restarted.
        next_active_snapshot = {
            "active_ranges": [dict(x) for x in active_ranges if isinstance(x, dict)],
            "updated_at": now_ts,
            "source": "zenex_active_ranges",
        }
        proposed_settings["zenex_active_range_snapshot"] = next_active_snapshot

        # Enforce service-level maximum of three countries unless Force Delete is OFF.
        for cfg_service, countries in list(services.items()):
            if not isinstance(countries, dict):
                continue
            discovered_rank = []
            _analysis_service_row = ((_prepared_apply_analysis.get("services", {}) or {}).get(_normalize_label(cfg_service), {}) or {})
            _analysis_country_map = {
                _normalize_label(str(row.get("country", "") or "")): dict(row)
                for row in (_analysis_service_row.get("countries", ()) or ())
                if isinstance(row, dict)
            }
            for country, meta_row in (discovered.get(cfg_service, {}) or {}).items():
                _arow = _analysis_country_map.get(_normalize_label(country), {})
                discovered_rank.append((country, int(meta_row.get("hits", 0)), float(_arow.get("country_score", 0.0) or 0.0)))
            discovered_rank.sort(key=lambda x: (-x[2], -x[1], _normalize_label(x[0])))
            protected = [
                c for c in countries
                if (not _is_pair_auto_range_enabled("ZENEX", cfg_service, c))
                or (not _is_pair_force_delete_enabled("ZENEX", cfg_service, c))
            ]
            keep = list(dict.fromkeys(protected))
            for country, _hits, _score in discovered_rank:
                if country in keep:
                    continue
                if len(keep) < 3:
                    keep.append(country)
            for country in list(countries.keys()):
                if (
                    country not in keep
                    and _is_pair_auto_range_enabled("ZENEX", cfg_service, country)
                    and _is_pair_force_delete_enabled("ZENEX", cfg_service, country)
                ):
                    del countries[country]
                    updated += 1

        api_cached = bool(candidate.get("cached")) if isinstance(candidate, dict) else False
        status_payload = {
            "state": "live",
            "source": "cached" if api_cached else "live",
            "api_cached": api_cached,
            "last_error": None,
            "updated_at": now_ts,
            "active_ranges": len(active_ranges),
            "configured_matches": matched,
            "updated_pairs": updated,
            "changed_pairs": len(changed_pairs),
        }
        proposed_settings["zenex_range_status"] = status_payload

        # Do not treat every newly-visible Active Range as a public event.
        # A broadcast is sent only when a configured service/country pair
        # actually changes its stored range (old range -> new range).

        # Compare before committing proposed state so local change accounting stays exact.
        def _range_core(state):
            meta_state = state.get("zenex_range_meta", {}) or {}
            compact_meta = {}
            for key, value in meta_state.items():
                if isinstance(value, dict):
                    compact_meta[key] = {k: value.get(k) for k in ("service", "country", "range", "hits", "tag")}
            return {"zenex_services": state.get("zenex_services", {}), "zenex_range_meta": compact_meta}

        # Commit in-memory state only after the remote durability stage succeeds.
        bot_settings = proposed_settings
        zenex_range_last_refresh = now_ts
        # Successful manual/automatic apply always restarts the 3-minute clock.
        zenex_next_auto_refresh_at = time.monotonic() + AUTO_RANGE_UPDATE_INTERVAL

        # Make freshly applied countries/ranges visible immediately; do not wait
        # for the background 0.35s UI worker cycle.
        try:
            _build_fast_ui_snapshot()
        except Exception as _ui_exc:
            _terminal_log(f"[FAST_UI] post-range snapshot refresh skipped: {_ui_exc}")

        if not save_db_sync():
            bot_settings["zenex_range_status"] = {**status_payload, "last_error": "Local range storage write failed."}
            return {"ok": False, "status": "error", "message": "Local range storage write failed."}

        # Range mutations are aggregated per refresh and delivered to configured admins.
        notification_items = changed_pairs
        if notification_items and notify_admin:
            _notify_range_changes_aggregated("ZENEX", notification_items)

        _terminal_log(
            f"[ZenEX] refresh success cached={api_cached} active={len(active_ranges)} "
            f"configured={configured_target_count} matched={matched} updated={updated} "
            f"changed_top1={len(changed_pairs)}"
        )
        try:
            _print_top_hit_ranges_to_terminal(
                active_ranges,
                analysis=_analysis_snapshot(),
                result={
                    "ok": True,
                    "matched": matched,
                    "updated": updated,
                    "changed_pairs": len(changed_pairs),
                },
                trigger="AUTO/ADMIN APPLY",
            )
        except Exception:
            pass

        unmatched = max(0, configured_target_count - matched)
        return {
            "ok": True,
            "status": "live",
            "matched": matched,
            "unmatched": unmatched,
            "api_cached": api_cached,
            "updated": updated,
            "active_ranges": len(active_ranges),
            "changed_pairs": len(changed_pairs),
        }
    finally:
        with zenex_range_lock:
            zenex_range_scan_running = False

def firestore_storage_metrics():
    """Return current Firestore data+index storage from Cloud Monitoring when available.

    Firestore publishes this as a gauge. The metric is sampled periodically, so
    the displayed value is the latest available monitoring sample, not a live byte counter.
    """
    result = {"ok": False, "bytes": None, "gib": None, "free_quota_percent": None, "free_quota_remaining_gib": None, "error": None}
    if not db or not monitoring_v3:
        result["error"] = "Cloud Monitoring SDK/permission unavailable"
        return result
    try:
        project_id = os.getenv("FIRESTORE_PROJECT_ID", "").strip()
        if not project_id:
            try:
                project_id = firebase_admin.get_app().project_id or ""
            except Exception:
                project_id = ""
        if not project_id:
            raise RuntimeError("FIRESTORE_PROJECT_ID is not configured")

        client = monitoring_v3.MetricServiceClient()
        from datetime import timezone, timedelta
        now = datetime.now(timezone.utc)
        interval = monitoring_v3.TimeInterval()
        interval.end_time.FromDatetime(now)
        interval.start_time.FromDatetime(now - timedelta(minutes=10))
        request = monitoring_v3.ListTimeSeriesRequest(
            name=f"projects/{project_id}",
            filter='metric.type="firestore.googleapis.com/storage/data_and_index_storage_bytes"',
            interval=interval,
            view=monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
        )
        total = 0
        for series in client.list_time_series(request=request):
            if not series.points:
                continue
            # Point list is newest-first for this API in normal responses; max is safe.
            latest = max(series.points, key=lambda p: p.interval.end_time)
            total += int(latest.value.int64_value or latest.value.double_value or 0)
        gib = total / (1024 ** 3)
        free_quota = 1.0
        percent = min(100.0, (gib / free_quota) * 100.0)
        result.update({
            "ok": True,
            "bytes": total,
            "gib": gib,
            "free_quota_percent": percent,
            "free_quota_remaining_gib": max(0.0, free_quota - gib),
        })
        return result
    except Exception as exc:
        result["error"] = str(exc)[:180]
        return result


def firestore_admin_status():
    fs = firestore_storage_metrics()
    return {
        "connected": bool(db),
        "storage": fs,
        "local_last_write": LOCAL_LAST_WRITE,
        "user_cache": len(user_cache),
        "known_users": len(all_known_users),
    }



def _refresh_traffic_analysis_silently():
    """Publish the newest prepared local snapshot without starting research.

    Expensive intelligence research runs on the unified three-minute checkpoint
    or via Admin Refresh. A normal user Traffic click only renders the latest
    prepared state so the interaction remains fast and non-blocking.
    """
    _FAST_UI_DIRTY.set()
    try:
        _build_fast_ui_snapshot()
    except Exception as exc:
        _terminal_log(f"[Traffic] fast snapshot refresh skipped: {exc}", flush=True)
    try:
        snap = _fast_ui_snapshot()
        published = _publish_active_menus(snap, force=True)
    except Exception as exc:
        published = 0
        _terminal_log(f"[Traffic] live UI publish skipped: {exc}", flush=True)
    return {"ok": True, "published": int(published)}


def _traffic_analysis_rows():
    """Return configured services with Top-3 countries and Top-1 range metrics."""
    analysis = _analysis_snapshot()
    configured = _configured_service_catalog()
    services = analysis.get("services", {}) or {}
    out = []
    for key, row in services.items():
        if not isinstance(row, dict):
            continue
        service = configured.get(_normalize_label(row.get("service", "")))
        if not service:
            continue
        countries = [dict(x) for x in (row.get("countries", ()) or ()) if isinstance(x, dict) and str(x.get("country", "")).strip()]
        countries = countries[:3]
        total_hits = int(row.get("total_hits", 0) or 0)
        if total_hits <= 0:
            total_hits = sum(int(x.get("hits", 0) or 0) for x in countries)
        out.append({"service": service, "total_hits": total_hits, "countries": countries})
    out.sort(key=lambda x: (-int(x["total_hits"]), _normalize_label(x["service"])))
    # Include configured services with no analysis evidence at the bottom.
    seen = {_normalize_label(x["service"]) for x in out}
    for service in configured.values():
        if _normalize_label(service) not in seen:
            out.append({"service": service, "total_hits": 0, "countries": []})
    return out


def build_traffic_ui():
    status = bot_settings.get("zenex_range_status", {}) or {}
    rows = _traffic_analysis_rows()
    lines = [
        "🔥 <b>LIVE TRAFFIC</b>",
        "━" * 51,
    ]
    if status.get("state") == "live":
        lines.append("🟢 <b>Source:</b> LIVE")
    elif status.get("state") == "error" or status.get("last_error"):
        lines.append("🟡 <b>Source:</b> CACHED (last refresh failed)")
    else:
        lines.append("🔄 <b>Source:</b> ANALYZING…")
    if status.get("updated_at"):
        dt = datetime.fromtimestamp(status["updated_at"]).strftime("%H:%M:%S")
        lines.append(f"🕓 Last range update: {dt}")
    lines.append("")
    visible = [x for x in rows if x["countries"] or x["total_hits"] > 0]
    if not visible:
        lines.append("<i>No traffic analysis is available yet.</i>")
    else:
        lines.append("<b>Services ranked by current performance:</b>")
        lines.append(f"\n✅ Configured services: <b>{len(rows)}</b>")
        lines.append("✅ Top-3 countries + Top-1 range per country")

    kb, row = [], []
    for item in rows:
        service = item["service"]
        label = str(service)
        row.append({
            "text": label,
            "icon_custom_emoji_id": _service_emoji_id(service),
            "callback_data": f"traffic_srv_{service}",
            "style": "primary",
        })
        if len(row) == 2:
            kb.append(row); row = []
    if row: kb.append(row)
    kb.append([{"text": "Refresh Ranges", "icon_custom_emoji_id": "5465368548702446780", "callback_data": "refresh_zenex_configured_ranges", "style": "success"}])
    kb.append([{"text": "Close", "icon_custom_emoji_id": "5420130255174145507", "callback_data": "close_msg", "style": "danger"}])
    markup = {"inline_keyboard": kb}
    return _balance_text_to_inline_keyboard(render_user_body_text("\n".join(lines)), markup), markup


def _service_emoji_html(service):
    """Return only the exact admin-configured Premium Emoji for a service."""
    _, data = _premium_service_record(service)
    if isinstance(data, dict):
        eid = str(data.get("id") or data.get("custom_emoji_id") or "").strip()
        char = str(data.get("char") or data.get("emoji") or "📱").strip()
        if eid.isdigit():
            return f'<tg-emoji emoji-id="{eid}">{html.escape(char)}</tg-emoji>'
        return html.escape(char)
    return ""


def _service_emoji_id(service):
    """Return the admin-uploaded Premium App Emoji ID, then fixed fallback."""
    # Admin configuration must win for every service button/logo.
    _, data = _premium_service_record(service)
    if isinstance(data, dict):
        eid = str(data.get("id") or data.get("custom_emoji_id") or "").strip()
        if eid.isdigit():
            return eid

    detected = _detected_fixed_service_key(service)
    if detected:
        return FIXED_PREMIUM_SERVICE_EMOJI_IDS.get(detected, "")
    for alias in _service_emoji_aliases(service):
        fixed = FIXED_PREMIUM_SERVICE_EMOJI_IDS.get(alias)
        if fixed:
            return fixed
    return ""


def build_traffic_service_ui(service):
    if not _is_configured_service(service):
        return render_user_body_text("❌ <b>Service is not configured.</b>"), {"inline_keyboard": [[{"text": "Back", "icon_custom_emoji_id": "5267490665117275176", "callback_data": "refresh_traffic", "style": "danger"}]]}
    configured = _configured_service_catalog()
    service = configured.get(_normalize_label(service), str(service).strip())
    analysis = _analysis_snapshot()
    stat = (analysis.get("services", {}) or {}).get(_normalize_label(service), {}) or {}
    items = [dict(x) for x in (stat.get("countries", ()) or ()) if isinstance(x, dict)]
    items = items[:3]
    if not items:
        direct_items = _prepared_active_range_country_fallback(service)
        items = [
            {
                "country": str(row.get("country", "") or ""),
                "hits": int(row.get("hits", 0) or 0),
                "top_range": str(row.get("range", "") or ""),
                "top_range_hits": int(row.get("range_hits", 0) or 0),
            }
            for row in direct_items
        ]
    display_service = _pretty_service_display_name(service)
    lines = [f"🔥 <b>{html.escape(display_service.upper())} LIVE TRAFFIC</b>", "━━━━━━━━━━━━━━━━━━━━", "<b>Top 3 countries:</b>", ""]
    kb, row = [], []
    for rank, item in enumerate(items, 1):
        country = str(item.get("country", "")).strip()
        hits = int(item.get("hits", 0) or 0)
        rng = str(item.get("top_range", "") or "").strip()
        flag = _premium_flag_html_for_country(country)
        iso_short = _country_short_name(country).upper() or "XX"
        fire_html = f" {_premium_body_emoji_html('🔥')}" if rank == 1 else ""
        range_part = f" • Top-1 <code>{html.escape(rng)}</code>" if rng else ""
        lines.append(f"{rank}. {flag} <b>{html.escape(iso_short)}</b> • <b>{hits}</b> hits{range_part}{fire_html}")
        # Country buttons intentionally show only the configured Premium Flag,
        # ISO short name and hit count. Full country names stay out of the button
        # label so the traffic UI remains compact and consistent.
        button_text = f"{iso_short} · {hits}"
        row.append({
            "text": button_text,
            "icon_custom_emoji_id": _country_emoji_id(country),
            "callback_data": f"traffic_country_{service}_{country}",
            "style": "primary",
        })
        if len(row) == 2:
            kb.append(row); row = []
    if row: kb.append(row)
    if not items:
        lines.append("<i>No analyzed country data yet.</i>")
    kb.append([{"text": "Back", "icon_custom_emoji_id": "5267490665117275176", "callback_data": "refresh_traffic", "style": "danger"}])
    return render_user_body_text("\n".join(lines)), {"inline_keyboard": kb}


def _country_emoji_id(country):
    norm = _normalize_label(country)
    for code, data in bot_settings.get("premium_flags", {}).items():
        if norm in {_normalize_label(data.get("iso", "")), _normalize_label(data.get("name", ""))}:
            return data.get("id", "5780471598922337683")
    return "5780471598922337683"


def build_traffic_country_ui(service, country):
    if not _is_configured_service(service):
        return render_user_body_text("❌ <b>Service is not configured.</b>"), {"inline_keyboard": [[{"text": "Back", "icon_custom_emoji_id": "5267490665117275176", "callback_data": "refresh_traffic", "style": "danger"}]]}
    configured = _configured_service_catalog()
    service = configured.get(_normalize_label(service), str(service).strip())
    analysis = _analysis_snapshot()
    stat = (analysis.get("services", {}) or {}).get(_normalize_label(service), {}) or {}
    candidates = [dict(x) for x in (stat.get("countries", ()) or ()) if isinstance(x, dict) and _normalize_label(x.get("country", "")) == _normalize_label(country)]
    iso_short = _country_short_name(country).upper() or "XX"
    _svc_name, _svc_html = get_service_info_html(service)
    lines = [
        f"{_svc_html} <b>{html.escape(_pretty_service_display_name(service).upper())}</b>",
        f"{_premium_flag_html_for_country(country)} <b>{html.escape(str(country).upper())} ({html.escape(iso_short)})</b>",
        "━━━━━━━━━━━━━━━━━━━━",
    ]
    if candidates:
        top = candidates[0]
        rng = str(top.get("top_range", "") or "").strip()
        hits = int(top.get("hits", 0) or 0)
        lines.append("🏆 <b>TOP 1 HIT RANGE</b>")
        lines.append(f"<code>{html.escape(rng or 'N/A')}</code>")
        lines.append(f"📈 Hits: <b>{hits}</b>")
    else:
        lines.append("<i>No analyzed range is currently available for this service/country.</i>")
    kb = [[{"text": "Back", "icon_custom_emoji_id": "5267490665117275176", "callback_data": f"traffic_srv_{service}", "style": "danger"}]]
    return render_user_body_text("\n".join(lines)), {"inline_keyboard": kb}


def _find_withdrawal_req_by_group_prompt(group_chat_id, prompt_message_id):
    """Find a pending withdrawal by the exact TXID prompt message it generated."""
    gid = str(group_chat_id)
    pid = int(prompt_message_id)
    for rid, req in list(pending_withdrawals.items()):
        try:
            if str(req.get("status", "")) != "awaiting_txid":
                continue
            if str(req.get("group_chat_id", "")) != gid:
                continue
            if int(req.get("txid_prompt_message_id", 0) or 0) == pid:
                return str(rid)
        except Exception:
            continue
    # Fallback after partial/local state loss: use Firestore for the exact
    # prompt id and group. This keeps TXID entry usable after a restart.
    if db:
        try:
            q = db.collection("withdrawals")
            try:
                docs = q.where("status", "==", "awaiting_txid").where("group_chat_id", "==", gid).stream()
            except Exception:
                docs = q.where("status", "==", "awaiting_txid").stream()
            for doc in docs:
                raw = doc.to_dict() or {}
                if str(raw.get("group_chat_id", gid)) != gid:
                    continue
                if int(raw.get("txid_prompt_message_id", 0) or 0) == pid:
                    rid = str(doc.id)
                    if rid not in pending_withdrawals:
                        try:
                            pending_withdrawals[rid] = {
                                "user_id": int(raw.get("user_id")),
                                "amount": float(raw.get("amount", 0.0) or 0.0),
                                "method": str(raw.get("method", "") or ""),
                                "number": str(raw.get("number", "") or ""),
                                "full_name": str(raw.get("full_name", raw.get("user_id", "User")) or "User"),
                                "balance_before": float(raw.get("balance_before", 0.0) or 0.0),
                                "balance_after": float(raw.get("balance_after", 0.0) or 0.0),
                                "status": "awaiting_txid",
                                "group_chat_id": gid,
                                "group_message_id": raw.get("group_message_id"),
                                "txid_prompt_message_id": pid,
                                "firebase_debited": True,
                            }
                        except Exception:
                            pass
                    return rid
        except Exception as exc:
            _terminal_log(f"[WITHDRAWAL][TXID] prompt lookup failed: {exc}")
    return ""


def _firestore_withdrawal_complete_txid(req_id, admin_id, txid):
    """Atomically move awaiting_txid -> approved and persist the TXID exactly once."""
    if not db:
        return False, "Firebase unavailable"
    transactional = getattr(firestore, "transactional", None)
    if not callable(transactional):
        return False, "Firestore transaction unavailable"
    req_id = str(req_id)
    try:
        @transactional
        def _tx(transaction):
            wref = db.collection("withdrawals").document(req_id)
            snap = wref.get(transaction=transaction)
            raw = snap.to_dict() if getattr(snap, "exists", False) else {}
            status = str(raw.get("status", "") or "")
            if status == "approved":
                existing = str(raw.get("transaction_id", "") or "")
                if existing == str(txid):
                    return True
                raise RuntimeError("withdrawal already approved with another TXID")
            if status != "awaiting_txid" or not bool(raw.get("firebase_debited", False)):
                raise RuntimeError(f"withdrawal is not awaiting TXID: {status}")
            transaction.set(wref, {
                "status": "approved",
                "transaction_id": str(txid),
                "processed_by": str(admin_id),
                "firebase_debited": True,
                "completed_at": firestore.SERVER_TIMESTAMP,
            }, merge=True)
            return True
        _tx(db.transaction())
        return True, "ok"
    except Exception as exc:
        return False, str(exc)


def _handle_group_withdrawal_txid(msg, req_id, admin_id):
    """Finalize one exact withdrawal from a reply to its exact TXID prompt."""
    req = pending_withdrawals.get(str(req_id))
    chat_id = msg["chat"]["id"]
    reply_to_id = (msg.get("reply_to_message") or {}).get("message_id")
    txid = str(msg.get("text", "") or "").strip()
    if not req or str(req.get("status", "")) != "awaiting_txid":
        send_message(chat_id, render_body_text("❌ <b>This withdrawal is no longer awaiting TXID.</b>"), reply_to_message_id=msg.get("message_id"))
        return
    if int(req.get("txid_prompt_message_id", 0) or 0) != int(reply_to_id or 0):
        send_message(chat_id, render_body_text("↩️ <b>Please reply directly to the TXID prompt for this specific withdrawal.</b>"), reply_to_message_id=msg.get("message_id"))
        return
    if not 3 <= len(txid) <= 128:
        send_message(chat_id, render_body_text("❌ <b>Invalid TXID.</b> Send 3–128 characters by replying to the TXID prompt."), reply_to_message_id=msg.get("message_id"))
        return

    # Prevent two admins replying to the same prompt simultaneously.
    inflight_key = f"TXID:{req_id}"
    with WITHDRAWAL_ACTION_LOCK:
        if inflight_key in withdrawal_action_inflight:
            send_message(chat_id, render_body_text("⏳ <b>This TXID is already being processed.</b>"), reply_to_message_id=msg.get("message_id"))
            return
        withdrawal_action_inflight.add(inflight_key)
    try:
        ok, reason = _firestore_withdrawal_complete_txid(req_id, admin_id, txid)
        if not ok:
            send_message(chat_id, render_body_text(f"❌ <b>TXID save failed.</b>\n<code>{html.escape(str(reason))}</code>"), reply_to_message_id=msg.get("message_id"))
            return
        uid = int(req["user_id"]); amt = float(req["amount"])
        req["status"] = "approved"
        req["transaction_id"] = txid
        req["processed_by"] = admin_id
        req["firebase_debited"] = True
        # Delete the temporary TXID prompt after successful completion, then
        # convert the original pending request message into the final SUCCESS state.
        prompt_id = int(req.get("txid_prompt_message_id", 0) or 0)
        if prompt_id and str(req.get("group_chat_id", "")) == str(chat_id):
            try:
                delete_message(chat_id, prompt_id)
                _terminal_log(f"[WITHDRAWAL][TXID] prompt deleted req={req_id} prompt_id={prompt_id}")
            except Exception as exc:
                _terminal_log(f"[WITHDRAWAL][TXID] prompt delete failed req={req_id}: {exc}")

        if req.get("group_chat_id") and req.get("group_message_id"):
            edit_message(req["group_chat_id"], req["group_message_id"], render_body_text(
                f"✅ <b>WITHDRAWAL SUCCESS</b>\n\n"
                f"👤 <b>USERNAME:</b> {html.escape(req.get('full_name', str(uid)))}\n"
                f"🆔 <b>USER ID:</b> <code>{uid}</code>\n"
                f"💳 <b>WITHDRAWAL:</b> {amt:g} TK\n"
                f"💰 <b>REMAINING:</b> {req.get('balance_after', 0.0):g} TK\n"
                f"🏦 <b>METHOD:</b> {html.escape(req.get('method', ''))}\n"
                f"📱 <b>NUMBER:</b> <code>{html.escape(req.get('number', ''))}</code>\n"
                f"🧾 <b>REQ ID:</b> <code>{req_id}</code>\n"
                f"🔑 <b>TRANSACTION ID:</b> <code>{html.escape(txid)}</code>"),
                reply_markup={"inline_keyboard":[[{"text":"✅ SUCCESS","icon_custom_emoji_id":"5352694861990501856","callback_data":"dismiss_status","style":"success"}]]})

        # Notify both sides: the admin who entered TXID and the withdrawing user.
        send_message(chat_id, render_body_text(
            f"✅ <b>TXID submitted successfully.</b>\n\n"
            f"🧾 <b>REQ ID:</b> <code>{req_id}</code>\n"
            f"🔑 <b>TXID:</b> <code>{html.escape(txid)}</code>"),
            reply_to_message_id=msg.get("message_id"))
        send_message(uid, render_body_text(
            f"✅ <b>Your withdrawal is successful!</b>\n\n"
            f"💳 <b>Amount:</b> {amt:g} TK\n"
            f"🏦 <b>Method:</b> {html.escape(req.get('method', ''))}\n"
            f"📱 <b>Number:</b> <code>{html.escape(req.get('number', ''))}</code>\n"
            f"🧾 <b>REQ ID:</b> <code>{req_id}</code>\n"
            f"🔑 <b>Transaction ID:</b> <code>{html.escape(txid)}</code>"))
        pending_withdrawals.pop(str(req_id), None)
        save_db_sync()
    except Exception as exc:
        _terminal_log(f"[WITHDRAWAL][TXID] finalize error req={req_id}: {exc}")
        send_message(chat_id, render_body_text(f"❌ <b>TXID processing failed.</b>\n<code>{html.escape(str(exc))}</code>"), reply_to_message_id=msg.get("message_id"))
    finally:
        with WITHDRAWAL_ACTION_LOCK:
            withdrawal_action_inflight.discard(inflight_key)

