MANUAL_ELITESMS_PANEL_ID = "builtin_elitesms"
MANUAL_ELITESMS_PANEL_NAME = "EliteSMS"
MANUAL_LEASE_SECONDS = 20 * 60

# EliteSMS explicitly rate-limits the Pull API. Keep one shared request clock for
# the listener and the admin Test button so they can never hammer the same endpoint.
ELITESMS_RATE_LIMIT_FLOOR = max(5.0, float(os.getenv("ELITESMS_RATE_LIMIT_FLOOR", "5.1")))
_elitesms_request_lock = threading.RLock()
_elitesms_request_session = requests.Session()
_elitesms_request_session.mount("http://", HTTPAdapter(pool_connections=4, pool_maxsize=4, max_retries=0))
_elitesms_request_session.mount("https://", HTTPAdapter(pool_connections=4, pool_maxsize=4, max_retries=0))
_elitesms_request_session.headers.update({"Connection": "keep-alive", "User-Agent": "FRD-EliteSMS/1.0"})
_elitesms_next_request_at = 0.0
_elitesms_server_backoff_until = 0.0
# Non-blocking delivery lane: fetching never waits on Telegram network latency.
_elitesms_delivery_pool = ThreadPoolExecutor(max_workers=32, thread_name_prefix="elitesms-delivery")
elite_sms_inflight_events = set()


def _elite_sms_settings():
    cfg = bot_settings.setdefault("elite_sms_manual", {})
    if not isinstance(cfg, dict):
        cfg = {}
        bot_settings["elite_sms_manual"] = cfg
    cfg.setdefault("panel_id", MANUAL_ELITESMS_PANEL_ID)
    cfg.setdefault("panel_name", MANUAL_ELITESMS_PANEL_NAME)
    cfg.setdefault("type", "API Panel")
    cfg.setdefault("api_url", os.getenv("ELITESMS_API_URL", "http://217.216.36.163/api/v1/sms"))
    cfg.setdefault("api_key", os.getenv("ELITESMS_API_KEY", ""))
    try:
        cfg["records"] = max(1, int(cfg.get("records", 5) or 5))
    except Exception:
        cfg["records"] = 5
    try:
        cfg["poll_interval"] = max(0.05, float(cfg.get("poll_interval", 0.075) or 0.075))
    except Exception:
        cfg["poll_interval"] = 0.075
    return cfg



# -----------------------------------------------------------------------------
# Fixed Manual Login Presets
# Admin should never have to re-enter panel URL/column/CDr settings for these
# known manual panels. Only username/password are editable from the UI.
# Existing matching panel entries are used as the fixed template so deployment-
# specific URLs are preserved automatically. HADI has its canonical URL baked in.
# -----------------------------------------------------------------------------
# Live admin UI status tracking for fixed manual-login panels.
# The worker only watches pages that an admin currently has open, so it does
# not create per-user/per-panel polling overhead.
_MANUAL_PRESET_UI_LOCK = threading.RLock()
_MANUAL_PRESET_UI_WATCHERS = {}
_MANUAL_PRESET_UI_STOP = threading.Event()
_MANUAL_PRESET_UI_INTERVAL = max(0.20, float(os.getenv("MANUAL_PRESET_UI_INTERVAL", "0.35")))
_MANUAL_PANEL_CONFIG_UI_LOCK = threading.RLock()
_MANUAL_PANEL_CONFIG_UI_WATCHERS = {}
_MANUAL_LIVE_CHECK_LOCK = threading.RLock()
_MANUAL_LIVE_CHECK_INFLIGHT = set()


def _manual_preset_ui_watch(chat_id, msg_id, preset_key, idx):
    try:
        watch_key = (int(chat_id), int(msg_id))
    except Exception:
        return
    with _MANUAL_PRESET_UI_LOCK:
        _MANUAL_PRESET_UI_WATCHERS[watch_key] = {
            "chat_id": int(chat_id),
            "msg_id": int(msg_id),
            "preset_key": str(preset_key or "").lower(),
            "idx": int(idx),
            "last_status": None,
            "last_render": None,
        }


def _manual_preset_ui_unwatch(chat_id, msg_id):
    try:
        watch_key = (int(chat_id), int(msg_id))
    except Exception:
        return
    with _MANUAL_PRESET_UI_LOCK:
        _MANUAL_PRESET_UI_WATCHERS.pop(watch_key, None)


def _manual_panel_config_ui_watch(chat_id, msg_id, idx):
    try:
        watch_key = (int(chat_id), int(msg_id))
        idx = int(idx)
    except (TypeError, ValueError):
        return
    with _MANUAL_PANEL_CONFIG_UI_LOCK:
        _MANUAL_PANEL_CONFIG_UI_WATCHERS[watch_key] = {
            "chat_id": int(chat_id),
            "msg_id": int(msg_id),
            "idx": idx,
            "last_signature": None,
        }


def _manual_panel_config_ui_unwatch(chat_id, msg_id):
    try:
        watch_key = (int(chat_id), int(msg_id))
    except (TypeError, ValueError):
        return
    with _MANUAL_PANEL_CONFIG_UI_LOCK:
        _MANUAL_PANEL_CONFIG_UI_WATCHERS.pop(watch_key, None)


def _manual_panel_config_ui_worker():
    while not _MANUAL_PRESET_UI_STOP.is_set():
        try:
            with _MANUAL_PANEL_CONFIG_UI_LOCK:
                watchers = list(_MANUAL_PANEL_CONFIG_UI_WATCHERS.values())
            panels = bot_settings.get("panels", []) or []
            for w in watchers:
                try:
                    idx = int(w.get("idx", -1))
                    chat_id = int(w.get("chat_id"))
                    msg_id = int(w.get("msg_id"))
                    if idx < 0 or idx >= len(panels) or not isinstance(panels[idx], dict):
                        _manual_panel_config_ui_unwatch(chat_id, msg_id)
                        continue
                    p = panels[idx]
                    if not _manual_is_login_panel(p):
                        continue
                    status = _normalize_legacy_login_status(
                        p.get("login_status"),
                        bool(p.get("username") and p.get("password")),
                    )
                    signature = (
                        status,
                        str(p.get("status") or ""),
                        str(p.get("username") or ""),
                        str(p.get("last_successful_check") or ""),
                        str(p.get("last_data_check") or ""),
                    )
                    if signature == w.get("last_signature"):
                        continue
                    w["last_signature"] = signature
                    with _MANUAL_PANEL_CONFIG_UI_LOCK:
                        _MANUAL_PANEL_CONFIG_UI_WATCHERS[(chat_id, msg_id)] = dict(w)
                    text = (
                        f"⚙️ <b>Configure {html.escape(str(p.get('name') or 'Manual Panel'))}</b>\n\n"
                        f"<b>Type:</b> {html.escape(str(p.get('type') or 'Auto Captcha Panel'))}\n"
                        f"<b>Status:</b> {'🟢 Monitoring' if str(p.get('status') or 'ON').upper() == 'ON' else '🔴 Stopped'}\n"
                        f"<b>Login Status:</b> {html.escape(status)}\n"
                        f"<b>Login URL:</b> <code>{html.escape(str(p.get('login_url') or 'None'))}</code>\n"
                        f"<b>User:</b> <code>{html.escape(str(p.get('username') or 'None'))}</code>\n"
                        f"<b>Num Col:</b> {html.escape(str(p.get('num_col_name') or 'number'))} (Idx: {html.escape(str(p.get('num_col_idx') or '3'))})\n"
                        f"<b>Msg Col:</b> {html.escape(str(p.get('msg_col_name') or 'sms'))} (Idx: {html.escape(str(p.get('msg_col_idx') or '6'))})"
                    )
                    edit_message(chat_id, msg_id, render_body_text(text), reply_markup=panel_config_keyboard(idx))
                except Exception:
                    continue
        except Exception as exc:
            _terminal_log(f"[MANUAL-CONFIG-UI] status refresh error: {exc}")
        _MANUAL_PRESET_UI_STOP.wait(_MANUAL_PRESET_UI_INTERVAL)


def _manual_preset_ui_worker():
    while not _MANUAL_PRESET_UI_STOP.is_set():
        try:
            with _MANUAL_PRESET_UI_LOCK:
                watchers = list(_MANUAL_PRESET_UI_WATCHERS.values())
            for w in watchers:
                try:
                    idx = int(w.get("idx", -1))
                    key = str(w.get("preset_key") or "").lower()
                    chat_id = int(w.get("chat_id"))
                    msg_id = int(w.get("msg_id"))
                    panels = bot_settings.get("panels", []) or []
                    if idx < 0 or idx >= len(panels):
                        _manual_preset_ui_unwatch(chat_id, msg_id)
                        continue
                    panel = panels[idx]
                    if not isinstance(panel, dict):
                        continue
                    status = _normalize_legacy_login_status(
                        panel.get("login_status"),
                        bool(panel.get("username") and panel.get("password")),
                    )
                    # Avoid Telegram edit spam when local status has not changed.
                    if status == w.get("last_status"):
                        continue
                    w["last_status"] = status
                    with _MANUAL_PRESET_UI_LOCK:
                        _MANUAL_PRESET_UI_WATCHERS[(chat_id, msg_id)] = dict(w)
                    edit_message(
                        chat_id,
                        msg_id,
                        _manual_preset_editor_text(key, idx),
                        reply_markup=manual_preset_panel_keyboard(key),
                    )
                except Exception:
                    continue
        except Exception as exc:
            _terminal_log(f"[MANUAL-UI] status refresh error: {exc}")
        _MANUAL_PRESET_UI_STOP.wait(_MANUAL_PRESET_UI_INTERVAL)


