def _manual_find_matching_panel(preset_key):
    preset = MANUAL_LOGIN_PRESETS.get(str(preset_key).lower()) or {}
    matches = tuple(preset.get("match") or ())
    for idx, raw in enumerate(bot_settings.get("panels", []) or []):
        if not isinstance(raw, dict):
            continue
        hay = " ".join([
            str(raw.get("name") or ""),
            str(raw.get("panel_name") or ""),
            str(raw.get("panel_id") or ""),
            str(raw.get("login_url") or ""),
            str(raw.get("msg_link") or ""),
        ]).casefold()
        if any(token in hay for token in matches):
            return idx, raw
    return None, None


def _manual_fixed_preset_data(preset_key, existing=None):
    key = str(preset_key or "").lower()
    preset = MANUAL_LOGIN_PRESETS.get(key) or {}
    src = dict(existing) if isinstance(existing, dict) else {}
    # Preserve deployment-specific panel values when an existing matching panel
    # is found. These are the fixed values the admin should not edit from the UI.
    cfg = {
        "name": str(src.get("name") or src.get("panel_name") or preset.get("label") or key.upper()),
        "type": "Auto Captcha Panel",
        "status": "ON",
        "source_type": "MANUAL",
        "records": int(src.get("records", 0) or 0),
        "login_url": str(src.get("login_url") or preset.get("login_url") or "").strip(),
        "msg_link": str(src.get("msg_link") or preset.get("msg_link") or "").strip(),
        "num_col_name": "number",
        "num_col_idx": 3,
        "msg_col_name": "sms",
        "msg_col_idx": 6,
        "panel_preset": key,
        "login_status": "⚪ Credentials Not Set",
    }
    # Retain known deployment fields that are not credentials and may be required
    # by the existing login implementation.
    for field in ("login_field_user", "login_field_pass", "login_form_action", "captcha_field"):
        if field in src:
            cfg[field] = src[field]
    return cfg


def _normalize_legacy_login_status(raw_status, has_credentials=False):
    """Convert stale status labels from older builds into neutral current states."""
    s = str(raw_status or "").strip()
    low = s.casefold()
    if "pending auto-login" in low or "pending first login" in low:
        return "⚪ Not Checked Yet" if has_credentials else "⚪ Credentials Not Set"
    if s in {"✅ Active & Fetching", "✅ Login OK | ⚪ No SMS Data"}:
        return s
    return s or ("⚪ Not Checked Yet" if has_credentials else "⚪ Credentials Not Set")


def _manual_preset_editor_text(preset_key, idx=None):
    key = str(preset_key or "").lower()
    p = MANUAL_LOGIN_PRESETS.get(key) or {"label": key.upper()}
    _, existing = _manual_find_matching_panel(key)
    if existing:
        user_state = str(existing.get("username") or "")
        status_state = _normalize_legacy_login_status(existing.get("login_status"), bool(user_state and existing.get("password")))
        if str(existing.get("login_status") or "").strip() != status_state:
            existing["login_status"] = status_state
            try:
                save_db()
            except Exception:
                pass
        return render_body_text(
            f"🔐 <b>{html.escape(p.get('label', key.upper()))} MANUAL PANEL</b>\n\n"
            "All panel settings are fixed automatically.\n"
            "Only the Username and Password can be changed.\n\n"
            f"Current Username: <code>{html.escape(user_state or 'Not set')}</code>\n"
            f"Status: <b>{html.escape(status_state)}</b>\n\n"
            "Press <b>SET CREDENTIALS</b> to update login credentials.\n"
            "Opening this panel automatically checks login and SMS data."
        )
    return render_body_text(
        f"🔐 <b>{html.escape(p.get('label', key.upper()))} MANUAL PANEL</b>\n\n"
        "This preset keeps URL, CDR page and Number/SMS columns fixed.\n"
        "Only Username and Password are required."
    )


