def _run_zenex_range_self_test():
    """Offline regression tests for the documented Active Ranges payload shape."""
    sample = {
        "success": True,
        "cached": True,
        "message": "Global routing ranges fetched",
        "data": {
            "active_ranges": [
                {"range": "447384XXX", "service": "Telegram", "tag": "Premium", "hits": 312},
                {"range": "628123XXX", "service": "WhatsApp", "tag": "Physical", "hits": 245},
                {"range": "261348XXX", "service": "Instagram", "tag": "Premium", "hits": 91},
                {"range": "261368XXX", "service": "Facebook", "tag": "Premium", "hits": 87},
            ]
        }
    }
    data = sample["data"]["active_ranges"]
    assert isinstance(data, list) and len(data) == 4
    assert data[0]["hits"] == 312
    # Regression: a country omitted by Active-Ranges can still be recovered from
    # its international calling prefix (Instagram sample: +261 = Madagascar).
    _iso, _country, _flag = _country_display_from_number("261348000")
    assert _normalize_label(_country) == "madagascar", (_iso, _country)
    # Regression: duplicated provider rows for one range are a single route.
    # Their total must beat a different range whose individual row is larger.
    top = _select_top_range_from_candidates([
        (11, "447384XXX", "Premium", "Telegram"),
        (10, "447384XXX", "Physical", "Telegram"),
        (20, "447385XXX", "Premium", "Telegram"),
    ])
    assert top and top["range"] == "447384XXX" and top["hits"] == 21
    _terminal_log("[ZenEX] offline Active Ranges payload self-test: PASS")


def _fetch_zenex_active_ranges_for_analysis():
    """Fetch only the latest ZenEX Active-Ranges snapshot for live analysis.

    This function NEVER mutates configured country/range assignments. The separate
    three-minute APPLY worker remains the only automatic configuration mutation path.
    """
    keys = [str(k).strip() for k in bot_settings.get("zenex_keys", []) if str(k).strip()]
    if not keys:
        return {"ok": False, "status": "disabled", "message": "No ZenEX API key configured."}

    headers = {"mapikey": keys[0], "Accept": "application/json", "User-Agent": "FRD-Live-Analysis/1.0"}
    last_error = None
    for attempt in range(3):
        try:
            response = ZENEX_HTTP.get(
                f"{ZENEX_BASE_URL}/v1/active-ranges",
                headers=headers,
                timeout=(5, 15),
            )
            response.raise_for_status()
            candidate = response.json()
            if isinstance(candidate, dict) and candidate.get("success") is not True:
                raise ValueError(f"ZenEX Active Ranges API reported failure: {candidate.get('message', 'unknown error')}")

            active = None
            if isinstance(candidate, dict):
                containers = [candidate]
                data = candidate.get("data")
                if isinstance(data, dict):
                    containers.insert(0, data)
                for container in containers:
                    for key in ("active_ranges", "activeRanges", "ranges", "routes", "items", "results"):
                        value = container.get(key)
                        if isinstance(value, list):
                            active = value
                            break
                    if active is not None:
                        break
                    if isinstance(container.get("active"), list):
                        active = container.get("active")
                        break
                if active is None and isinstance(data, list):
                    active = data
            elif isinstance(candidate, list):
                active = candidate

            if not isinstance(active, list):
                raise ValueError("Invalid Active Ranges response format.")

            normalized = []
            for item in active:
                if not isinstance(item, dict):
                    continue
                route = str(
                    item.get("range", "") or item.get("prefix", "")
                    or item.get("number_range", "") or item.get("numberRange", "")
                ).strip()
                service = str(
                    item.get("service", "") or item.get("service_name", "")
                    or item.get("serviceName", "") or item.get("app", "")
                    or item.get("application", "") or item.get("sid", "")
                ).strip()
                if not route or not service:
                    continue
                row = dict(item)
                row.setdefault("range", route)
                row.setdefault("service", service)
                normalized.append(row)

            now_ts = time.time()
            _set_analyzed_active_ranges(normalized)
            analysis_state = _build_continuous_analysis_snapshot()
            _build_fast_ui_snapshot()
            # Persist only the prepared analysis brain. Full bot-state writes remain
            # reserved for actual state mutations, keeping live refreshes lightweight.
            _persist_prepared_analysis_state_async(analysis_state)
            try:
                _publish_active_menus(_fast_ui_snapshot(), force=True)
            except Exception:
                pass
            return {
                "ok": True,
                "analysis_version": int((analysis_state or {}).get("version", 0) or 0),
                "status": "live",
                "active_ranges": len(normalized),
                "fetched_at": now_ts,
                "api_cached": bool(candidate.get("cached")) if isinstance(candidate, dict) else False,
            }
        except (requests.RequestException, ValueError) as exc:
            last_error = str(exc)
            if attempt < 2:
                time.sleep(1 << attempt)

    return {"ok": False, "status": "error", "message": last_error or "Live analysis refresh failed."}


def zenex_live_analysis_listener():
    """Compatibility worker for the unified 3-minute intelligence scheduler.

    Recent global traffic is collected continuously by ``zenex_global_traffic_listener``.
    Full Active-Ranges research is intentionally owned by ``zenex_console_listener``
    so there is exactly one three-minute research/apply clock.
    """
    while not LOCAL_STOP.is_set():
        LOCAL_STOP.wait(5.0)


def zenex_console_listener():
    """Run the complete ZenEX research + ranking + apply cycle every three minutes.

    Each checkpoint refreshes recent Global Broadcast evidence, fetches a fresh
    Active-Ranges matrix, rebuilds canonical country/service/range analysis,
    validates the result, and only then applies changes. A successful manual
    Refresh resets the same clock
    through ``zenex_next_auto_refresh_at`` so the next automatic refresh occurs
    three minutes after the latest successful apply.
    """
    global zenex_next_auto_refresh_at
    last_enabled = bool(bot_settings.get("zenex_keys"))
    if not zenex_next_auto_refresh_at:
        zenex_next_auto_refresh_at = time.monotonic() + AUTO_RANGE_UPDATE_INTERVAL

    while True:
        try:
            enabled = bool(bot_settings.get("zenex_keys"))
            if not enabled:
                last_enabled = False
                time.sleep(1.0)
                continue

            # Re-arm the clock when ZenEX is enabled after being disabled.
            if not last_enabled:
                zenex_next_auto_refresh_at = time.monotonic() + AUTO_RANGE_UPDATE_INTERVAL

            now_mono = time.monotonic()
            if now_mono >= zenex_next_auto_refresh_at:
                # Full three-minute intelligence checkpoint. Recent global traffic
                # is refreshed first so the same cycle compares the freshest recent
                # activity against the freshly fetched Active-Ranges hit matrix.
                cycle_phases = []
                if INTELLIGENCE_TERMINAL:
                    _startup_console_log(f"[AUTO INTELLIGENCE] 3-MIN CYCLE START {time.strftime('%H:%M:%S')}")

                phase_started = time.perf_counter()
                try:
                    fetch_zenex_global_traffic(force=True)
                    traffic_phase_ok = bool(zenex_global_traffic_last_fetch_ok)
                except Exception as _traffic_exc:
                    traffic_phase_ok = False
                    _intelligence_terminal_log(f"[ZenEX] Recent traffic checkpoint refresh skipped: {_traffic_exc}")
                cycle_phases.append(("Recent Global Broadcast refresh", time.perf_counter() - phase_started, traffic_phase_ok))

                phase_started = time.perf_counter()
                result = refresh_configured_zenex_ranges(
                    force=True,
                    broadcast_all=False,
                    notify_admin=False,
                )
                cycle_phases.append(("Active-Ranges fetch + canonical analysis + Top-Hit apply", time.perf_counter() - phase_started, bool(result.get("ok"))))
                # The refresh function itself resets the next deadline only after
                # a successful apply. On failure, retry on the next fixed interval
                # without changing the currently-valid local snapshot.
                if not result.get("ok"):
                    zenex_next_auto_refresh_at = time.monotonic() + AUTO_RANGE_UPDATE_INTERVAL
                    if INTELLIGENCE_TERMINAL:
                        _startup_console_log(f"[AUTO INTELLIGENCE] 3-MIN CYCLE FAILED: {result.get('message', 'unknown error')}")
                    _print_intelligence_dashboard(trigger="3-MIN CYCLE FAILED", phase_times=cycle_phases, result=result)
                else:
                    phase_started = time.perf_counter()
                    ui_ok = True
                    try:
                        snap = _build_fast_ui_snapshot()
                        _publish_active_menus(snap, force=True)
                    except Exception as _ui_exc:
                        ui_ok = False
                        _intelligence_terminal_log(f"[FAST UI] publish warning: {_ui_exc}")
                    cycle_phases.append(("Prepared UI snapshot + menu publish", time.perf_counter() - phase_started, ui_ok))
                    _print_intelligence_dashboard(trigger="3-MIN CYCLE COMPLETE", phase_times=cycle_phases, result=result)
                    if INTELLIGENCE_TERMINAL:
                        _startup_console_log("[AUTO INTELLIGENCE] 3-MIN CYCLE COMPLETE — prepared state published and apply checkpoint finished.")

            last_enabled = enabled
        except Exception as exc:
            _terminal_log(f"[ZenEX] Auto-range listener error: {exc}")
            zenex_range_status = {
                "state": "error",
                "last_error": str(exc),
                "updated_at": time.time(),
            }
            zenex_next_auto_refresh_at = time.monotonic() + AUTO_RANGE_UPDATE_INTERVAL
            last_enabled = bool(bot_settings.get("zenex_keys"))

        time.sleep(0.25)

def _warm_zenex_ranges():
    """Synchronously initialize configured ZenEX state before user polling starts.

    Startup invariant: when ZenEX is configured, perform one fresh reconciliation
    immediately so each configured service receives its Top-3 countries and each
    selected country receives exactly its Top-1 range before the bot accepts users.
    If the provider is temporarily unavailable, the previously persisted valid
    state is retained and normal three-minute scheduled refresh resumes.
    """
    try:
        if not bot_settings.get("zenex_keys"):
            return {"ok": False, "status": "disabled", "message": "No ZenEX API key configured."}
        result = refresh_configured_zenex_ranges(force=True, broadcast_all=False, notify_admin=False)
        if not result.get("ok"):
            _terminal_log(f"[ZenEX] Startup warm refresh preserved existing state: {result.get('message', 'unknown error')}")
        else:
            _terminal_log(
                f"[ZenEX] Startup warm refresh OK: active={result.get('active_ranges', 0)} "
                f"matched={result.get('matched', 0)} updated={result.get('updated', 0)} "
                f"changed_top1={result.get('changed_pairs', 0)}"
            )
        return result
    except Exception as exc:
        _terminal_log(f"[ZenEX] Startup warm refresh error; existing state retained: {exc}")
        return {"ok": False, "status": "error", "message": str(exc)}

# ==========================================
# Fake OTP Forwarder (New Feature)
# ==========================================
def fake_otp_forwarder():
    """Continuously forward synthetic OTPs using analyzed service/country traffic.

    The forward path combines each Manual panel's last OTP-active number (for
    20 minutes) with the latest canonical Active-Ranges analysis. Auto rows:
      * services with more total traffic are selected more often;
      * within each service, every detected country remains eligible;
      * countries with more hits are selected more often;
      * for the selected service/country, the strongest (Top-1) range is used;
      * OTP length remains service-specific: normal Facebook = 5; FB Forgot
        and every other service = 6.

    Only configured service/country pairs with a current live snapshot are
    eligible.  All eligible pairs share one global hit-weighted quota; there
    is no Facebook-only percentage split.

    This function intentionally affects only synthetic/fake forwards to fw_groups.
    """
    def _read_hits(item):
        try:
            return max(0, int(float(
                item.get("hits", 0)
                or item.get("hit", 0)
                or item.get("count", 0)
                or item.get("access", 0)
                or (item.get("stats", {}) or {}).get("hits", 0)
                or 0
            )))
        except Exception:
            return 0

    def _effective_service(item):
        return _facebook_routing_service(item)

    def _country_for_item(item, rng):
        raw_country = str(
            item.get("country", "")
            or item.get("country_name", "")
            or item.get("countryName", "")
            or item.get("country_code", "")
            or item.get("countryCode", "")
            or item.get("iso", "")
            or item.get("cc", "")
            or item.get("countryISO", "")
            or item.get("country_iso", "")
            or ""
        ).strip()
        if raw_country:
            country = _country_full_name(raw_country) or raw_country
        else:
            try:
                _, country, _ = _country_display_from_number(rng)
            except Exception:
                country = ""
        country = str(country or "").strip()
        if not country or _normalize_label(country) in {"unknown", "xx", "other", "others"}:
            return ""
        return country

    def build_analyzed_service_country_pool():
        """Return one Top-1 range row for every analyzed service/country pair."""
        with _ANALYSIS_STATE_LOCK:
            active_ranges = list((_ANALYSIS_STATE.get("active_ranges", ()) or ()))

        if not active_ranges:
            active_ranges = list(_latest_validated_active_ranges_fallback() or [])

        # The canonical analysis snapshot also contains the provider's latest
        # service/country aggregates.  During startup the raw active-range list
        # can briefly contain only one configured service; merge missing pairs
        # from the same real-time snapshot so they are not silently starved.
        with _ANALYSIS_STATE_LOCK:
            analyzed_services = dict((_ANALYSIS_STATE.get("services", {}) or {}))
        existing_pairs = set()
        for raw_item in active_ranges:
            if not isinstance(raw_item, dict):
                continue
            raw_svc = _effective_service(raw_item)
            raw_cnt = _country_for_item(raw_item, str(raw_item.get("range", "") or raw_item.get("prefix", "")))
            if raw_svc and raw_cnt:
                existing_pairs.add((_normalize_label(raw_svc), _normalize_label(raw_cnt)))
        for service_row in analyzed_services.values():
            if not isinstance(service_row, dict):
                continue
            for country_row in (service_row.get("countries", ()) or ()):
                if not isinstance(country_row, dict):
                    continue
                service_name = str(service_row.get("service", "") or "").strip()
                country_name = str(country_row.get("country", "") or "").strip()
                top_range = str(country_row.get("top_range", "") or "").strip()
                if not service_name or not country_name or not top_range:
                    continue
                pair = (_normalize_label(_effective_service({"service": service_name, "tag": country_row.get("top_range_tag", "") })), _normalize_label(country_name))
                if pair not in existing_pairs:
                    active_ranges.append({"service": service_name, "country": country_name, "range": top_range, "tag": country_row.get("top_range_tag", ""), "hits": int(country_row.get("hits", 0) or 0)})
                    existing_pairs.add(pair)

        grouped = {}

        for item in active_ranges:
            if not isinstance(item, dict):
                continue
            if _is_bare_fb_clone_service(item) or _is_reserved_fb_clone_conflict(item):
                continue
            rng = str(
                item.get("range", "")
                or item.get("prefix", "")
                or item.get("number_range", "")
                or item.get("numberRange", "")
                or ""
            ).strip()
            if not rng:
                continue

            service = _effective_service(item)
            if not service:
                continue

            country = _country_for_item(item, rng)
            if not country:
                continue
            canonical = _configured_forward_service(service, country)
            if not canonical:
                continue

            hits = _read_hits(item)
            # A route with zero reported hits stays eligible with a minimal weight.
            weight = max(1, hits)
            service_key = _normalize_label(canonical)
            country_key = _normalize_label(country)
            group_key = (service_key, country_key)
            bucket = grouped.setdefault(group_key, {
                "service": canonical,
                "country": country,
                "country_hits": 0,
                "ranges": {},
            })
            bucket["country_hits"] += weight
            rb = bucket["ranges"]
            rb[rng] = int(rb.get(rng, 0) or 0) + weight

        rows = []
        for bucket in grouped.values():
            ranges = bucket.get("ranges") or {}
            if not ranges:
                continue
            top_range, top_range_hits = sorted(
                ranges.items(),
                key=lambda kv: (-int(kv[1]), str(kv[0]))
            )[0]
            rows.append({
                "service": bucket["service"],
                "country": bucket["country"],
                "country_hits": max(1, int(bucket["country_hits"])),
                "range": top_range,
                "range_hits": max(1, int(top_range_hits)),
            })

        return rows

    def _is_five_digit_service(service_name):
        # Only the normal Facebook service is a 5-digit service.
        # FB Forgot and every other service are strictly 6 digits.
        return _synthetic_otp_length_for_service(service_name) == 5

    def _configured_forward_service(service_name, country_name):
        """Return the canonical service only for an admin-configured pair."""
        canonical = _resolve_configured_service_name(service_name)
        if not canonical:
            return ""
        for setting_key in ("stex_services", "voltx_services", "zenex_services"):
            configured = bot_settings.get(setting_key, {}) or {}
            if not isinstance(configured, dict):
                continue
            for configured_service, countries in configured.items():
                if not isinstance(countries, dict):
                    continue
                if not _service_labels_match(canonical, configured_service):
                    continue
                # An explicitly configured service may temporarily have an
                # empty country map while its live provider snapshot is being
                # discovered. In that case accept only the provider's current
                # active country; a non-empty map remains an allow-list.
                if not countries:
                    return canonical
                if any(_country_labels_match(country_name, configured_country) for configured_country in countries):
                    return canonical
        return ""

    # The forwarding clock is a global minute-sized quota, never a per-service
    # random picker.  This keeps every eligible pair in one traffic pool.
    next_forward_at = time.monotonic()
    active_rate = None
    last_route_key = None
    minute_plan = []
    quota_carry = {}

    def _route_key(row):
        return (_normalize_label(row.get("service", "")), _normalize_label(row.get("country", "")))

    def _fair_minute_plan(rows, slots):
        total = sum(max(1, int(r.get("country_hits", 1) or 1)) for r in rows)
        if not rows or slots <= 0:
            return [], {}
        # Largest-remainder allocation gives an auditable quota while retaining
        # a carry so low-volume routes are not permanently starved when rate < N.
        raw = [
            (max(1, int(r.get("country_hits", 1) or 1)) * slots / total)
            + float(quota_carry.get(_route_key(r), 0.0) or 0.0)
            for r in rows
        ]
        quotas = [int(x) for x in raw]
        remain = slots - sum(quotas)
        order = sorted(range(len(rows)), key=lambda i: (-(raw[i] - quotas[i]), str(rows[i]["service"]), str(rows[i]["country"])))
        for i in order[:max(0, remain)]:
            quotas[i] += 1
        if remain < 0:
            for i in sorted(order, key=lambda j: (raw[j] - quotas[j], str(rows[j]["service"]), str(rows[j]["country"]))):
                if remain >= 0:
                    break
                if quotas[i] > 0:
                    quotas[i] -= 1
                    remain += 1
        for i, row in enumerate(rows):
            quota_carry[_route_key(row)] = max(-1.0, min(1.0, raw[i] - quotas[i]))
        quota_map = {_route_key(rows[i]): quotas[i] for i in range(len(rows))}
        # Weighted fair ordering; rotating ties prevents one pair owning every
        # first slot of every minute.
        planned = []
        remaining = list(quotas)
        scores = [0.0] * len(rows)
        cursor = 0
        for _ in range(slots):
            for i, row in enumerate(rows):
                if remaining[i]:
                    scores[i] += max(1, int(row.get("country_hits", 1) or 1))
            choices = [i for i, n in enumerate(remaining) if n]
            if not choices:
                break
            best_score = max(scores[i] for i in choices)
            tied = [i for i in choices if scores[i] == best_score]
            pick = next((i for i in tied if i >= cursor), tied[0])
            remaining[pick] -= 1
            scores[pick] -= total
            planned.append(rows[pick])
            cursor = (pick + 1) % len(rows)
        if last_route_key and len(planned) > 1 and _route_key(planned[0]) == last_route_key:
            for i in range(1, len(planned)):
                if _route_key(planned[i]) != last_route_key:
                    planned[0], planned[i] = planned[i], planned[0]
                    break
        return planned, quota_map

    while not LOCAL_STOP.is_set():
        try:
            enabled = bool(bot_settings.get("fake_otp_enabled", False))
            try:
                rate = max(0, int(bot_settings.get("fake_otp_rate", 0) or 0))
            except (TypeError, ValueError):
                rate = 0
            if not enabled or rate <= 0:
                active_rate = None
                next_forward_at = time.monotonic()
                LOCAL_STOP.wait(1)
                continue
            if rate != active_rate:
                active_rate = rate
                next_forward_at = time.monotonic()
                minute_plan = []
            delay = next_forward_at - time.monotonic()
            if delay > 0:
                LOCAL_STOP.wait(min(delay, 1.0))
                continue

            # A fresh analysis is published by the live-analysis worker every
            # minute; read it at the beginning of every forwarding minute.
            if not minute_plan:
                auto_rows = [dict(r, source="AUTO") for r in build_analyzed_service_country_pool()]
                manual_rows = _manual_forward_rows()
                seen = {_route_key(r): r for r in auto_rows}
                auto_avg = max(1, int(sum(max(1, int(r.get("country_hits", 1))) for r in auto_rows) / max(1, len(auto_rows))))
                for row in manual_rows:
                    service = _configured_forward_service(row.get("service", ""), row.get("country", ""))
                    if service:
                        candidate = {"source": "MANUAL", "service": service, "country": row.get("country", ""), "number": row.get("number", ""), "country_hits": auto_avg}
                        seen.setdefault(_route_key(candidate), candidate)
                eligible = []
                for row in seen.values():
                    _, service_emoji = get_service_info_html(row.get("service", ""), "")
                    if str(service_emoji or "").strip():
                        eligible.append(row)
                    else:
                        _debug_log(f"[ROUTE-SKIP] Service={row.get('service')} Country={row.get('country')} reason=emoji")
                if not eligible:
                    next_forward_at = time.monotonic() + 5
                    LOCAL_STOP.wait(5)
                    continue
                minute_plan, quotas = _fair_minute_plan(eligible, rate)
                total_hits = sum(max(1, int(r.get("country_hits", 1) or 1)) for r in eligible)
                _debug_log(f"[ROUTE-SUMMARY] configured_services={len(_configured_service_catalog())} active_countries={len({_normalize_label(r.get('country')) for r in eligible})} eligible_routes={len(eligible)} total_hits={total_hits} rate={rate}")
                for row in eligible:
                    _debug_log(f"[ROUTE] Service={row['service']} Country={row['country']} Hits={int(row.get('country_hits', 0))} Quota={quotas.get(_route_key(row), 0)}")

            selected = minute_plan.pop(0)
            service, country = selected["service"], selected["country"]
            if selected.get("source") == "MANUAL":
                num_str = str(selected.get("number") or "")
            else:
                rng = str(selected.get("range") or "")
                num_str = "".join(str(random.randint(0, 9)) if ch.upper() == "X" else ch for ch in rng)
                while len(num_str) < 10:
                    num_str += str(random.randint(0, 9))
            otp = ''.join(random.choices('0123456789', k=_synthetic_otp_length_for_service(service)))
            iso = _country_short_name(country) if country else "XX"
            _, prem_app_html = get_service_info_html(service, "")
            if prem_app_html:
                display_num = f"+{num_str}" if not num_str.startswith("+") else num_str
                msg_text = build_otp_group_message(display_num, iso, prem_app_html, "English")
                _otp_delivery_pool.submit(forward_otp_to_configured_groups, otp, msg_text, True)
                last_route_key = _route_key(selected)
            next_forward_at += 60.0 / rate
            if next_forward_at < time.monotonic():
                next_forward_at = time.monotonic()
        except Exception as e:
            _terminal_log(f"[FakeOTP] error: {e}")
            next_forward_at = time.monotonic() + 5
            LOCAL_STOP.wait(5)

def _restore_pending_withdrawals_from_firestore():
    """Restore pending/awaiting-TX withdrawal requests after a deployment restart."""
    if not db:
        return 0
    restored = 0
    try:
        if FieldFilter is not None:
            query = db.collection("withdrawals").where(
                filter=FieldFilter("status", "in", ["pending", "awaiting_txid"])
            )
        else:
            # Backward-compatible fallback for older google-cloud-firestore.
            query = db.collection("withdrawals").where("status", "in", ["pending", "awaiting_txid"])
        for doc in query.stream():
            req_id=str(doc.id)
            raw=doc.to_dict() or {}
            if req_id in pending_withdrawals:
                continue
            try:
                uid=int(raw.get("user_id"))
                pending_withdrawals[req_id]={
                    "user_id":uid,
                    "amount":float(raw.get("amount",0.0) or 0.0),
                    "method":str(raw.get("method","") or ""),
                    "number":str(raw.get("number","") or ""),
                    "full_name":str(raw.get("full_name",uid) or uid),
                    "balance_before":float(raw.get("balance_before",0.0) or 0.0),
                    "balance_after":float(raw.get("balance_after",0.0) or 0.0),
                    "status":str(raw.get("status","pending") or "pending"),
                    "group_chat_id":raw.get("group_chat_id") or bot_settings.get("w_group","") ,
                    "group_message_id":raw.get("group_message_id"),
                }
                if raw.get("transaction_id"):
                    pending_withdrawals[req_id]["transaction_id"]=str(raw["transaction_id"])
                if (str(raw.get("status", "pending") or "pending") == "pending"
                        or (str(raw.get("status", "") or "") == "awaiting_txid" and not bool(raw.get("firebase_debited", False)))):
                    pending_user_withdrawal_reservations[uid] = float(pending_user_withdrawal_reservations.get(uid, 0.0) or 0.0) + float(raw.get("amount", 0.0) or 0.0)
                restored += 1
            except Exception as exc:
                _terminal_log(f"[WITHDRAWAL] restore skipped {req_id}: {exc}")
        if restored:
            save_db_sync()
    except Exception as exc:
        _terminal_log(f"[WITHDRAWAL] restore failed: {exc}")
    return restored

def _enable_runtime_silence():
    """Disable stdout/stderr noise by default; set TERMINAL_LOG=1 to restore logs."""
    enabled = str(os.getenv("TERMINAL_LOG", "0")).strip().lower() in {"1", "true", "yes", "on"}
    if enabled:
        return
    try:
        devnull = open(os.devnull, "w", encoding="utf-8")
        sys.stdout = devnull
        sys.stderr = devnull
    except Exception:
        pass


def _post_startup_background_bootstrap():
    """Apply the initial analysis after polling has already started."""
    # Forwarding must remain available even when an optional startup task (such
    # as an external provider refresh) fails.  This worker manages its own
    # retry loop and uses the persisted active-range snapshot immediately.
    threading.Thread(target=fake_otp_forwarder, daemon=True, name="fake-otp-forwarder").start()
    try:
        # Publish the three production health lines before any optional provider
        # warm-up can delay them.
        local_health = _verify_local_storage_connection()
        if local_health.get("ok"):
            _startup_console_log("✅ Local Storage Connected: bot data + users list")
        else:
            _startup_console_log(f"❌ Local Storage Connection Failed: {local_health.get('message', 'unknown error')}")
        firebase_health = _verify_firebase_connection(timeout=3) if FIREBASE_INITIALIZED else {"ok": False, "message": FIREBASE_INIT_ERROR or "client initialization failed"}
        if firebase_health.get("ok"):
            _startup_console_log("✅ Firebase Connected")
        else:
            _startup_console_log(f"❌ Firebase Connection Check Failed: {firebase_health.get('message', 'unknown error')}")
        _startup_console_log("✅ Bot polling started; users can interact immediately")
        # Service catalog remains available through the Admin Panel; normal terminal startup is status-only.
        _debug_log("BACKGROUND bootstrap START")
        # The first apply is intentionally first in this worker.  It must never
        # delay Telegram update polling during process startup.
        _debug_log("BACKGROUND warm ZenEX START")
        _warm_zenex_ranges()
        _debug_log("BACKGROUND analysis START")
        _build_continuous_analysis_snapshot()
        _debug_log("BACKGROUND fast UI snapshot START")
        _build_fast_ui_snapshot()
        save_db()
        _flush_live_ui_registry(force=True)
        _print_intelligence_dashboard(trigger="STARTUP PREPARED STATE")

        threading.Thread(target=_fast_ui_worker, daemon=True, name="fast-ui-precompute").start()
        _restore_pending_withdrawals_from_firestore()
        threading.Thread(target=_balance_sync_worker, daemon=True, name="balance-sync").start()
        threading.Thread(target=assigned_route_cleanup_worker, daemon=True, name="assigned-route-cleanup").start()

        configured_wg = _normalize_telegram_chat_id(bot_settings.get("w_group", ""))
        if configured_wg:
            _probe_telegram_chat(configured_wg)

        for target, name in (
            (panel_monitor_thread, "panel-monitor"),
            (auto_captcha_panels_listener, "auto-captcha-panels-listener"),
            (manual_panels_listener, "manual-panels-listener"),
            (_manual_preset_ui_worker, "manual-preset-ui-status"),
            (_manual_panel_config_ui_worker, "manual-panel-config-ui-status"),
            (elite_sms_manual_listener, "elitesms-manual-listener"),
            (manual_lease_cleanup_worker, "manual-lease-cleanup"),
            (global_sms_listener, None),
            (stex_console_listener, None),
            (voltx_sms_listener, None),
            (voltx_console_listener, None),
            (zenex_sms_listener, None),
            (zenex_live_analysis_listener, "zenex-live-analysis"),
            (zenex_console_listener, None),
            (hourly_best_traffic_broadcast_listener, "hourly-best-broadcast"),
        ):
            threading.Thread(target=target, daemon=True, name=name).start() if name else threading.Thread(target=target, daemon=True).start()
        _run_otp_language_self_test()
        _run_zenex_range_self_test()
    except Exception as exc:
        _terminal_log(f"[STARTUP] Background initialization error: {exc}")


def _telegram_polling_loop(executor, polling_ready):
    """Run Telegram polling in its own thread and show polling errors."""
    offset = None

    print("🚀 Telegram poller thread started...", flush=True)

    # Tell main() that the polling thread is alive.
    polling_ready.set()

    while True:
        try:
            updates = _telegram_get_updates(offset)

            if updates and "result" in updates:
                for update in updates["result"]:
                    offset = update["update_id"] + 1

                    if "message" in update:
                        msg = update["message"]

                        _debug_log(
                            f"DISPATCH message "
                            f"update_id={update['update_id']} "
                            f"chat={msg.get('chat', {}).get('id')}"
                        )

                        executor.submit(handle_message, msg)

                    elif "callback_query" in update:
                        cb = update["callback_query"]

                        _debug_log(
                            f"DISPATCH callback "
                            f"update_id={update['update_id']} "
                            f"chat={(cb.get('message') or {}).get('chat', {}).get('id')}"
                        )

                        executor.submit(handle_callback, cb)

        except Exception as e:
            # Show the real Telegram/network error instead of silently hiding it.
            print(
                f"❌ TELEGRAM POLLING ERROR: {type(e).__name__}: {e}",
                flush=True
            )

            _debug_log(
                f"TELEGRAM POLLING ERROR: {type(e).__name__}: {e}"
            )

            # Prevent a rapid error loop.
            LOCAL_STOP.wait(2.0)


def main():
    global BOT_USERNAME

    # Show startup immediately.
    print("========================================", flush=True)
    print("🤖 BOT STARTING...", flush=True)
    print("========================================", flush=True)

    _enable_runtime_silence()

    if not _acquire_bot_instance_lock():
        print(
            "⚠️ Bot not started: another local process is already polling this token.",
            flush=True
        )
        _startup_console_log(
            "⚠️ Bot not started: another local process is already polling this token."
        )
        return

    _debug_log("MAIN START")

    _bootstrap_premium_flags_from_local_txt()

    _debug_log("CONFIG READY; starting Telegram poller")

    _FAST_UI_DIRTY.clear()
    _ANALYSIS_DIRTY.clear()

    if "_ANALYSIS_FORCE_DIRTY" in globals():
        _ANALYSIS_FORCE_DIRTY.clear()

    _UI_PUBLISH_DIRTY.clear()

    executor = ThreadPoolExecutor(
        max_workers=32,
        thread_name_prefix="update-handler"
    )

    polling_ready = threading.Event()

    # Start Telegram polling first.
    polling_thread = threading.Thread(
        target=_telegram_polling_loop,
        args=(executor, polling_ready),
        daemon=True,
        name="telegram-poller",
    )

    polling_thread.start()

    print("⏳ Waiting for Telegram poller...", flush=True)

    _debug_log(
        "Telegram poller thread STARTED; waiting for readiness"
    )

    polling_ready.wait(timeout=2.0)

    if polling_ready.is_set():
        print("✅ Telegram poller is ready.", flush=True)
    else:
        print(
            "⚠️ Telegram poller did not report ready within 2 seconds.",
            flush=True
        )

    _terminal_log(
        f"🤖 Bot is starting... @{BOT_USERNAME}"
    )

    _debug_log(
        "POLLING READY; launching background bootstrap"
    )

    # Start background work after Telegram polling has started.
    threading.Thread(
        target=_post_startup_background_bootstrap,
        daemon=True,
        name="post-startup-bootstrap",
    ).start()

    print(
        "🟢 Bot is running. Waiting for Telegram messages...",
        flush=True
    )

    # Keep process alive.
    try:
        while not LOCAL_STOP.wait(1.0):
            pass

    except KeyboardInterrupt:
        print("🛑 Bot stopping...", flush=True)

        LOCAL_STOP.set()

        try:
            executor.shutdown(
                wait=False,
                cancel_futures=True
            )

        except TypeError:
            executor.shutdown(wait=False)

        except Exception as e:
            print(
                f"⚠️ Shutdown error: {e}",
                flush=True
            )


if __name__ == "__main__":
    main()
